VALUES ('gap-press-overhaul-dependency', NULL, NULL, 'Only Baxter Hydraulics technicians can re-seal and re-pressurize the press 7 accumulator; the plant depends on them for it.', 'Medium', 'NonBlocking', 'Open', 'knowledge-engineer', '2026-05-20T09:00:00-05:00', 'Shadow the next two Baxter overhauls and write the re-pressurization procedure.', 'eval-current', 'urn:effortless:pko-extension#KnowledgeGap', NULL, NULL, NULL, NULL, NULL) ON CONFLICT (knowledge_gap_id) DO UPDATE SET procedure_version = EXCLUDED.procedure_version, step = EXCLUDED.step, statement = EXCLUDED.statement, severity = EXCLUDED.severity, blocking_kind = EXCLUDED.blocking_kind, status = EXCLUDED.status, owner_role = EXCLUDED.owner_role, identified_at = EXCLUDED.identified_at, resolution_plan = EXCLUDED.resolution_plan, evaluation_context = EXCLUDED.evaluation_context, semantic_type_iri = EXCLUDED.semantic_type_iri, gap_cause = EXCLUDED.gap_cause, holder_declined_to_share = EXCLUDED.holder_declined_to_share, siloed_within = EXCLUDED.siloed_within, drawn_out_by_session = EXCLUDED.drawn_out_by_session, codified_as_fragment = EXCLUDED.codified_as_fragment;

