VALUES ('gap-mixer2-twin-drive-isolation', 'loto-v2.0.0', NULL, 'Nobody at the plant or at any provider holds a verified isolation sequence for mixer 2''s twin-drive conversion.', 'Medium', 'NonBlocking', 'Open', 'knowledge-engineer', '2026-05-20T09:00:00-05:00', 'Critical-incident interviews with the technicians who performed the conversion.', 'eval-current', 'urn:effortless:pko-extension#KnowledgeGap', NULL, NULL, NULL, NULL, NULL) ON CONFLICT (knowledge_gap_id) DO UPDATE SET procedure_version = EXCLUDED.procedure_version, step = EXCLUDED.step, statement = EXCLUDED.statement, severity = EXCLUDED.severity, blocking_kind = EXCLUDED.blocking_kind, status = EXCLUDED.status, owner_role = EXCLUDED.owner_role, identified_at = EXCLUDED.identified_at, resolution_plan = EXCLUDED.resolution_plan, evaluation_context = EXCLUDED.evaluation_context, semantic_type_iri = EXCLUDED.semantic_type_iri, gap_cause = EXCLUDED.gap_cause, holder_declined_to_share = EXCLUDED.holder_declined_to_share, siloed_within = EXCLUDED.siloed_within, drawn_out_by_session = EXCLUDED.drawn_out_by_session, codified_as_fragment = EXCLUDED.codified_as_fragment;

