VALUES ('aq-pkm4-q16', 'maintenance-technician', 'loop-06', 'Which step is the remedy for a given error, and which errors have none?', 'An error that keeps occurring with no remedy step is being handled by whoever happens to be on shift.', FALSE, 'Errors.HasNoRemedyStep=3/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

