VALUES ('aq-pkm4-q07', 'plant-safety-officer', 'loop-06', 'Which issues were encountered during this execution, and were they solved?', 'An issue with no recorded solution will be met again by someone who does not know it happened.', FALSE, 'IssueOccurrences.HasNoRecordedSolution=1/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

