VALUES ('aq-pkm1-q03', 'process-steward', 'loop-06', 'Which conditions have tended to accompany issues during execution?', 'Issues that coincide with a failed precondition point at the precondition, not the person.', FALSE, 'IssueOccurrences.CoincidedWithFailedCondition=1/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm4-q01', 'maintenance-technician', 'loop-06', 'Before starting this procedure, which regulation requires it, which document is kept for compliance, and which requirements are regulatory?', 'The compliance document and the way the work is actually done are different artifacts; a technician needs to know which is which.', FALSE, 'Requirements.IsRegulatoryRequirement=3/16', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm3-q01', 'maintenance-technician', 'loop-06', 'For this procedure, does the specification say which steps, in what order, under which conditions, and what to do when things go wrong?', 'An agent or a new hire can only execute what is actually specified.', FALSE, 'ProcedureVersions.IsUnderSpecifiedForExecution=7/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm1-q01', 'process-steward', 'loop-06', 'Which steps make up this process, and which procedures exist only as a title and a document?', 'A procedure with no specified steps is knowledge the organization believes it holds but cannot show.', FALSE, 'Procedures.HasNoExplicitSteps=5/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q6-steward-doc-lag', 'process-steward', 'loop-06', 'Has the documentation a live version rests on fallen behind how we now run it?', 'Static prose drifts from practice; the drift is only visible if something compares the dates.', FALSE, 'ProcedureVersions.DocumentLagsPractice=2/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q6-steward-instruction-only', 'process-steward', 'loop-06', 'Which steps carry nothing but a one-line instruction, with none of the checks and judgment behind it?', 'The line that says cut main power leaves out every judgment a technician makes to do it safely.', FALSE, 'Steps.HasInstructionOnly=25/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q6-steward-mixed-performers', 'process-steward', 'loop-06', 'Which procedure versions mix human steps with software or AI steps?', 'Hand-offs between people and machines are where accountability gets lost.', FALSE, 'ProcedureVersions.MixesHumanAndSoftwareSteps=3/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q6-steward-adoption', 'process-steward', 'loop-06', 'Which organizations adopted our procedures, did each state whether as is, extended or as a reference, and which procedures instantiate a template?', 'An adoption whose mode nobody recorded cannot be governed: nobody knows which local changes are allowed.', FALSE, 'ProcedureAdoptions.IsAdoptionModeUnstated=1/3; Procedures.IsTemplateInstance=1/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q6-steward-outcome-criteria', 'process-steward', 'loop-06', 'Does every procedure say what outcome counts as success and what counts as failure?', 'Without a failure criterion, an execution can never be judged to have failed.', FALSE, 'Procedures.HasNoFailureCriterion=8/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q6-steward-feedback', 'process-steward', 'loop-06', 'Which feedback criticizes the procedure itself, and is any of it not carried into a change request?', 'Feedback about the procedure that stops at the feedback form is a known defect left in place.', FALSE, 'UserFeedback.IsUnactionedProcedureCritique=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q6-steward-role-scope', 'process-steward', 'loop-06', 'Is anyone still assigned to a role for a procedure version we have retired?', 'An assignment scoped to a deprecated version keeps authority alive over a procedure nobody should run.', FALSE, 'RoleAssignments.IsScopedToRetiredVersion=1/36', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-knowledge-levels', 'knowledge-engineer', 'loop-08', 'Does each level of process knowledge, operational, tactical and strategic, have its own way of capturing both what can be written down and what can only be passed on in person?', 'A strategy that works for the technician''s how does nothing for the planner''s heuristics or the executive''s why; a level with no tacit strategy loses that knowledge when its holders leave.', FALSE, 'LevelCaptureStrategies.ContradictsKnowledgeForm=1/5; ProcessKnowledgeLevels.LacksCaptureStrategyForEitherForm=1/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-planning-pyramid', 'knowledge-engineer', 'loop-08', 'Is every statement about a procedure filed at the level of the planning pyramid that answers its kind of question?', 'A why filed among the operational how-to steps is invisible to the executive who owns it and noise to the technician reading the steps.', FALSE, 'ProcessLevelStatements.IsFiledAtWrongLevel=1/8', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-tech-operational-level', 'maintenance-technician', 'loop-08', 'For each step, does the procedure tell me what it follows, what it depends on and what must hold before I carry on?', 'Those three things are the operational level; a step missing any of them leaves the order to memory.', FALSE, 'Steps.StatesOperationalKnowledge=3/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm1-q05', 'plant-operations-manager', 'loop-08', 'Where are the bottlenecks in our lockout and release work: which step waits on a resource that is allocated less than it is demanded, and what are we doing about it?', 'Paused lockouts waiting on padlocks and verifiers are a resource problem, not a technician problem; I can only fix what I can see.', FALSE, 'Steps.IsBottleneckStep=2/41; TacticalResourceAllocations.IsBottleneck=2/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm1-q06', 'vp-engineering', 'loop-08', 'Why does each of our procedures exist, what value does it create for our mission, and what trade-offs does it make?', 'I decide which procedures to fund and which to relax; a procedure nobody can justify, or one whose costs nobody wrote down, cannot be weighed.', FALSE, 'Procedures.HasNoStatedReasonForExisting=6/10; ProcessStrategicAlignments.StatesNoTradeOff=1/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm1-q07', 'vp-engineering', 'loop-08', 'How does each procedure''s measured performance connect to the business outcomes I am accountable for?', 'A change failure rate matters to me because it moves platform availability; a measure tied to nothing is activity, not performance.', FALSE, 'Procedures.MeasuresPerformanceWithoutBusinessLink=1/10; ProcessOutcomeMeasures.IsUnlinkedToBusinessOutcome=1/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-pm-stages', 'platform-product-manager', 'loop-08', 'Which stages group the release process''s steps, who owns each stage, and is any stage without an owner who is actually there, or without steps?', 'I run the process by stage; a rollout stage owned by a role nobody holds is where releases stall.', FALSE, 'ProcessStages.IsUnownedOrEmptyStage=2/7; ProcessStages.OwnerHasNoHolder=1/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm3-q04', 'platform-infrastructure-engineer', 'loop-08', 'Which of our operations help each other, which require each other, and which work against each other?', 'When a deployment destabilizes the ledger integrations during the close, the two operations are coupled whether or not anyone wrote it down.', FALSE, 'Procedures.IsHinderedByAnotherOperation=2/10; ProcessInterdependencies.IsHinderingDependency=2/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-steward-lenses', 'process-steward', 'loop-08', 'Is each procedure organized for more than one stakeholder, and is every stakeholder''s view projected from the one current specification rather than kept as a separate copy?', 'A procedure organized for auditors alone fails the trainer; an executive deck copied from the 2019 checklist silently contradicts the procedure it summarizes.', FALSE, 'ProcedureLensViews.IsDisconnectedSilo=4/15; Procedures.PrivilegesSingleStakeholderView=1/10; StakeholderLenses.NeedsComplianceEvidence=1/9; StakeholderLenses.NeedsExceptionHandling=3/9; StakeholderLenses.NeedsMetrics=4/9; StakeholderLenses.NeedsStepGuidance=2/9; StakeholderLenses.NeedsStructuredConstraints=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-safety-granularity', 'plant-safety-officer', 'loop-08', 'Is each view written at the level of detail its readers need, and does any procedure version mix whole activities with single actions at the same level?', 'Training needs every action; a planner drowning in actions misses the category; a checklist that says ''do the maintenance'' beside ''apply locks'' hides the hard part.', FALSE, 'ProcedureLensViews.IsGranularityMisfit=2/15; ProcedureVersions.MixesGranularityAtOneLevel=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q31', 'platform-product-manager', 'loop-08', 'What does this process look like at step-level detail compared with its category, and does any reader need a resolution the procedure cannot give?', 'Training needs steps and planning needs the category; a procedure that exists only as a PDF cannot serve the first.', FALSE, 'Procedures.HasStepAndCategoryResolutions=5/10; Procedures.IsMissingDemandedResolution=2/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-safety-context-scoping', 'plant-safety-officer', 'loop-08', 'Where a step matters differently depending on who does it, what is on hand or what is going on, does the procedure say where that holds?', 'A night-shift verification by a deputy and a day-shift verification by me are not the same safeguard; unscoped, the difference is lost.', FALSE, 'ApplicabilityScopes.StatesConditions=4/5; Steps.IsContextSensitiveButUnscoped=1/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q21', 'internal-compliance-auditor', 'loop-08', 'Under which business unit, geography, customer segment or regulatory regime does each variant of a procedure apply, and when does it stop applying?', 'I cannot accept a variant as evidence of compliance if nothing says where it is allowed to replace the standard procedure.', FALSE, 'SituationalVariants.DivergesWithoutStatedConditions=2/4; SituationalVariants.HasNoApplicabilityDimension=1/4; SituationalVariants.ScopeStatesConditions=2/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-organize-before-model', 'knowledge-engineer', 'loop-08', 'Was every piece of collected material organized into a scheme before it was modeled into a procedure version?', 'Encoding an unorganized document excerpt means modeling before knowing what is being modeled; the conveyor procedure was imported that way.', FALSE, 'CollectedSourceMaterials.IsModeledBeforeOrganized=1/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-steward-scheme-frames', 'process-steward', 'loop-08', 'Does each organizing scheme hold the different kinds of knowledge collected about its procedures in one frame, and has it been refined as new material came in?', 'A glossary built from document excerpts alone leaves the veterans'' transcripts somewhere else; a scheme never refined after new field notes is organizing last year''s understanding.', FALSE, 'Vocabularies.IsFrozenDespiteNewCollection=1/12; Vocabularies.IsSingleKindFrame=1/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-vocabulary-first', 'knowledge-engineer', 'loop-08', 'For each domain, was vocabulary control in place before ontology modeling began, and did we adopt standards in order from vocabularies to lightweight ontologies to process and decision models?', 'Classes built before the terms are controlled bake uncontrolled wordings into axioms; adopting DMN before the procedure ontology it decides over leaves decisions with nothing to refer to.', FALSE, 'OntologyProfiles.SkipsAdoptionPath=1/27; Vocabularies.OntologyPrecededVocabularyControl=1/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-practitioner-terms', 'knowledge-engineer', 'loop-08', 'Is each controlled concept organized around the words practitioners actually use, and do the different phrasings of one activity in different sources all reconcile to it?', 'Technicians say LOTO; a scheme organized around ''lockout/tagout'' alone reads like the SOP and not like the floor. The runbook''s ''release gate check'' is the same review as ''sign-off'' but nothing says so.', FALSE, 'VocabularyTerms.HasUnreconciledVariantPhrasings=4/44; VocabularyTerms.IsOrganizedAroundOfficialTerm=2/44', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-canonical-resolution', 'knowledge-engineer', 'loop-08', 'Does every variant wording resolve through the labels to exactly one canonical concept?', 'A wording that resolves to nothing is uncontrolled; a wording registered for two concepts cannot be normalized by anything downstream.', FALSE, 'SourceTermMentions.IsUncontrolledWording=4/25; TermLabelVariants.IsAmbiguousLabel=2/53', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q09', 'internal-compliance-auditor', 'loop-08', 'List every process in which a compliance-review role takes part.', 'My evidence request goes to every process a compliance reviewer touches; finding them by job title misses the safety officer and the release manager.', FALSE, 'Procedures.InvolvesComplianceReviewRole=3/10; Roles.HasComplianceReviewCapability=4/33; Steps.AssignedRoleDoesComplianceReview=4/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-auditor-role-query', 'internal-compliance-auditor', 'loop-08', 'When I query for a role through the role vocabulary, does it find every process that mentions that role in other words?', 'The field notes say ''the tech''; if the role vocabulary does not carry that wording, my query for maintenance technicians misses the night-shift lockout.', FALSE, 'Roles.IsMissedByPhraseQuery=1/33', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q28', 'process-steward', 'loop-08', 'Which departments contain which roles, and which roles sit directly in a company or division with no department?', 'A role with no department has no departmental owner to keep its vocabulary entry and responsibilities current.', FALSE, 'Roles.IsNotHousedInDepartment=21/33', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q29', 'process-steward', 'loop-08', 'Which roles are specializations of others, and is every senior version of a role recorded as a specialization of it?', 'A query for technicians should find the senior technician too; that works only if the hierarchy says a senior technician is a technician.', FALSE, 'Roles.HasSpecializations=2/33; Roles.IsSeniorVariantNotSpecialization=1/33', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-capability-tags', 'knowledge-engineer', 'loop-08', 'Does every role carry capability tags, and is every tag drawn from the controlled agent-capability scheme?', 'An AI agent is matched to work by capability; a tag borrowed from a plant''s local quality list cannot be matched against anything.', FALSE, 'RoleCapabilityTags.IsTagOutsideCapabilityScheme=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q30', 'platform-product-manager', 'loop-08', 'Which specific process types fall under each functional domain, through which narrower groups?', 'I plan the roadmap by domain and need to find every process type beneath it without knowing their names.', FALSE, 'ProcedureTypes.HasNarrowerTypes=11/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-steward-taxonomy-consistency', 'process-steward', 'loop-08', 'Is every procedure categorized at a defined process type, and can every node of the taxonomy be reached by navigating down from a functional domain?', 'A new procedure filed straight under ''Operations'' is categorized inconsistently with its peers; a branch hanging off nothing cannot be found by browsing, by people or by AI.', FALSE, 'ProcedureTypes.BroaderIsDetached=1/17; ProcedureTypes.IsDetachedFromTaxonomy=1/17; ProcedureTypes.IsUnreachableByNavigation=2/17; Procedures.IsInconsistentlyCategorized=1/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-faceted-groupings', 'knowledge-engineer', 'loop-08', 'Does each grouping in the taxonomy name the facet that distinguishes it, and do its members actually share that distinction?', 'A grouping whose members lack the distinction it claims is a convenience bucket; it will mislead everyone who navigates by it.', FALSE, 'ProcedureTypes.IsArbitraryGrouping=1/17; Procedures.LacksTypeDistinction=2/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-skos-structure', 'knowledge-engineer', 'loop-08', 'Is every concept placed in its scheme with a definition, a scope note, a direct broader concept and its associative relations, and is any direct link really an indirect one?', 'A broader link that skips a level asserts a hierarchy the scheme does not have and double-counts every query that walks it.', FALSE, 'TermRelations.AssertsIndirectLinkAsDirect=1/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-steward-vocabulary-coverage', 'process-steward', 'loop-08', 'Does every procedure with steps have a controlled vocabulary whose metadata, its governing role and establishment, is managed?', 'A glossary nobody governs is a document, not vocabulary control.', FALSE, 'Procedures.LacksManagedControlledVocabulary=1/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-steward-terminological-drift', 'process-steward', 'loop-08', 'Has what we mean by any controlled term changed since its definition was last revised, and which terms changed shape over the years?', 'A definition of ''release'' written when an engineer copied a build to production gives answers that were true two years ago.', FALSE, 'TermMeaningChanges.IsStructuralChange=2/3; VocabularyTerms.HasStaleDefinition=1/44; VocabularyTerms.HasStructuralSenseShiftAcrossYears=2/44', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q26', 'knowledge-engineer', 'loop-08', 'Which adopted external terms have since been deprecated by their source standard?', 'A deprecated term still resolves, so nothing breaks until a consumer upgrades the standard and our mappings point at nothing.', FALSE, 'ExternalStandardTerms.DeprecatedBySource=6/9; ExternalStandardTerms.IsAdoptedButDeprecated=6/9; ExternalStandardTerms.StillResolves=9/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-rehoming', 'knowledge-engineer', 'loop-08', 'For each deprecated external term, did we update the alignment, take the term into our namespace if we still need it, link it to the original, cut a release for it, and propagate identifier changes?', 'Each skipped step leaves a different failure: stale documentation, a term that vanishes, a lost identity, an unversioned change, or queries against an old prefix.', FALSE, 'ExternalStandardTerms.HasUnpropagatedIdentifierChange=1/9; ExternalStandardTerms.IsAlignmentStaleAfterDeprecation=1/9; ExternalStandardTerms.IsNeededDeprecatedTermNotRehomed=1/9; ExternalStandardTerms.IsRecentDeprecation=3/9; ExternalStandardTerms.IsRehomedWithoutIdentityLink=1/9; ExternalStandardTerms.IsRehomedWithoutNewRelease=1/9; ExternalStandardTerms.ModelStillNeedsTerm=8/9; ExternalStandardTerms.RehomingKeptExternalNamespace=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-standard-change-rates', 'knowledge-engineer', 'loop-08', 'How fast does each standard we reuse change, and have we reviewed our dependency on the fast-changing ones recently enough?', 'FOAF has barely moved in a decade, schema.org deprecates terms every few releases, DCAT went through a major revision; one review cadence cannot fit all three.', FALSE, 'OntologyProfiles.IsReviewOverdueForChangeRate=1/27; OntologyProfiles.RequiresFrequentReview=2/27', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-release-ai-grounding', 'release-manager', 'loop-08', 'When an AI model labels workflow status for our releases, does it return only the governed status values, and is the vocabulary it is grounded in formal enough to use?', 'An ungrounded model calls the same status live, shipped and current; my dashboards count three statuses where there is one.', FALSE, 'AiLabelingRuns.GroundedInNonMachineReadableScheme=1/3; AiLabelingRuns.GroundingSchemeIsMachineAccessible=1/3; AiLabelingRuns.IsUngroundedSynonymSprawl=1/3; SourceTermMentions.IsNonCanonicalGeneratedValue=5/25; Vocabularies.IsMachineAccessible=10/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-resource-organization', 'knowledge-engineer', 'loop-08', 'Is every resource with content also typed, findable and linked, so its structure counts as much as what it says?', 'A PDF with no artifact type, no keywords and no link to a step is content nobody will find when it is needed.', FALSE, 'Resources.IsContentWithoutOrganization=14/19', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-ke-value-formats', 'knowledge-engineer', 'loop-08', 'Does every value an execution records have the datatype and format its step variable declares?', 'A risk report pasted into chat as text is not the machine-readable report the approval gate is specified to read.', FALSE, 'ExecutionEntities.ViolatesDeclaredDatatypeOrFormat=1/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q8-steward-shared-concerns', 'process-steward', 'loop-08', 'Is a concern that cuts across plant and engineering work, such as quality control or validation, defined once and shared, or defined again inside each domain?', 'Optimization, quality control and validation are the same problems in both disciplines; defining them twice splits the knowledge along the org chart.', FALSE, 'TermLabelVariants.IsCrossSchemeDuplicatePref=2/53', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-steward-lifecycle-feedback', 'process-steward', 'loop-09', 'At which stage of the knowledge lifecycle, from collecting to operationalizing, are we hearing nothing back?', 'Feedback that only arrives once knowledge is in operation means mistakes made while storing or codifying it surface on the shop floor.', FALSE, 'EncodingLifecycleStages.IsStageWithoutFeedback=2/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ke-knowledge-infrastructure', 'knowledge-engineer', 'loop-09', 'Which systems holding our process knowledge are silos, which modeling tools, repositories or AI platforms are linked to nothing, and which graph platforms are missing a capability?', 'Knowledge locked in a proprietary binder or a modeling tool nobody connected never reaches the people and agents who need it.', FALSE, 'KnowledgeConsumerSystems.ExportsStandardFormat=4/8; KnowledgeConsumerSystems.HasGraphAlgorithms=2/8; KnowledgeConsumerSystems.HasMachineLearning=3/8; KnowledgeConsumerSystems.HasMetadataSchema=4/8; KnowledgeConsumerSystems.HasOntology=3/8; KnowledgeConsumerSystems.HasReasoner=2/8; KnowledgeConsumerSystems.HasSemanticStorage=2/8; KnowledgeConsumerSystems.HasTaxonomy=3/8; KnowledgeConsumerSystems.HasThesaurus=2/8; KnowledgeConsumerSystems.HoldsProcedureKnowledge=5/8; KnowledgeConsumerSystems.IsImmatureGraphPlatform=1/8; KnowledgeConsumerSystems.IsKnowledgeSilo=1/8; KnowledgeConsumerSystems.IsUnlinkedToolchainComponent=1/8', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ke-consistent-spread', 'knowledge-engineer', 'loop-09', 'Does every system that consumes a procedure hold its current version, synced since its last change, fed from the shared model, with provenance intact?', 'A tablet still showing the 2019 checklist, or a release bot reading a copy of the runbook, disagrees with the procedure the moment it changes.', FALSE, 'ConsumerSystemSyncs.CarriesProvenance=5/6; ConsumerSystemSyncs.DropsProvenanceInTransit=1/6; ConsumerSystemSyncs.IsAiFedFromForkedCopy=1/6; ConsumerSystemSyncs.IsBehindCanonicalVersion=1/6; ConsumerSystemSyncs.PredatesVersionChange=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ailead-integrations', 'ai-enablement-lead', 'loop-09', 'Is every agent integration in the central registry, on a shared pathway, delivering knowledge at run time, against a graph somebody governs?', 'An integration nobody registered or a one-off script is invisible when the procedure changes; an agent against an ungoverned graph repeats whatever is in it.', FALSE, 'AgentIntegrations.IsDeployedOnUngovernedGraph=1/7; AgentIntegrations.IsOneOffConnection=2/7; AgentIntegrations.IsShadowIntegration=1/7; AgentIntegrations.SnapshotIsGoverned=5/7; Agents.LacksRuntimeKnowledgeIntegration=1/55; GroundingSnapshots.IsGoverned=2/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ke-reasoner-before-ai', 'knowledge-engineer', 'loop-09', 'Was every graph we served to AI found consistent and fully materialized by the reasoner before serving, and did any run blow its budget or drop axioms to fit it?', 'A language model will not notice that the context it was handed contradicts itself; the reasoner has to, before the model sees it.', FALSE, 'GroundingSnapshots.ServedBeforeMaterialization=2/3; GroundingSnapshots.ServedWithoutConsistencyCheck=1/3; ReasonerRuns.IsConsistent=3/5; ReasonerRuns.IsRichnessTractabilityFailure=2/5; ReasonerRuns.PassesSchemaButFailsReasoner=1/5; ReasonerRuns.SchemaValidationPassed=4/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ailead-stale-retrieval-graph', 'ai-enablement-lead', 'loop-09', 'Is the graph our assistants retrieve from serving any ended role assignment or any deprecated procedure version as if it were current?', 'An assistant that names the superseded classifier as the one scoring risk is wrong with full confidence, because the graph told it so.', FALSE, 'GroundingSnapshots.ServesDeprecatedAsCurrent=1/3; GroundingSnapshots.ServesStaleRoleAssignments=2/3; SnapshotAssertions.IsStaleRoleAssertion=2/15; SnapshotAssertions.PresentsDeprecatedAsCurrent=1/15; SnapshotAssertions.SourceAssignmentIsCurrent=13/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

