VALUES ('q9-ke-served-assertions', 'knowledge-engineer', 'loop-09', 'Does every assertion we serve to retrieval link back to where it came from, carry a readable identifier, and carry a Dublin Core title and description?', 'An assertion about a blank node with no source cannot be cited in an answer, and cannot be checked by the person the answer is for.', FALSE, 'SnapshotAssertions.HasOpaqueIdentifier=2/15; SnapshotAssertions.LacksDublinCore=2/15; SnapshotAssertions.LacksProvenance=1/15; SnapshotAssertions.SnapshotIsReasoned=12/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-release-agent-category', 'release-manager', 'loop-09', 'For every agent the graph says holds a role, can it tell me by inference whether that agent is a person or software?', 'When a release goes wrong I need to know whether a human or a pipeline was accountable, and a name alone does not say.', FALSE, 'Agents.CategoryNotAvailableAsInference=2/55; SnapshotAssertions.IsInferred=2/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ke-segments', 'knowledge-engineer', 'loop-09', 'Is every retrieval segment cut at an activity or decision boundary, carrying its position, applicability and related segments; do the indexed segments contradict each other; and is a person accountable for each?', 'A thousand-character chunk of the 2019 SOP retrieved next to the current step tells the assistant two incompatible orders of work.', FALSE, 'RetrievalSegments.ContradictedIsIndexed=1/9; RetrievalSegments.IsInconsistentGrounding=1/9; RetrievalSegments.IsIndexed=9/9; RetrievalSegments.IsIsolatedChunk=1/9; RetrievalSegments.IsMachineHeldKnowledge=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ke-structured-queries', 'knowledge-engineer', 'loop-09', 'Do our structured queries walk both the ontology and the instance data when the question needs both, and can they reach several knowledge systems without copying them into one store first?', 'A flat query cannot know that a pipeline is a software agent; a nightly consolidated copy answers yesterday''s question.', FALSE, 'KnowledgeQueryDefinitions.ConsolidatedDistributedSources=1/4; KnowledgeQueryDefinitions.MissesALayer=1/4; KnowledgeQueryDefinitions.NeedsOntologyAndInstances=2/4; KnowledgeQueryDefinitions.RanOverConsolidatedCopy=1/4; KnowledgeQueryDefinitions.TraversesInstanceLayer=4/4; KnowledgeQueryDefinitions.TraversesOntologyLayer=1/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-assist-grounding', 'plant-assistant', 'loop-09', 'Before I tell a technician something mid-procedure: is it drawn from our own procedure knowledge, cited so they can check it, in time for the step, and have I raised the safety problem already on record?', 'Generic advice, uncited advice, advice after the step is over, or silence about a hiss already heard is how an assistant makes lockout less safe.', FALSE, 'AnswerGroundings.CitedToUser=12/14; AnswerGroundings.IsFromOwnKnowledge=13/14; AssistantAnswers.ArrivedAfterStepEnded=1/13; AssistantAnswers.IsNotFromOwnKnowledge=2/13; AssistantAnswers.IsUntraceableToSource=2/13; AssistantAnswers.RaisedSafetyConcern=2/13; AssistantAnswers.StayedSilentOnSafetyProblem=1/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-safety-ai-state', 'plant-safety-officer', 'loop-09', 'Did an AI assistant act as if a step were done that the record shows never completed, or tell someone a next step our procedure does not allow?', 'The model holds the dependencies; an assistant that tracks state in its own head will send a technician to maintenance before zero energy is verified.', FALSE, 'AssistantAnswers.ContradictsSharedModel=1/13; AssistantAnswers.LostTrackOfState=2/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm1-q11', 'release-manager', 'loop-09', 'Which of our explicit procedure knowledge does this AI recommendation rest on, and which recommendations rest on none?', 'I cannot judge a recommendation against what we intend unless I can see what it was based on.', FALSE, 'AssistantAnswers.IsExplicitlyGroundedRecommendation=2/13; AssistantAnswers.RecommendationRestsOnNothingExplicit=1/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm1-q12', 'plant-safety-officer', 'loop-09', 'Which actions an AI recommended conflict with a regulatory requirement that applies to them, and which were never checked?', 'A recommendation to skip the second zero-energy verification breaks the hazardous energy standard whether or not anyone checked.', FALSE, 'AssistantAnswers.ConflictsWithRegulation=1/13; AssistantAnswers.DeliveredDespiteConflict=1/13; AssistantAnswers.IsUncheckedRegulatedRecommendation=1/13; StepRequirements.RequirementIsRegulatory=3/18', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-release-human-judgment', 'release-manager', 'loop-09', 'Was an AI recommendation on a step that needs human judgment ever acted on without an expert looking at it?', 'The approval gate exists because encoding cannot carry my judgment about a hotfix; an AI that stands in for it removes the gate.', FALSE, 'AssistantAnswers.ActedOnWithoutHumanJudgment=1/13; AssistantAnswers.RecommendedStepNeedsHuman=3/13; AssistantAnswers.WasActedOn=6/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ke-division-of-labor', 'knowledge-engineer', 'loop-09', 'Did our assistants answer compliance questions from documents instead of structured queries, let the language model do the reasoning, or give wrong answers because the graph itself was stale?', 'The model should phrase the answer; the query and the reasoner should decide it. When that is reversed, the error is invisible.', FALSE, 'AnswerGroundings.AssertionIsStale=1/14; AnswerGroundings.AssertionPresentsDeprecated=1/14; AnswerGroundings.GroundsOnStaleAssertion=2/14; AssistantAnswers.AnsweredComplianceQuestionFromDocuments=2/13; AssistantAnswers.DocumentInterpretationErred=1/13; AssistantAnswers.ModelDidTheReasoning=4/13; AssistantAnswers.NeedsInference=5/13; AssistantAnswers.WasCorrect=4/13; AssistantAnswers.WrongBecauseGraphWasStale=2/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q45', 'ai-enablement-lead', 'loop-09', 'Where, step by step, does the AI fail?', 'Failures clustered at one step point at the knowledge for that step, not at the model.', FALSE, 'Steps.IsAiFailurePoint=4/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q46', 'ai-enablement-lead', 'loop-09', 'What is each AI agent''s task completion rate, and which fall short of target?', 'A completion rate measured per agent is the earliest outcome signal we have.', FALSE, 'Agents.IsBelowTaskCompletionTarget=3/55', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ailead-ai-engagement', 'ai-enablement-lead', 'loop-09', 'Which AI agents consume our knowledge without any of their retrievals being logged?', 'We log every technician''s search; an agent whose retrievals nobody logs is the one consumer whose failures we cannot see.', FALSE, 'Agents.IsUntrackedAiConsumer=3/55', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ke-tool-use', 'knowledge-engineer', 'loop-09', 'Is every tool an AI agent used declared on its step in the process graph, did it act with the inputs the step needs, and are the rules for tool-using steps stored in a form an agent can parse?', 'An agent that reserves padlocks without the lock inventory, or calls a tool nobody declared, is running a process the model does not describe.', FALSE, 'AiToolInvocations.ActedWithoutDeclaredContext=1/3; AiToolInvocations.IsUndeclaredToolUse=1/3; DecisionPoints.IsDmnEncoded=4/5; StepConditions.IsMachineParseable=1/7; Steps.ToolUseRulesOnlyInProse=8/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ke-embeddings', 'knowledge-engineer', 'loop-09', 'Does the embedding model we retrieve with treat our near-synonyms as similar and our opposites as opposed?', 'A model that puts approve next to reject retrieves the rejection path when a technician asks about approval.', FALSE, 'EmbeddingProbes.OppositesNotOpposed=1/6; EmbeddingProbes.SynonymsNotSimilar=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ailead-prompt-library', 'ai-enablement-lead', 'loop-09', 'Which prompts carry procedure knowledge the model does not hold, sit outside the maintained library, blow the token budget on rare detail, or paste a document instead of condensing it?', 'A hotfix note typed into a system prompt is a second procedure nobody governs, and it scales to exactly one agent.', FALSE, 'PromptTemplates.CarriesProcedureInstructions=4/5; PromptTemplates.IncludesRareDetail=1/5; PromptTemplates.IsDisconnectedPromptKnowledge=1/5; PromptTemplates.IsUnmanagedPromptInUse=1/5; PromptTemplates.IsVerbatimDump=1/5; PromptTemplates.SpendsBudgetOnRareDetail=1/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-steward-projections', 'process-steward', 'loop-09', 'Are our diagrams and narrative documents generated from the model since its last change, and can the people they are for actually reach them in the form they prefer?', 'A hand-drawn flowchart and the model disagree the day the procedure changes, and nobody can tell which one is right.', FALSE, 'KnowledgeProjections.DiagramCanDivergeFromModel=2/7; KnowledgeProjections.NarrativeNotGeneratedFromModel=1/7; KnowledgeProjections.NarrativeUnreachable=1/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-steward-annotations', 'process-steward', 'loop-09', 'Do comments stay out of the authoritative model, can practitioners flag outdated guidance and add what they know through the annotation interface, and does missing-knowledge friction become a recorded gap?', 'A question written into the rulebook changes the procedure; a flag sent by email is lost; a veteran''s tip that never becomes a fragment is lost too.', FALSE, 'ModelAnnotations.FlagBypassedAnnotationInterface=1/9; ModelAnnotations.IsDiscussionInAuthoritativeModel=1/9; ModelAnnotations.IsFrictionWithoutGap=1/9; ModelAnnotations.IsLostNewKnowledge=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q32', 'maintenance-technician', 'loop-09', 'Which guidance have we flagged as outdated, and at which steps?', 'If I flagged the press-7 map last week I need to know it is still flagged before I use it tonight.', FALSE, 'ModelAnnotations.IsOpenOutdatedFlag=2/9; Steps.HasReportedRealityMismatch=2/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q33', 'process-steward', 'loop-09', 'Where has the encoded procedure drifted from how the work is actually done?', 'A step people keep deviating from, or deviate from where they flagged the guidance, is a step whose encoding is wrong.', FALSE, 'Steps.IsDriftedFromPractice=1/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q40', 'process-steward', 'loop-09', 'What do people search for and fail to find, and is each failure linked to a gap or a usability barrier?', 'A failed search at 22:18 for the press-7 accumulator is the knowledge gap that caused the night''s residual-energy release.', FALSE, 'KnowledgeSearchEvents.FoundNothingUseful=2/6; KnowledgeSearchEvents.IsUnlinkedFailedSearch=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q41', 'process-steward', 'loop-09', 'At what point do people give up on a query?', 'Giving up after results came back is a usability barrier; giving up on no results is a gap. They need different fixes.', FALSE, 'KnowledgeSearchEvents.GaveUpAfterSeeingResults=1/6; KnowledgeSearchEvents.WasAbandoned=2/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ke-encoding-adequacy', 'knowledge-engineer', 'loop-09', 'Is each procedure version encoded richly enough to guide AI, findable, clear, and in a form that can be searched, queried, validated and reasoned over?', 'A version that exists only as rows nobody can query or reason over is stored, not encoded.', FALSE, 'ProcedureVersions.IsInadequateForUse=6/9; ProcedureVersions.IsNotQueryValidateReasonReady=5/9; ProcedureVersions.LacksMachineInterpretableEncoding=5/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-steward-reach', 'process-steward', 'loop-09', 'Can people and machines both reach each current procedure version, or does a version reach only one of them, or nobody?', 'Knowledge that reaches the assistant but no technician, or neither, is not organizational knowledge anyone can act on.', FALSE, 'ConsumerSystemSyncs.ReachesHumans=3/6; ConsumerSystemSyncs.ReachesMachines=5/6; KnowledgeProjections.IsPublished=6/7; ProcedureVersions.IsUnreachableKnowledge=4/9; ProcedureVersions.ServesOnlyHumansOrOnlyMachines=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-steward-drift-detection', 'process-steward', 'loop-09', 'Is every procedure we run checked automatically and recently against what the event logs say actually happened?', 'Drift found once a year by audit is drift that ran all year.', FALSE, 'ProcedureVersions.LacksContinuousDriftDetection=2/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-steward-outcomes', 'process-steward', 'loop-09', 'Is each procedure we run connected to measured outcomes, and did bad outcomes change what we invest in; are efficiency claims about procedural knowledge at all?', 'Outcome data that feeds no decision is a dashboard; a quality-graph gain is not evidence for procedure graphs.', FALSE, 'KnowledgeOutcomeMeasurements.IsGainOutsideProceduralScope=1/7; KnowledgeOutcomeMeasurements.IsUnactedAdverseOutcome=2/7; ProcedureVersions.IsDisconnectedFromOutcomes=2/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q42', 'plant-safety-officer', 'loop-09', 'Do crews with better access to the lockout knowledge make fewer errors than the crews they are compared with?', 'If the night crew''s error rate falls as their access rises, the second verifier and the map are worth funding.', FALSE, 'KnowledgeOutcomeMeasurements.HigherAccessFewerErrors=2/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q43', 'plant-safety-officer', 'loop-09', 'Do crews with better access to the lockout knowledge work more efficiently?', 'Access that makes a crew safer but slower is a different argument from access that makes it both.', FALSE, 'KnowledgeOutcomeMeasurements.HigherAccessMoreEfficient=1/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q44', 'plant-safety-officer', 'loop-09', 'Do crews with better access to the lockout knowledge leave the people they serve more satisfied?', 'Production supervisors are the customers of a lockout; their satisfaction is the outcome they notice.', FALSE, 'KnowledgeOutcomeMeasurements.HigherAccessMoreSatisfied=1/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ke-ai-insights', 'knowledge-engineer', 'loop-09', 'Is each insight an AI produced validated and folded back into the model, did any AI grow the model where no person had seeded it, and does AI both feed and draw on each version?', 'An AI-discovered deviation pattern that nobody folds back is lost; an AI-invented procedure nobody seeded is an ontology nobody owns.', FALSE, 'AiInsightProposals.GrewModelWithoutHumanSeed=1/6; AiInsightProposals.IsUnvalidatedOrStrandedInsight=2/6; ProcedureVersions.UsesAiInOneDirectionOnly=3/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-ailead-initiatives', 'ai-enablement-lead', 'loop-09', 'Does each AI initiative rest on documented, elicited process knowledge, earn its way from reviewed partial automation, invest in the knowledge layer, get measured, and give knowledge back?', 'The initiatives that failed here were the ones that started from a prompt instead of a procedure.', FALSE, 'AiAdoptionInitiatives.AdoptedWithoutBottomLineResult=2/9; AiAdoptionInitiatives.AgenticWithoutKnowledgeCapture=2/9; AiAdoptionInitiatives.BreaksElicitEncodeConnectOrder=3/9; AiAdoptionInitiatives.FailedWithoutFormalizedKnowledge=2/9; AiAdoptionInitiatives.IsAgentic=6/9; AiAdoptionInitiatives.IsAiOutcomeUnmeasured=4/9; AiAdoptionInitiatives.NotAnchoredInProcessKnowledge=1/9; AiAdoptionInitiatives.RedesignedBeforeDocumented=1/9; AiAdoptionInitiatives.UnderinvestsKnowledgeLayer=4/9; AiAdoptionInitiatives.WentFullWithoutReviewedPartialStage=1/9; Organizations.AiFailsForLackOfCapturedKnowledge=1/18', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm1-q15', 'ai-enablement-lead', 'loop-09', 'Does this AI task follow ordered steps and depend on our own knowledge, so that it calls for a process knowledge framework?', 'A single classification needs a good model; a multi-step task that depends on how we work needs the procedure.', FALSE, 'AiAdoptionInitiatives.CallsForProcessKnowledgeFramework=6/9; AiAdoptionInitiatives.DependsOnOrganizationalKnowledge=8/9; AiAdoptionInitiatives.TaskIsMultiStep=7/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-safety-agent-readiness', 'plant-safety-officer', 'loop-09', 'Is any agent being handed a procedure that exists only in people''s heads, that does not specify conditions and exceptions, or whose steps carry no ontology type?', 'An agent cannot ask the veteran what he meant; it can only do what is specified.', FALSE, 'AiAdoptionInitiatives.AgentOnNotationOnlyProcedure=1/9; AiAdoptionInitiatives.AgentOnUnderSpecifiedProcedure=3/9; AiAdoptionInitiatives.HandsTacitProcedureToAgent=1/9; AiAdoptionInitiatives.TargetHasNoExplicitSteps=3/9; AiAdoptionInitiatives.TargetVersionNotationOnly=1/9; AiAdoptionInitiatives.TargetVersionUnderSpecified=5/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm3-q08', 'process-steward', 'loop-09', 'Which procedures we intend agents to execute exist only as tacit knowledge?', 'Those are the procedures to elicit first.', FALSE, 'Procedures.IsTacitOnlyAgentTarget=1/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q9-safety-compliance-exposure', 'plant-safety-officer', 'loop-09', 'Which regulated procedures exist only as documents, and which executions went wrong with nobody reporting it?', 'Exposure nobody can see is exposure nobody funds fixing.', FALSE, 'ProcedureExecutions.IsUnreportedMistake=1/10; Procedures.IsRegulatedButUnformalized=1/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

