VALUES ('aq-ont4-q01', 'change-risk-classifier', 'loop-09', 'Which person currently holds the role that approves production releases, so I can route my risk class to them?', 'Routing to a name from a document sends the classification to whoever held the role when the document was written.', FALSE, 'Roles.IsProductionReleaseApprover=1/33; Steps.IsReleaseApprovalGate=1/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

