VALUES ('aq-ont4-q02', 'release-manager', 'loop-09', 'Which role, and which person in it, backs me up on escalation when I cannot approve?', 'An escalation path that ends in a vacant role is no escalation path.', FALSE, 'Roles.HasEscalationBackup=3/33; Roles.HasUnfilledEscalationBackup=1/33', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

