VALUES ('q9-ke-semantic-context', 'knowledge-engineer', 'loop-09', 'Which of our tables carry their meaning only as a column layout, with no mapping to any ontology term?', 'A table that maps to nothing means whatever the next reader of its column names guesses.', FALSE, 'RulebookTables.MeaningIsOnlyTabular=52/260', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

