VALUES ('q9-ailead-benchmarks', 'ai-enablement-lead', 'loop-09', 'On which task families did grounding our assistant in the graph lift its accuracy, and by how much?', 'Grounding costs knowledge-engineering time; the lift per task family says where it pays.', FALSE, 'AssistantBenchmarks.GeneratesDatabaseQueries=3/4; AssistantBenchmarks.ShowsGeospatialRetrievalLift=1/4; AssistantBenchmarks.ShowsSpatialLiftFromGraphQueries=1/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

