VALUES ('aq-ont4-q15', 'ontology-authority', 'loop-10', 'Who is the steward of each model we govern, and which models have nobody?', 'A model with no steward has nobody watching it drift.', FALSE, 'GovernedModels.HasNoCurrentSteward=2/7; GovernedModels.IsOwnerless=2/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

