VALUES ('q10-authority-ownerless-models', 'ontology-authority', 'loop-10', 'Which models have gone ownerless for a year, and whose governance simply lapsed?', 'An ownerless model is predicted not to survive a year; lapsed governance means the capability was treated as a project that ended.', FALSE, 'GovernedModels.GovernanceLapsed=1/7; GovernedModels.IsOwnerlessPastAYear=1/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

