VALUES ('q10-authority-charter-quality', 'ontology-authority', 'loop-10', 'Does every charter name a steward with written responsibilities and an authority with a stated approval scope, kept distinct, held by the domain''s own function?', 'Named roles with no written duties, one role doing both jobs, or authority held outside the domain all make ownership a label.', FALSE, 'ModelCharters.ConflatesStewardAndAuthority=1/8; ModelCharters.IsAuthorityOutsideDomainOwner=2/8; ModelCharters.IsAuthorityScopeUnstated=1/8; ModelCharters.IsCurrent=5/8; ModelCharters.IsSanctionedDualHolding=1/8; ModelCharters.IsStewardUnwritten=1/8', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

