VALUES ('q10-authority-roles-exercised', 'ontology-authority', 'loop-10', 'Are the stewards and authorities we named actually doing the work?', 'A charter whose steward never acts and whose authority never decides is ownership on paper only.', FALSE, 'ModelCharters.IsNamedButUnexercised=1/8', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

