VALUES ('q10-steward-practice-drift', 'process-steward', 'loop-10', 'Which models carry detected drift from practice, and which of those has nobody maintaining it?', 'Drift someone is working is a backlog; drift on an unmaintained model is decay.', FALSE, 'GovernedModels.HasOpenPracticeDrift=2/7; GovernedModels.IsNeglectedAndDrifting=1/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

