VALUES ('q10-authority-silent-decay', 'ontology-authority', 'loop-10', 'Where did a model that passed its tests drift anyway, and where did we only learn of it from an expert''s wrong answer?', 'Decay does not fail the build; if only experts catch it, the review process is missing.', FALSE, 'DriftObservations.DriftFollowsCleanRelease=2/4; DriftObservations.ReleasePassedValidation=2/4; DriftObservations.WentUndetectedByPassingSuite=1/4; GovernedModels.DegradationHiddenUntilWrongAnswer=1/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-ke-dependencies', 'knowledge-engineer', 'loop-10', 'Which revisions to standards we reuse have I not yet checked against our mappings?', 'A deprecated DCAT term we still map to changes meaning without our model changing a byte.', FALSE, 'ExternalDependencyRevisions.IsUntrackedRevision=1/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

