VALUES ('q10-ke-user-questions', 'knowledge-engineer', 'loop-10', 'Which questions from the model''s users are waiting on me past due?', 'Adopters who get no answer stop raising issues and start working around the model.', FALSE, 'StakeholderQuestions.IsUnansweredPastDue=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q13', 'knowledge-engineer', 'loop-10', 'Which stakeholder questions can the model not answer today?', 'Every unanswerable question is either a scope change or a reason the model is being bypassed.', FALSE, 'StakeholderQuestions.IsUnanswerableToday=5/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q14', 'knowledge-engineer', 'loop-10', 'For each question we cannot answer, is the fix more data, a small schema extension, or a structural change?', 'The fix decides the process: data operations, a minor release, or a major one.', FALSE, 'StakeholderQuestions.IsUntriagedUnanswerable=1/6; StakeholderQuestions.NeedsStructuralChange=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-authority-scope-requests', 'ontology-authority', 'loop-10', 'Did every unanswerable question become a scope change request, and did triage send each to the right process?', 'A triaged question that goes through the wrong process is a schema change made as a data load, or the reverse.', FALSE, 'StakeholderQuestions.IsMisroutedAfterTriage=1/6; StakeholderQuestions.UnanswerableWithoutScopeRequest=2/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-authority-expansion', 'ontology-authority', 'loop-10', 'When another function asks to model its workflows here, did we decide honestly whether they fit the schema?', 'Saying new workflows fit when some concepts have no table is how a model gets bent until it means nothing.', FALSE, 'ExpansionConceptFits.IsUncovered=2/9; ModelExpansionRequests.FitDecisionContradictsConceptFit=1/3; ModelExpansionRequests.IsCrossFunctionExpansion=2/3; ModelExpansionRequests.RequiresSchemaExtension=2/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-authority-change-rules', 'ontology-authority', 'loop-10', 'Did every change go through the process our rules require for its layer?', 'Schema changes belong to governance and instance changes to data operations; mixing them skips review or clogs it.', FALSE, 'ChangeAuthorityRules.IsRuleBypassed=1/4; ModelChangeRequests.IsMisrouted=1/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

