VALUES ('q10-authority-review-scope', 'ontology-authority', 'loop-10', 'Which changes went past me that were beyond the steward''s minor-change authority?', 'The steward approves minor changes; renames, domain changes, disjointness and retirements are mine to review.', FALSE, 'ModelChangeRequests.AuthorityReviewSkipped=4/17; ModelChangeRequests.HasAuthorityReview=6/17; ModelChangeRequests.IsAccepted=15/17; ModelChangeRequests.IsMinorScope=10/17; ModelChangeRequests.PlacementNotDecidedByAuthority=1/17; ModelChangeRequests.RequiresAuthorityReview=7/17; ModelChangeRequests.StewardApprovalOutOfBounds=3/17; ModelChangeRequests.StewardOwnChangeUnreviewed=2/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-ke-question-tied', 'knowledge-engineer', 'loop-10', 'Is every change request tied to a competency question, and were the ones without one sent back?', 'A change nobody can tie to a question is a change nobody can test.', FALSE, 'ModelChangeRequests.LacksMotivatingQuestion=2/17; ModelChangeRequests.UnmotivatedAndNotReturned=1/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

