VALUES ('aq-ont4-q30', 'ontology-authority', 'loop-10', 'Which competency question motivated this change, and was it one the model used to answer?', 'A change motivated by a question that now fails is a repair; one motivated by a new question is growth.', FALSE, 'ModelChangeRequests.MotivatedByFailingQuestion=5/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

