VALUES ('aq-ont4-q19', 'release-manager', 'loop-10', 'In which release version did this change ship?', 'A deployed schema change in no release is invisible to every consumer pinned to a version.', FALSE, 'ModelChangeRequests.DeployedWithoutTargetRelease=1/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

