VALUES ('q10-release-agent-swaps', 'release-manager', 'loop-10', 'Were agent swaps handled as data operations, and were moves from AI to human execution recorded with when, why and compliance consequences?', 'Swapping the risk classifier''s version changes one assignment; moving health verification to a person changes who answers to the auditor.', FALSE, 'ModelChangeRequests.AiToHumanMoveUnaudited=1/17; ModelChangeRequests.AiToHumanMoveWithoutComplianceReview=1/17; ModelChangeRequests.IsMisclassifiedAgentSwap=1/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

