VALUES ('q10-steward-lifecycle-authority', 'process-steward', 'loop-10', 'Was every procedure definition created, modified or retired by someone governance allows to?', 'A definition retired by whoever happened to be on shift takes knowledge out of the register with no one accountable.', FALSE, 'ModelChangeRequests.LifecycleChangeByUnauthorizedAgent=1/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

