VALUES ('aq-ont4-q09', 'ontology-authority', 'loop-10', 'Which existing instance data would this change make inconsistent?', 'Instance data made inconsistent by a schema change is a silent failure in every query over it.', FALSE, 'ModelChangeRequests.WouldMakeInstancesInconsistent=1/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

