VALUES ('aq-ont4-q29', 'ontology-authority', 'loop-10', 'Would the proposed change leave the vocabulary layer and domain coverage model complete?', 'A change that leaves an area uncovered removes the model''s ability to say something it was built to say.', FALSE, 'DomainCoverageAreas.IsUncoveredArea=1/4; ModelChangeRequests.WouldLeaveCoverageIncomplete=1/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

