VALUES ('q10-authority-impact-misses', 'ontology-authority', 'loop-10', 'What did our impact assessments miss that deployment then revealed?', 'Every post-deployment surprise is a question the assessment should have asked.', FALSE, 'ModelChangeRequests.DomainChangeSpreadWrongInferences=1/17; ModelChangeRequests.IntuitiveDisjointnessBrokeIndividuals=1/17; ModelChangeRequests.IsModelingChange=10/17; ModelChangeRequests.IsSchemaChange=9/17; ModelChangeRequests.LeavesCoverageUnchecked=2/17; ModelChangeRequests.MissedAlteredInferences=2/17; ModelChangeRequests.MissedAlteredQueryResults=1/17; ModelChangeRequests.MissedInconsistentInstances=2/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

