VALUES ('q10-ke-validation-runs', 'knowledge-engineer', 'loop-10', 'Was each change run through the validation suite with the change applied, with failures inspected, consistency confirmed and expected inferences produced?', 'Only the suite run with the change applied says whether the model still holds together.', FALSE, 'ChangeValidationRuns.HasUninspectedFailures=1/8; ChangeValidationRuns.IsUnconfirmedConsistency=3/8; ChangeValidationRuns.MissesExpectedInference=1/8; ExpectedInferenceChecks.IsUnproduced=1/4; ModelChangeRequests.AcceptedWithFailingSuite=1/17; ModelChangeRequests.AcceptedWithoutStructuralCheck=2/17; ModelChangeRequests.AcceptedWithoutTestRun=2/17; ModelChangeRequests.AcceptedWithoutVocabularyCheck=3/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

