VALUES ('q10-authority-integrity-review', 'ontology-authority', 'loop-10', 'Did a person review every schema change for disjointness violations, unintended domain inferences and range inconsistencies?', 'An assistant can run the checks; only validation and a person''s judgment can say the model''s integrity survived.', FALSE, 'ModelChangeRequests.IntegrityDecidedWithoutHuman=1/17; ModelChangeRequests.SkippedDisjointnessReview=2/17; ModelChangeRequests.SkippedDomainInferenceReview=3/17; ModelChangeRequests.SkippedRangeReview=4/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

