VALUES ('q10-safety-objections', 'plant-safety-officer', 'loop-10', 'Was any change approved while my objection to it was still unresolved?', 'Declaring people and software disjoint broke the plant''s organization agent; I objected and it shipped anyway.', FALSE, 'ChangeObjections.IsUnresolved=1/2; ModelChangeRequests.ApprovedOverUnresolvedObjection=1/17', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

