VALUES ('aq-ont4-q25', 'release-manager', 'loop-10', 'Which version is the model currently released at?', 'Every consumer pins a version; they need to know which one is current.', FALSE, 'RulebookReleases.IsDeclaredCurrentRelease=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

