VALUES ('q10-release-semver', 'release-manager', 'loop-10', 'Does every release''s version number match what it actually contains?', 'A class rename shipped as a minor release breaks every consumer that trusted semantic versioning.', FALSE, 'RulebookReleases.ClassRemovalWithoutMajor=1/9; RulebookReleases.InconsistentDisjointnessWithoutMajor=1/9; RulebookReleases.InvalidatingDomainRangeWithoutMajor=1/9; RulebookReleases.IsIncrementInconsistentWithScale=1/9; RulebookReleases.MinorIsNotBackwardCompatible=2/9; RulebookReleases.PatchAltersLogicalModel=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-release-breaking', 'release-manager', 'loop-10', 'Was every breaking release planned, decided on record, announced to its dependents and re-validated by every consumer?', 'A major release is an engineering event: the Postgres substrate, the reasoner and the register all have to move with it.', FALSE, 'ConsumerRevalidations.PassedRevalidation=11/26; ConsumerRevalidations.WasNotified=26/26; RulebookReleases.BreakingReleaseWithUnrevalidatedConsumers=2/9; RulebookReleases.BreakingReleaseWithoutMigrationPlan=1/9; RulebookReleases.IsBreakingRelease=3/9; RulebookReleases.IsUnannouncedToDependents=2/9; RulebookReleases.IsUndocumentedVersionDecision=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-authority-release-record', 'ontology-authority', 'loop-10', 'Is every release approved, tagged, licensed at a permanent identifier, kept in short cycles, and matched by its recorded changes and suite updates?', 'A release nobody approved, tagged or licensed cannot be rolled back to, cited or reused.', FALSE, 'RulebookReleases.IsLongReleaseCycle=1/9; RulebookReleases.IsReleaseWithoutRecordedChanges=1/9; RulebookReleases.IsReleasedWithoutLicenceOrPermanentId=1/9; RulebookReleases.IsUntaggedRelease=1/9; RulebookReleases.PublishedWithoutApproval=1/9; RulebookReleases.SuiteLagsRelease=2/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-ke-release-evaluation', 'knowledge-engineer', 'loop-10', 'Was each release consistency-checked, scored against our quality criteria, and shown to answer its competency questions, not just validated as well formed?', 'A well-formed model can still fail every requirement it was built for.', FALSE, 'QualityCriteria.IsStated=8/8; RulebookReleases.IsNotScoredAgainstCriteria=7/9; RulebookReleases.PassedValidationAtRelease=3/9; RulebookReleases.ReleasedDespiteFailedValidation=1/9; RulebookReleases.ReleasedWithoutConsistencyCheck=5/9; RulebookReleases.ReleasedWithoutCqTaskTest=5/9; RulebookReleases.WellFormedButRequirementsUnshown=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q12', 'ontology-authority', 'loop-10', 'Does this version still answer every original competency question, and which ones regressed?', 'An original question that stops answering is a regression, whatever the tests say.', FALSE, 'CompetencyQuestionRuns.EntryIsOriginal=9/10; CompetencyQuestionRuns.IsBaselineRegression=1/10; CompetencyQuestionRuns.IsUnfixedWrongAnswer=1/10; CompetencyQuestionRuns.PriorWasAnswerable=5/10; CompetencyQuestionRuns.WasAnswerable=9/10; RulebookReleases.HasBaselineRegression=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-authority-cq-coverage', 'ontology-authority', 'loop-10', 'Is competency question coverage tracked release by release, and did it fall?', 'Element completeness can rise while the share of questions answered falls.', FALSE, 'RulebookReleases.CqCoverageDeclined=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-ke-cq-review', 'knowledge-engineer', 'loop-10', 'Is each model''s question set reviewed at least quarterly, with the original baseline kept, outgrown questions flagged, and irrelevant ones made deprecation candidates?', 'Questions right at launch are outgrown within a year; without review the model is judged against a world that is gone.', FALSE, 'CompetencyQuestionSetEntries.IrrelevantButStillActive=1/8; CompetencyQuestionSetEntries.IsOriginalBaseline=7/8; CompetencyQuestionSetEntries.IsOutgrownBaselineQuestion=2/8; CompetencyQuestionSetEntries.ServesEveryGovernanceUse=2/8; CompetencyQuestionSetEntries.UsedAsAcceptanceCriterion=5/8; CompetencyQuestionSetEntries.UsedAsTestDriver=5/8; CompetencyQuestionSetEntries.UsedForGovernance=4/8; CompetencyQuestionSetEntries.UsedForScoping=7/8; GovernedModels.CqReviewOverdue=3/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-ke-lot-lifecycle', 'knowledge-engineer', 'loop-10', 'Does each model have a requirements specification, and does governance cover every stage of each procedure family''s knowledge, continuously?', 'Governance that covers capture but not retrieval or use leaves the knowledge ungoverned where it matters.', FALSE, 'GovernanceStageControls.IsContinuous=18/20; GovernanceStageControls.IsContinuousPipelineStage=8/20; GovernedModels.IsUnmanageableUndocumentedWork=1/7; GovernedModels.LacksLifecycleStageControl=2/7; GovernedModels.PipelineNotContinuous=3/7; GovernedModels.ProcedureHasNoExplicitSteps=3/7; GovernedModels.RequirementsSpecIncomplete=4/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-ke-ai-proposals', 'knowledge-engineer', 'loop-10', 'Did every AI candidate stay a proposal until a person reviewed, quality-checked and committed it?', 'AI may draft questions, alignments and instance data; it must never commit an axiom or become the one who answers for adoption.', FALSE, 'ModelProposals.AdoptionNotAnsweredByPerson=2/11; ModelProposals.AiAlignmentDecidedByAi=1/11; ModelProposals.AiAxiomWithoutHumanReview=1/11; ModelProposals.AiInstanceDataLoadedWithoutSteward=1/11; ModelProposals.AiQuestionAdoptedUnvetted=1/11; ModelProposals.AwaitsEngineerVetting=1/11; ModelProposals.AwaitsStewardApproval=1/11; ModelProposals.CommittedWithoutExpertReview=4/11; ModelProposals.EnteredWithoutQualityCheck=2/11; ModelProposals.HasNoHumanTouchpoint=2/11; ModelProposals.IsAiCandidate=9/11; ModelProposals.IsPendingAlignmentDecision=1/11', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

