VALUES ('aq-pkm2-q35', 'maintenance-technician', 'loop-10', 'Which knowledge is approved, and which is only proposed?', 'A proposed hotfix step read as approved is followed as if someone stood behind it.', FALSE, 'ModelProposals.IsOnlyProposed=3/11', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

