VALUES ('aq-pkm2-q36', 'maintenance-technician', 'loop-10', 'Who approved this knowledge?', 'Approved knowledge with no approver is trusted on nobody''s word.', FALSE, 'ModelProposals.ApproverUnknown=3/11', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

