VALUES ('q10-ke-definitions', 'knowledge-engineer', 'loop-10', 'Does each class definition say what it includes, excludes and neighbors, and did a person revise every AI draft?', 'An unrevised AI definition reads plausibly and draws the class boundary wherever the draft happened to.', FALSE, 'TermDefinitions.AiDraftAdoptedUnrevised=1/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

