VALUES ('aq-ont4-q03', 'release-manager', 'loop-10', 'Which AI agent version held this step''s assignment on a given past date?', 'When a January release is questioned, I need to know it was classifier 2.4.0, not 2.4.1.', FALSE, 'AssignmentInstantChecks.HeldStepAtInstant=2/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

