VALUES ('q10-release-assignment-history', 'release-manager', 'loop-10', 'When an assignment is replaced, is the old one kept with its validity period closed?', 'An assignment superseded but never closed makes it impossible to say who acted when.', FALSE, 'RoleAssignments.PredecessorLacksValidityEnd=1/36', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

