VALUES ('q10-ke-agent-classification', 'knowledge-engineer', 'loop-10', 'Is every agent classified as a person or a kind of software, and does every AI agent carry its model version?', 'Accountability questions are answered from structure only if the structure says who is a person and which model version acted.', FALSE, 'Agents.IsAiAgentWithoutModelVersion=1/55; Agents.IsUnclassifiedAgent=1/55', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

