VALUES ('q10-steward-review-refresh', 'process-steward', 'loop-10', 'Did each review refresh the reviewed workflow''s last-modified date?', 'The staleness query reads last-modified; a reviewed workflow that keeps its old date is reported stale, or a stale one is hidden.', FALSE, 'ReviewEvents.ReviewDidNotRefreshModified=1/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

