VALUES ('aq-ont4-q05', 'process-steward', 'loop-10', 'Which workflows have not been modified in more than twelve months?', 'A year without a change on a live workflow is either rare stability or unnoticed decay.', FALSE, 'ProcedureVersions.IsUnmodifiedForTwelveMonths=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-ke-staleness-runs', 'knowledge-engineer', 'loop-10', 'Does the staleness query run periodically, and do its results reach the steward?', 'A staleness report nobody reads is the same as not running it.', FALSE, 'StalenessQueryRuns.NotSurfacedToSteward=1/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

