VALUES ('q10-steward-design-decisions', 'process-steward', 'loop-10', 'Are the decisions behind each procedure''s commitments recorded alongside it, with their rationale?', 'The next steward will change a two-attempt cap they cannot explain.', FALSE, 'ProcedureVersions.IsLiveWithoutRecordedDecisions=5/9; ProcessDesignDecisions.IsCommitmentWithoutRationale=1/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm3-q05', 'maintenance-technician', 'loop-10', 'Why was this decision made, and was the reason written down when it was made?', 'A reason reconstructed weeks later is memory, not record.', FALSE, 'ProcessDesignDecisions.IsRecordedAfterTheFact=1/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q10-ke-publication', 'knowledge-engineer', 'loop-10', 'Is every term published under a resolvable identifier, aligned to external standards, typed by convention, reused rather than reinvented, and access-controlled?', 'Outside systems can only interpret terms they can resolve and recognize.', FALSE, 'RulebookTables.IsUnalignedToStandard=206/260; RulebookTables.IsUnsecuredGovernanceRecord=35/260; RulebookTables.LacksSemanticTypeConvention=14/260; SemanticMappings.IsNonResolvableTermIri=157/299; SemanticMappings.ReinventsStandardTerm=2/299', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

