VALUES ('q11-sourcing-outsourcing-models', 'sourcing-manager', 'loop-11', 'Which of our functions have we classified as execution to send out, and is each one routine transactional work or expertise-heavy work that builds process knowledge?', 'Routine work can be sent out with little lost; expertise-heavy work sent out takes the organization''s process knowledge with it.', FALSE, 'SourcingFunctions.IsBusinessProcessOutsourcing=1/12; SourcingFunctions.IsKnowledgeProcessOutsourcing=5/12; SourcingFunctions.IsOutsourced=6/12; SourcingFunctions.IsVitalExpertiseClassedNonCore=5/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-sourcing-what-how-split', 'sourcing-manager', 'loop-11', 'Where we keep the specification but a provider holds the method, can we still build what we design, or have we hollowed out?', 'A firm that keeps its brand and designs but not the know-how to make its products depends on its provider for its own business.', FALSE, 'Organizations.IsHollowedOutFirm=1/18; SourcingFunctions.ClaimsHowWithoutDoing=1/12; SourcingFunctions.DeliversOwnProduct=3/12; SourcingFunctions.DesignsWhatItCannotBuild=1/12; SourcingFunctions.IsWhatHowSplit=5/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm3-q07', 'sourcing-manager', 'loop-11', 'For each of our processes, who holds the knowledge of how it is really performed: us, or an outside provider?', 'Sourcing decisions are made about cost; nobody records that the how-knowledge moved with the work.', FALSE, 'SourcingFunctions.IsMethodKnowledgeHeldOutside=5/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-sourcing-provider-knowledge-terms', 'sourcing-manager', 'loop-11', 'For each provider we rely on for knowledge, who owns the documentation, can we reach the know-how, and have we planned how it comes back to us?', 'A provider whose know-how is its differentiator has every reason to keep it; only the contract can move it back.', FALSE, 'ProviderEngagements.HasKnowledgeAccessClause=4/7; ProviderEngagements.IsActive=6/7; ProviderEngagements.IsKnowledgeAccessUnsecured=2/7; ProviderEngagements.IsUnplannedKnowledgeReturn=3/7; ProviderEngagements.ProviderTreatsKnowHowAsDifferentiator=3/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-sourcing-knowledge-flow', 'sourcing-manager', 'loop-11', 'Does each provider relationship produce explicit knowledge deliverables, moving in both directions, over a term long enough to build knowledge together?', 'Knowledge that is not a deliverable does not move; learning that runs one way is extraction, not partnership.', FALSE, 'KnowledgeDeliverables.IsDelivered=9/10; ProviderEngagements.IsOneWayLearning=2/7; ProviderEngagements.IsShortTermWithoutJointKnowledge=3/7; ProviderEngagements.LacksKnowledgeDeliverables=1/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm3-q12', 'sourcing-manager', 'loop-11', 'Does this provider relationship oblige explicit knowledge deliverables, and knowledge flowing back to us?', 'Renewal is the moment to add the obligation; it has to be visible per relationship to be negotiated.', FALSE, 'ProviderEngagements.ObligesKnowledgeFlowBack=3/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm3-q02', 'knowledge-engineer', 'loop-11', 'What procedural knowledge do we hold versus need, and where are the gaps and the dependencies on providers?', 'Capture work has to start from the audit''s shortfalls, not from whatever documentation happens to exist.', FALSE, 'KnowledgeAuditItems.HasInternalShortfall=5/12; KnowledgeAuditItems.IsCoverageGap=1/12; KnowledgeAuditItems.IsKnowledgeDependency=4/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-ke-audit-completeness', 'knowledge-engineer', 'loop-11', 'Which functions we outsource or depend on were never audited for held against needed knowledge, and which findings did nobody name as a knowledge gap?', 'An unaudited dependency is invisible, and a finding that is not named is not owned by anybody.', FALSE, 'KnowledgeAuditItems.IsUnnamedFinding=2/12; SourcingFunctions.IsUnauditedFunction=2/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-ke-single-team-silos', 'knowledge-engineer', 'loop-11', 'Which of the knowledge we do hold sits with a single team?', 'Knowledge held by one team is hoarded by default, even when nobody intends it.', FALSE, 'KnowledgeAuditItems.IsSingleTeamSilo=1/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-authority-deficit-framing', 'knowledge-authority', 'loop-11', 'Did our audits call what they found a process knowledge deficit, or file it as a cost and efficiency problem?', 'A deficit filed as a cost problem gets a cost answer: another provider, not knowledge coming back.', FALSE, 'KnowledgeAudits.TreatsDeficitAsCostProblem=1/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-authority-knowledge-staff', 'knowledge-authority', 'loop-11', 'Which organizations have audit findings but employ no knowledge engineer, information architect or ontologist to capture, organize and encode that knowledge?', 'Findings without the people to act on them stay findings.', FALSE, 'Organizations.HasKnowledgeFindingsWithoutKnowledgeStaff=1/18', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm3-q03', 'knowledge-authority', 'loop-11', 'Which processes are strategically vital and expertise-heavy, and which of those have we outsourced?', 'Those are the processes whose knowledge the organization cannot afford to lose track of.', FALSE, 'SourcingFunctions.IsOutsourcedVitalExpertiseProcess=5/12; SourcingFunctions.IsStrategicallyVital=11/12; SourcingFunctions.IsVitalExpertiseProcess=10/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-authority-capture-priorities', 'knowledge-authority', 'loop-11', 'Among vital, expertise-heavy processes that are outsourced or have coverage gaps, which have no deliberate effort to capture their knowledge?', 'Capture capacity is scarce; it must go first where losing the knowledge would hurt most.', FALSE, 'SourcingFunctions.IsUncapturedPriorityProcess=3/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-steward-retention-scope', 'process-steward', 'loop-11', 'Which retention rules destroy engineering records while their knowledge is still in use, and was it a compliance-only, legally sponsored programme that set them?', 'Retention set for legal exposure deletes the design history the next engineer needs.', FALSE, 'CorporateGovernancePrograms.CoversCompliance=3/3; CorporateGovernancePrograms.CoversDataQuality=1/3; CorporateGovernancePrograms.CoversInformationManagement=2/3; CorporateGovernancePrograms.CoversKnowledgeManagement=2/3; CorporateGovernancePrograms.IsComplianceOnly=1/3; RecordsRetentionPolicies.IsLegalLedKnowledgeDestruction=1/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-ke-registry-feed', 'knowledge-engineer', 'loop-11', 'Is every AI model version the registry reports running in production an individual in our graph, with its deployments and evaluations?', 'An AI system that runs without being in the graph cannot be found by any accountability or impact query.', FALSE, 'AiModelDeployments.IsLiveInProduction=2/6; AiModelEvaluations.Passed=2/3; AiRegistryModelVersions.IsLiveButUnregisteredInGraph=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-ke-registry-populates-agents', 'knowledge-engineer', 'loop-11', 'Were our AI agent individuals filled from the registry through its Dublin Core fields, or typed in by hand?', 'A hand-typed version drifts from the registry, and every query about that agent then answers for a version that does not exist.', FALSE, 'Agents.IsAiAgentNotFilledFromRegistry=11/55', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-release-registry-context', 'release-manager', 'loop-11', 'Which live AI deployments are only a registry row, with no role, step or artifact connecting them to our workflows?', 'A deployment record says a model is running; only its links say what it is doing and to whom.', FALSE, 'AiModelDeployments.IsIsolatedRegistryFact=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q21', 'release-manager', 'loop-11', 'Which artifacts has this AI agent produced?', 'Every risk report I approve on was produced by some classifier version; I need to know which.', FALSE, 'Agents.HasProducedArtifacts=6/55', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q22', 'release-manager', 'loop-11', 'Which downstream steps take this agent''s artifacts as inputs?', 'Those are the steps whose inputs change when the agent does.', FALSE, 'StepVariables.IsInputFromAiArtifact=2/21; Steps.ConsumesAiAgentArtifact=2/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q23', 'vp-engineering', 'loop-11', 'Which roles and agents are responsible for the downstream steps that consume this agent''s artifacts, and is any of them held by nobody?', 'An upgrade has to be announced to the people who act on its output; a vacant role there hears nothing.', FALSE, 'StepVariables.AiArtifactConsumerHasNoAccountableAgent=1/21', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q24', 'vp-engineering', 'loop-11', 'Which workflows contain the steps affected by an agent change?', 'Workflow owners sign off on changes to their workflows, so the change record must name every one.', FALSE, 'ProcedureVersions.ContainsStepsAffectedByAiAgentChange=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q04', 'vp-engineering', 'loop-11', 'If this agent moves to a newer model version, what else is affected, all the way downstream?', 'A risk report feeds the approval, the approval feeds the rollout, the rollout feeds verification: the impact is transitive.', FALSE, 'Agents.HasArtifactBlastRadius=1/55; ArtifactHandoffs.DisagreesWithDeclaredVariable=1/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-vp-upgrade-assessment', 'vp-engineering', 'loop-11', 'Did the impact assessment for this agent upgrade list everything a traversal of the graph finds?', 'A hand-written change ticket lists the step the engineer remembers, not the ones two hand-offs away.', FALSE, 'AgentUpgradeAssessments.MissedTraversedImpact=1/2', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q27', 'vp-engineering', 'loop-11', 'Which human is accountable for this AI agent?', 'When a classifier misjudges a change, somebody must answer for it, and it cannot be the pipeline.', FALSE, 'Agents.IsAiAgentWithoutAccountableHuman=3/55; AiAgentAccountabilities.IsAccountableToNonPerson=1/4; AiAgentAccountabilities.IsCurrent=2/4; AiAgentAccountabilities.IsCurrentHumanAccountability=1/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-vp-assignment-update-governance', 'vp-engineering', 'loop-11', 'When someone leaves a role or an agent is swapped, does governance name who must trigger the update, and was the update completed within its service level?', 'Once the pipeline routes from assignments, an update nobody owns is an outage waiting for the next run.', FALSE, 'AssignmentUpdatePolicies.ModelDrivesRouting=3/3; RoleAssignmentUpdateTasks.ExceededUpdateSla=5/6; RoleAssignmentUpdateTasks.LacksNamedTriggerOwner=4/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-release-one-assignment-change', 'release-manager', 'loop-11', 'When the work of a role changed hands, did only the assignment change, or was the work moved to a new role so the steps had to be re-pointed?', 'Re-pointing steps to change a person is a workflow change nobody reviewed as one.', FALSE, 'RoleAssignmentUpdateTasks.ChangedRoleInsteadOfAssignment=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-release-before-next-run', 'release-manager', 'loop-11', 'Was each departure recorded before the next deployment that needed that role, and did a stale assignment actually break a run?', 'A stale assignment that no run has read is an accuracy problem; one a run routed from is an operational failure.', FALSE, 'RoleAssignmentUpdateTasks.MissedNextDependentRun=3/6; RoleAssignmentUpdateTasks.StaleAssignmentBrokeRouting=2/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-ont4-q06', 'release-manager', 'loop-11', 'To whom does the approval notice for a deployment go at present?', 'If the answer is not read from the current assignments, the notice goes to whoever a list last said.', FALSE, 'RoleAssignments.ReceivesApprovalNoticesNow=4/36', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q11-release-notice-routing', 'release-manager', 'loop-11', 'Did each approval and verification notice reach someone who held the step''s role when it was sent, and did any routing bypass the assignments in the model?', 'A notice that reaches a departed manager, or nobody, is how a release ships on a verbal go-ahead.', FALSE, 'AssignmentRoutedNotices.ReachedWrongPersonOrNobody=3/6; AssignmentRoutedNotices.RecipientHeldRoleWhenSent=3/6; AssignmentRoutedNotices.RoutedAroundModel=1/6; RoleAssignments.IsOpenEnded=29/36', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
