VALUES ('aq-pkm2-q02', 'knowledge-engineer', 'loop-07', 'When I asked what they would do if a condition were different, what did the practitioner say?', 'The what-if answer exposes the conditions a practice depends on, which the practitioner rarely volunteers.', FALSE, 'ObservedActions.HasCounterfactualAnswer=2/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

