VALUES ('aq-pkm2-q03', 'plant-safety-officer', 'loop-07', 'What goal or value does this lockout action ultimately serve, according to the technician who does it?', 'A technician who knows what a step protects can adapt it safely; one who only knows the step cannot.', FALSE, 'ConceptLadderRungs.IsUltimateGoal=2/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q04', 'knowledge-engineer', 'loop-07', 'According to the practitioner, which subprocesses and conditions make up this higher-level activity?', 'Laddering down finds the sub-steps and preconditions a step title hides.', FALSE, 'ConceptLadderRungs.IsDecompositionRung=2/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q05', 'knowledge-engineer', 'loop-07', 'Along which recorded dimensions do our experts tell these machines'' lockout situations apart?', 'The dimensions an expert discriminates on are the ones a newcomer cannot see and the SOP never names.', FALSE, 'RepertoryGridConstructs.IsNeverStatedDimension=2/3; RepertoryGridConstructs.IsRecordedDiscriminatingDimension=2/3; RepertoryGridConstructs.SeparatesSituations=2/3; RepertoryGridConstructs.WasStatedUnprompted=1/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q10', 'knowledge-authority', 'loop-07', 'Which knowledge gaps do we know about and have not yet closed?', 'A known unknown is manageable; the authority must see the list, not rediscover it in an incident.', FALSE, 'KnowledgeGaps.IsKnownAndUnresolved=7/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q11', 'knowledge-authority', 'loop-07', 'Which of our knowledge gaps come from gatekeeping or sabotage?', 'Gatekept gaps do not close by asking again; they need a different method and a different conversation.', FALSE, 'KnowledgeGaps.IsGatekeepingOrSabotage=2/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q17', 'plant-safety-officer', 'loop-07', 'Which past lockout episodes went well, went badly, or had to be improvised?', 'The episodes are where the procedure met the machine; the bad and improvised ones carry the lessons.', FALSE, 'CriticalIncidents.IsAdverseOrImprovised=2/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q18', 'plant-safety-officer', 'loop-07', 'What judgment call did each of those episodes reveal, and where is it recorded?', 'An episode retold without the judgment it revealed is an anecdote, not knowledge.', FALSE, 'CriticalIncidents.HasSurfacedJudgment=2/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q7-ke-knows-more-than-can-say', 'knowledge-engineer', 'loop-07', 'Which of our practitioners reliably know something they cannot put into words?', 'Expertise without a statable basis is the knowledge most at risk and the hardest to elicit; it must be recorded as such.', FALSE, 'PractitionerExpertise.ForesightConfirmed=2/5; PractitionerExpertise.IsUnexplainedForesight=1/5; PractitionerExpertise.KnowsMoreThanCanSay=1/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q7-authority-incidents-unprobed', 'knowledge-authority', 'loop-07', 'Which versions rely on tacit judgment that no critical incident was ever collected to surface?', 'Documentation hides judgment calls; without incidents the version encodes the steps and misses the calls.', FALSE, 'ProcedureVersions.JudgmentUnprobedByIncidents=2/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

