VALUES ('q7-authority-gatekept-gaps', 'knowledge-authority', 'loop-07', 'Where did someone decline to share knowledge, and was the gatekept knowledge we need ever drawn out and codified?', 'A gap caused by withholding must be named as such, and required knowledge behind it must be drawn out before the holder leaves.', FALSE, 'KnowledgeGaps.HolderDeclinedToShare=3/15; KnowledgeGaps.IsRequiredGatekeptUncodified=1/15; KnowledgeGaps.IsUnattributedGatekeeping=1/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

