VALUES ('q7-ke-interview-probes', 'knowledge-engineer', 'loop-07', 'Did each interview ask why choices are made and what happens when the procedure falls short?', 'An interview that only walks the steps records what the SOP already says.', FALSE, 'ElicitationSessions.IsInterview=3/13; ElicitationSessions.IsInterviewWithoutShortfallProbe=2/13; ElicitationSessions.IsInterviewWithoutWhyProbe=1/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q7-ke-observation-captures', 'knowledge-engineer', 'loop-07', 'What did observation see that the practitioner never mentioned, and did we capture it and ask why?', 'Observation exists to catch the obvious and the unreachable; seeing it and not recording it wastes the method.', FALSE, 'ObservedActions.IsMissedStepLeftUncaptured=1/5; ObservedActions.IsOmittedFromOwnAccount=3/5; ObservedActions.IsSmallChoice=2/5; ObservedActions.IsUnofficialWorkaround=1/5; ObservedActions.IsWatchedNotQuestioned=1/5; ObservedActions.MentionedInOwnAccount=2/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

