VALUES ('q7-steward-workshop-composition', 'process-steward', 'loop-07', 'Who was in each workshop: did it include everyone who starts, does and depends on the process, and people normally left out?', 'A workshop of the usual invitees reproduces the official picture of the work.', FALSE, 'ElicitationParticipants.IsKnowledgeConsumer=5/7; ElicitationParticipants.IsKnowledgeEngineer=1/7; ElicitationParticipants.IsKnowledgeProducer=5/7; ElicitationParticipants.IsPractitioner=3/7; ElicitationParticipants.IsSubjectMatterExpert=3/7; ElicitationParticipants.IsUsuallyInvited=6/7; ElicitationSessions.GathersWholeProcessChain=1/13; ElicitationSessions.IsWorkshop=2/13; ElicitationSessions.IsWorkshopWithoutUsualOutsiders=1/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q7-steward-sme-approval', 'process-steward', 'loop-07', 'Did the subject matter experts whose work a procedure affects approve its representation?', 'A representation nobody affected approved is the knowledge engineer''s reading of the work, not the work.', FALSE, 'ProcedureVersions.ExpertsEvaluateAiNotRepresentation=1/9; ProcedureVersions.IsApprovedWithoutSmeSignoff=5/9; RepresentationReviews.ReviewerIsAffectedSme=3/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

