VALUES ('q7-steward-reconciled-views', 'process-steward', 'loop-07', 'Which differing accounts of how work flows came out in sessions, and were they reconciled?', 'Surfacing a disagreement without settling it leaves two procedures in practice and one on paper.', FALSE, 'WorkflowViewDivergences.IsReconciled=1/2; WorkflowViewDivergences.IsSurfacedButUnreconciled=1/2', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q7-authority-blended-elicitation', 'knowledge-authority', 'loop-07', 'Was each version''s knowledge elicited with complementary methods, including workshops, interviews, observation and a settled disagreement?', 'Every method sees part of the practice; one method alone gives a partial picture that looks complete.', FALSE, 'ProcedureVersions.MissesARequiredElicitationMode=3/9; ProcedureVersions.ReliesOnSingleMethod=2/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q7-ke-skilled-specific-capture', 'knowledge-engineer', 'loop-07', 'Was each session run with an elicitation method by someone skilled at capturing process knowledge, and what did each method trade away?', 'Generic knowledge handling by whoever is available loses exactly the tacit part the session was for.', FALSE, 'ElicitationSessions.FacilitatorIsKnowledgeEngineer=10/13; ElicitationSessions.IsGenericOrUnskilledCapture=3/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q7-ke-field-researcher', 'knowledge-engineer', 'loop-07', 'For each version I elicited, did I go where the work is done, like a field researcher, or only interview from the desk?', 'Process knowledge lives in the setting; a knowledge engineer who never visits studies the account, not the practice.', FALSE, 'ElicitationSessions.IsKeFieldSession=9/13; ProcedureVersions.IsStudiedOnlyFromTheDesk=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

