VALUES ('q7-ke-tacit-protocols', 'knowledge-engineer', 'loop-07', 'What did the protocols draw out: mental models, automatic heuristics, reviewed recordings, and how tacit and how lossy was each fragment?', 'Tacit knowledge is captured as models, heuristics and reasons, and the capture must record what it could not carry.', FALSE, 'ElicitationSessions.IsReviewedRecording=1/13; ExpertCognitions.AppliedAutomatically=2/3; ExpertCognitions.IsAutomaticHeuristic=2/3; ExpertCognitions.IsMentalModel=1/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

