VALUES ('q7-authority-flattened-rules', 'knowledge-authority', 'loop-07', 'Which tacit knowledge did we flatten into bare rules, dropping the conditions and exceptions the expert gave?', 'A rule stripped of its conditions fails on the machine it was never meant for, and does so with authority.', FALSE, 'ExpertCognitions.ExpertStatedExceptions=2/3; ExpertCognitions.IsHeuristicOversimplified=1/3; KnowledgeFragments.IsFlattenedToBrittleRule=1/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

