VALUES ('q7-authority-corroboration', 'knowledge-authority', 'loop-07', 'Which approved knowledge rests on a single data point that no second session or practitioner supports?', 'Process knowledge is non-linear; one person''s account on one day is an anecdote until corroborated.', FALSE, 'FragmentCorroborations.Agrees=3/4; KnowledgeFragments.RestsOnSingleDataPoint=8/12', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

