VALUES ('q7-ke-seci-conversions', 'knowledge-engineer', 'loop-07', 'How did the lockout knowledge move between tacit and explicit form, and is each conversion typed consistently?', 'Mislabelled conversions hide that a retyped document was treated as captured expertise.', FALSE, 'KnowledgeConversions.IsModeInconsistentWithForms=1/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

