VALUES ('q7-opsmgr-knowledge-locations', 'plant-operations-manager', 'loop-07', 'Where did the plant''s lockout knowledge live before we encoded it, and where does it live now?', 'Knowledge in operators'' heads, manual margins and departing staff leaves with them; the move to the rulebook is the point.', FALSE, 'KnowledgeHoldings.HandlesExceptionOrDiscretion=7/10; KnowledgeHoldings.HolderIsVeteran=5/10; KnowledgeHoldings.IsJudgmentOutsideDocument=5/10; KnowledgeHoldings.IsProceduralKnowledge=4/10; KnowledgeHoldings.IsUnformalizedProcessKnowledge=6/10; KnowledgeHoldings.IsUnsaidInSop=5/10; KnowledgeHoldings.IsVeteranDiscretion=3/10; ProcedureVersions.LivesInHandsSilenceAndNegotiation=1/9; ProcedureVersions.TacitShareExceedsExplicit=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

