VALUES ('q7-authority-formalized-without-work', 'knowledge-authority', 'loop-07', 'Which knowledge did we formalize without anyone observing, interviewing or extracting it?', 'Formalizing is deliberate work; a note retyped into the rulebook inherits the rulebook''s authority without earning it.', FALSE, 'KnowledgeHoldings.IsFormalizedWithoutElicitationWork=1/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

