VALUES ('q7-opsmgr-knowledge-tests', 'plant-operations-manager', 'loop-07', 'Did the lockout knowledge tests improve competency gaps, quality, efficiency, satisfaction and consistency?', 'Tests are justified by what they improve; an outcome that did not move says where the programme falls short.', FALSE, 'KnowledgeTestOutcomes.HigherIsBetter=2/5; KnowledgeTestOutcomes.IsImproved=4/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

