VALUES ('aq-pkm2-q06', 'knowledge-engineer', 'loop-12', 'Who actually holds each piece of our process know-how right now: which person, plant or system, in which form, and is that person still here?', 'Collection that follows the org chart misses the people, plants and systems where the know-how really sits.', FALSE, 'KnowHowCarriers.HolderIsStillEngaged=5/13; KnowHowCarriers.IsHeldByCurrentPractitioner=5/13; KnowHowCarriers.IsHeldInBothForms=3/13; KnowHowCarriers.IsInWrittenProcedure=6/13; KnowHowCarriers.IsTrainedSkill=10/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

