VALUES ('aq-pkm2-q07', 'knowledge-engineer', 'loop-12', 'When a technician asks where some know-how lives, who can point them to the person who holds it, without holding it themselves?', 'Brokers know where knowledge is held; that meta-knowledge is how seekers find holders across the organization.', FALSE, 'KnowledgeBrokerLinks.LocatesOtherHolder=1/8', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

