VALUES ('q12-steward-knowledge-decay', 'process-steward', 'loop-12', 'Which procedures depend on documentation that has gone stale, or on know-how held only by people who have left?', 'Documents, training and mentoring decay; unless decay is detected, the register looks complete while it is not.', FALSE, 'KnowHowCarriers.IsHeldOnlyByDeparted=2/13; KnowledgeRepositoryEntries.IsStale=1/8; Procedures.HasDecayedTransferChannel=2/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

