VALUES ('q12-ke-social-holders', 'knowledge-engineer', 'loop-12', 'Is there uncaptured know-how held by someone still here whom no collection effort has approached?', 'Process knowledge is distributed across a social network; collection that ignores who holds it socially misses it.', FALSE, 'KnowHowCarriers.IsOverlookedLivingHolder=3/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

