VALUES ('q12-ke-network-analysis', 'knowledge-engineer', 'loop-12', 'Who connects our communities of practice, and did a network analysis find them, or are some connectors invisible to us?', 'People who bridge groups know things no single practitioner does; they are found by network analysis, not by title.', FALSE, 'Agents.IsBoundarySpanner=3/55; Agents.IsUnidentifiedBoundarySpanner=2/55; CommunityMemberships.IsExternalMember=4/9; CommunityMemberships.IsSpecialist=3/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

