VALUES ('q12-ke-negotiation', 'knowledge-engineer', 'loop-12', 'Where a power imbalance shapes what a source will tell me, have I negotiated how their knowledge is collected and used?', 'Collection is a negotiation; ignoring rank, supervisors in the room or job-security fears gets a sanitized account.', FALSE, 'SourceRelationships.IsUnnegotiatedPowerGap=1/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

