VALUES ('q12-ke-source-trust', 'knowledge-engineer', 'loop-12', 'With which sources is trust not established, and am I doing anything to build it?', 'Sources withhold to protect status or job security; only trust built over time changes what they share.', FALSE, 'SourceRelationships.IsExtractiveRelationship=1/4; SourceRelationships.WithholdingObserved=2/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

