VALUES ('q12-authority-direct-engagement', 'knowledge-authority', 'loop-12', 'Which procedures did we capture only by machine, without engaging a single practitioner?', 'Automation can summarize manuals; it cannot collect what practitioners know and never wrote down.', FALSE, 'KnowledgeRepositoryEntries.IsMachineAuthored=1/8; Procedures.IsCapturedByAutomationAlone=1/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

