VALUES ('q12-authority-expertise-credit', 'knowledge-authority', 'loop-12', 'Which repository entries record someone''s expertise without crediting them?', 'Expertise that goes uncredited stops being offered.', FALSE, 'KnowledgeRepositoryEntries.CreditsSourceExpert=6/8; KnowledgeRepositoryEntries.IsUncreditedExpertKnowHow=1/8', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

