VALUES ('q12-vp-memory-intact', 'vp-engineering', 'loop-12', 'As people leave, how much of what they knew did we keep, and does the repository outlive its authors?', 'Organizational memory that walks out with each departure has to be rebuilt by every successor.', FALSE, 'KnowHowCarriers.IsCaptured=3/13; KnowHowCarriers.IsHeldByDepartedHolder=6/13; KnowledgeRepositoryEntries.AuthorIsStillEngaged=7/8; KnowledgeRepositoryEntries.OutlivesAuthorTenure=1/8; Organizations.MemoryLeavesWithStaff=1/18', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

