VALUES ('q12-ops-feedback-loop', 'plant-operations-manager', 'loop-12', 'Which procedures do we execute without anything learned in execution being written back into their documentation?', 'Without a feedback loop from doing the work, procedural knowledge cannot be captured or kept current.', FALSE, 'KnowledgeRepositoryEntries.IsExecutionFeedback=3/8; Procedures.IsExecutedWithoutFeedbackLoop=1/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

