VALUES ('q12-vp-culture-values-documentation', 'vp-engineering', 'loop-12', 'Do we give people time for documentation and knowledge transfer, or does most of it happen on their own time?', 'A culture that values documentation budgets for it; one that does not gets it only from goodwill until goodwill runs out.', FALSE, 'KnowledgeRepositoryEntries.AuthoredOnAllocatedTime=6/8; KnowledgeTransfers.OnAllocatedTime=7/9; Organizations.TreatsKnowledgeWorkAsUnvalued=1/18', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

