VALUES ('aq-pkm3-q06', 'release-manager', 'loop-12', 'Has the problem in front of me been solved before?', 'Solving a problem again from scratch wastes the time the first fix cost and repeats its risks.', FALSE, 'ProblemOccurrences.HasBeenSolvedBefore=3/5; ProblemOccurrences.IsSolved=4/5; ProblemOccurrences.PriorWasSolved=3/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

