VALUES ('aq-pkm3-q09', 'release-manager', 'loop-12', 'Who handled this problem last time, and are they still here to consult?', 'A specialist who solved it before is the fastest route to a fix, but only while they remain.', FALSE, 'ProblemOccurrences.HasConsultableSpecialist=2/5; ProblemOccurrences.PriorSolverIsStillEngaged=2/5; ProblemOccurrences.SolverIsStillEngaged=3/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

