VALUES ('q12-release-record-solutions', 'release-manager', 'loop-12', 'Which solved problems have no recorded solution, and which came back because the earlier fix was never written down?', 'A fix that lives only in the solver''s head is lost the day the solver moves on.', FALSE, 'ProblemOccurrences.IsRelearnedSolvedProblem=1/5; ProblemOccurrences.IsSolvedWithoutRecordedSolution=1/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

