VALUES ('q12-ke-knowledge-network', 'knowledge-engineer', 'loop-12', 'Does our know-how build on related know-how in the same community, and does it span physical and digital work with people in the loop?', 'Know-how about related components compounds when concentrated in one community; scattered, it fragments.', FALSE, 'CommunitiesOfPractice.SpansPhysicalAndDigitalWithHumans=1/7; KnowHowCarriers.BuildsOnSameCommunityKnowHow=2/13', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q12-ops-practice-cluster', 'plant-operations-manager', 'loop-12', 'Is there a cluster where several firms share engineering practice, people move between firms, and specialists are at hand?', 'Such a cluster is where process knowledge compounds; our suppliers'' know-how reaches us through it.', FALSE, 'CommunitiesOfPractice.IsCrossFirmPracticeCluster=1/7', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q12-ops-apprentice-intake', 'plant-operations-manager', 'loop-12', 'In clusters where know-how circulates as people move between firms, are the apprenticeship places being filled?', 'Circulation needs new people entering the trade; when apprenticeships go unfilled the circulation ends with the last generation.', FALSE, 'CommunitiesOfPractice.IsCirculationEndingForLackOfApprentices=1/7; Mentorships.IsRecentApprenticeship=2/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q12-ops-ambient-trade', 'plant-operations-manager', 'loop-12', 'Where a trade is concentrated in one place, does its know-how reach people who do not practise it?', 'Ambient know-how is the deepest sign a trade has settled in a place, and a pool of future recruits.', FALSE, 'CommunitiesOfPractice.HasAmbientTradeKnowHow=1/7; CommunitiesOfPractice.IsColocatedTrade=1/7; KnowledgeTransfers.IsAmbientAbsorptionByNonPractitioner=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q12-ops-erosion-stages', 'plant-operations-manager', 'loop-12', 'Did our training-and-retention cycle erode stage by stage: facility investment, then engineer training, then how-to-make upkeep?', 'Each stage feeds the next; seeing the sequence tells us where rebuilding has to start.', FALSE, 'CapabilityDeclines.FollowsPrecedingStageDecline=2/4; Organizations.ErodedInStages=1/18', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q12-ops-knowhow-carriers', 'plant-operations-manager', 'loop-12', 'Is our how-to-build knowledge carried by people, plants and systems together, or by only some of them?', 'Manufacturing know-how lives in the workforce, the plants and the systems doing the work; losing any carrier loses part of it.', FALSE, 'Organizations.HoldsKnowHowInPeoplePlantsAndSystems=1/18', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q12', 'knowledge-engineer', 'loop-13', 'For this step, which collected material does it trace to: which transcript, field notes, document excerpt or event trace?', 'A step that traces to nothing cannot be checked, defended or updated when its source changes.', FALSE, 'Steps.HasCollectionEvidence=7/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-knowledge-engineer-models-trace-to-collection', 'knowledge-engineer', 'loop-13', 'Does every process model, every step definition and every constraint we encoded trace back to the collection activity that produced it?', 'Organized knowledge with no trace to a collection activity is an assertion nobody can audit.', FALSE, 'ProcedureVersions.IsLiveModelUntraced=5/9; Requirements.IsUntracedBoundConstraint=14/16; Steps.IsUntracedActivityInTracedModel=10/41', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q13', 'process-steward', 'loop-13', 'Has the document this knowledge was taken from been revised since we took it?', 'Knowledge taken from a source that has since changed may no longer say what the source says.', FALSE, 'KnowledgeTraces.IsSourceChangedSinceTaken=5/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q14', 'process-steward', 'loop-13', 'This source was revised: which process models, steps and constraints that we organized from it are affected?', 'Without the dependency, a revised source silently leaves stale knowledge in the model.', FALSE, 'CollectedSourceMaterials.HasKnowledgeAffectedBySourceChange=2/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-process-steward-change-visibility', 'process-steward', 'loop-13', 'Which collected materials did we encode into a model without recording what rests on them, so that a change to them would reveal nothing?', 'A dependency that was never recorded cannot be revealed when the source changes.', FALSE, 'CollectedSourceMaterials.IsDependencyInvisibleToChange=1/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-knowledge-authority-fidelity', 'knowledge-authority', 'loop-13', 'Where does a modeled step say something different from the source it was taken from?', 'Traceability is only worth keeping if it lets us check the model still represents its sources faithfully.', FALSE, 'KnowledgeTraces.IsUnfaithfulToSource=1/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-knowledge-engineer-evidence-kind', 'knowledge-engineer', 'loop-13', 'Is each claim cited to the kind of evidence that can support it: interviews for how a step is described, observation for workarounds, logs for what really ran?', 'A claim about real execution that rests on an interview is hearsay, however confident the speaker.', FALSE, 'CollectedSourceMaterials.IsPracticeEvidence=4/15; KnowledgeTraces.IsAspectUnsupportedBySourceKind=1/15; KnowledgeTraces.SourceIsPracticeEvidence=2/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm1-q08', 'internal-compliance-auditor', 'loop-13', 'For this knowledge item, where did it come from, how was it produced, and who confirmed it?', 'An auditor cannot rely on an item whose origin, route or confirmation is missing.', FALSE, 'KnowledgeTraces.HasIncompleteProvenance=1/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q38', 'knowledge-authority', 'loop-13', 'How was this piece of knowledge derived, and by a person or by a machine?', 'Knowledge a machine extracted needs a different kind of review from knowledge a person paraphrased.', FALSE, 'KnowledgeTraces.IsMachineDerived=1/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q39', 'knowledge-authority', 'loop-13', 'Who validated this piece of knowledge, and was it someone other than the person who derived it?', 'A derivation confirmed only by its own author has not been independently validated.', FALSE, 'KnowledgeTraces.IsSelfValidated=1/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-knowledge-engineer-document-starting-point', 'knowledge-engineer', 'loop-13', 'For steps we took from existing documents, has capture from the people who do the work since confirmed them, and added what the documents leave out?', 'Documents describe the prescribed process; only people who perform it can confirm it and supply what is missing.', FALSE, 'CollectedSourceMaterials.IsDocumentSource=5/15; CollectedSourceMaterials.IsPeopleCapture=7/15; KnowledgeTraces.IsDocumentOrigin=8/15; KnowledgeTraces.IsDocumentStartNeverExtended=3/15; KnowledgeTraces.IsDocumentStartNeverValidated=2/15; KnowledgeTraces.SourceIsDocument=8/15; KnowledgeTraces.SourceIsPeopleCapture=6/15', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm4-q13', 'plant-operations-manager', 'loop-13', 'Which of our procedures are documented in a way that trails how they are actually performed?', 'Operators follow the practice; auditors and new hires follow the document. Where they differ, one of them is wrong.', FALSE, 'KnowledgeTraces.IsDocumentTrailingPractice=1/15; ProcedureVersions.IsDocumentedBehindPractice=1/9; Resources.IsBehindCurrentPractice=1/19', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-knowledge-engineer-mining-complement', 'knowledge-engineer', 'loop-13', 'Where mining found cases that did not follow the procedure, have we asked experienced workers why?', 'An event log shows what was done, never the reasoning or tacit judgment behind it.', FALSE, 'CollectedSourceMaterials.HoldsReasoningOrTacitKnowledge=4/15; ProcessMiningRuns.IsDeviationUnexplainedByPeople=3/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm1-q13', 'knowledge-engineer', 'loop-13', 'Which hand-offs in the flow mined from our event logs are not in the process logic we intended?', 'A path the model does not contain is either an undocumented practice or a control being bypassed.', FALSE, 'MinedFlowEdges.IsUndocumentedPath=2/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q15', 'release-manager', 'loop-13', 'In which of our procedures does the process as enacted deviate from the documented one?', 'A release process that is enacted differently from its documentation is not governed by it.', FALSE, 'ProcessMiningRuns.HasUndocumentedEnactedPath=1/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm2-q16', 'release-manager', 'loop-13', 'Where in the mined release flow do cases sit waiting far longer than the next step should take?', 'Waiting is where release lead time goes, and where people start looking for a way around the gate.', FALSE, 'MinedFlowEdges.IsBottleneck=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-knowledge-authority-mined-versus-intended', 'knowledge-authority', 'loop-13', 'Has any mined behavior been recorded as intended process logic without anyone deciding that it should be?', 'A log records what happened, not what should happen; promoting it silently makes a workaround normative.', FALSE, 'MinedFlowEdges.IsMinedPathRecordedAsIntentWithoutDecision=1/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm1-q09', 'process-steward', 'loop-13', 'Which stakeholder perspectives on this process conflict, and which collected material does each come from?', 'Legitimate disagreement is information about the process; its source tells us whose experience it reflects.', FALSE, 'StakeholderPerspectives.IsInConflict=4/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-process-steward-dissent-kept', 'process-steward', 'loop-13', 'Did we collapse a legitimate disagreement into one agreed version, or keep a dissenting view without its source?', 'Forcing consensus discards the knowledge of whoever lost the argument.', FALSE, 'StakeholderPerspectives.IsDissentingViewNotKeptWithSource=1/5', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-process-steward-capture-in-work', 'process-steward', 'loop-13', 'For which procedures do we only collect knowledge in separate exercises and never while the work is being done?', 'Capture that waits for a workshop loses what people notice in the moment.', FALSE, 'CollectedSourceMaterials.IsCapturedInFlowOfWork=1/15; Procedures.IsCaptureSeparateFromWork=2/10', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-process-steward-collection-occasions', 'process-steward', 'loop-13', 'Are our retrospectives, process reviews and improvement initiatives held on cadence, and does what they surface get collected?', 'A recurring occasion that is skipped, or held and not captured, is a collection channel that has quietly closed.', FALSE, 'CollectionOccasions.IsHeldWithoutCapture=1/3; CollectionOccasions.IsLapsed=1/3', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-knowledge-engineer-feedback-into-collection', 'knowledge-engineer', 'loop-13', 'When a practitioner''s feedback reveals know-how the procedure lacks, did it prompt us to go and collect it?', 'Feedback is the cheapest discovery channel for tacit knowledge; unfollowed, it is lost with the ticket.', FALSE, 'UserFeedback.IsTacitSignalNotFedIntoCollection=1/6; UserFeedback.RevealsTacitKnowledge=2/6', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('q13-knowledge-engineer-acquisition-cost', 'knowledge-engineer', 'loop-13', 'How many hours of our domain experts'' time has capturing each procedure''s knowledge taken?', 'Acquisition is paid for in expert time, by people whose job is not knowledge modeling.', FALSE, NULL, 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO role_questions (role_question_id, asking_role, witness_loop, question_text, why_it_matters, answerable_before, witnessed_answer, semantic_type_iri)
VALUES ('aq-pkm3-q11', 'plant-safety-officer', 'loop-13', 'How has this procedure failed before, how was each failure recorded, and what redesign followed?', 'A failure that is recorded but never fed into a redesign will happen again at the next run.', FALSE, 'IssueOccurrences.IsFailureWithoutLandedRedesign=3/4', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

