VALUES ('q13-knowledge-authority-tacit-behind-compliance', 'knowledge-authority', 'loop-13', 'Which procedures did we standardize for compliance without capturing the tacit knowledge that makes them work?', 'A compliant document does not carry the judgment of the people who perform it.', FALSE, 'ProcedureVersions.IsStandardizedWithoutTacitCapture=1/9', 'urn:effortless:pko-extension#RoleQuestion') ON CONFLICT (role_question_id) DO UPDATE SET asking_role = EXCLUDED.asking_role, witness_loop = EXCLUDED.witness_loop, question_text = EXCLUDED.question_text, why_it_matters = EXCLUDED.why_it_matters, answerable_before = EXCLUDED.answerable_before, witnessed_answer = EXCLUDED.witnessed_answer, semantic_type_iri = EXCLUDED.semantic_type_iri;

