VALUES ('analyst-home', '/finance-analyst/my-work', 'My Steps', 'domain', 'finance-analyst', 'execution', 1, 'dashboard', 'The steps I personally executed, and whether each one closed cleanly or closed past something.', 'Card per step execution with status, duration vs expected, and blocking-control state. Anything that closed past a blocking control is the emphasis.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

