VALUES ('analyst-blocking-unmet', '/finance-analyst/my-work/blocking-unmet', 'Closed Past a Control', 'domain', 'finance-analyst', 'execution', 2, 'workspace', 'On the steps I personally executed, did any close out while a BLOCKING requirement was still not fully satisfied?', 'List of my step executions with an unmet blocking control, each showing the control and its satisfaction level. This is a personal-exposure screen — keep it short and unambiguous.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

