VALUES ('analyst-stale-then-vs-now', '/finance-analyst/evidence/stale-then-vs-now', 'Stale Then vs Stale Now', 'domain', 'finance-analyst', 'evidence', 4, 'workspace', 'Was the source stale AT THE MOMENT I RAN, or has it merely gone stale since — and are those the same steps?', 'Two-column comparison: staleness at run-time vs staleness at the current evaluation context. The delta between the columns is the whole point of the screen.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

