VALUES ('analyst-clean-but-uncovered', '/finance-analyst/quality/clean-but-uncovered', 'Clean, or Just Unchecked', 'domain', 'finance-analyst', 'quality', 1, 'workspace', 'Of the executions that ARE clean, how many are clean because everything was checked and passed, versus clean because there was almost nothing checking them?', 'Scatter or two-axis table: controls-checked against controls-passed. Low-check/high-pass is the quadrant of interest and should be labelled as such.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

