VALUES ('analyst-mute-clearance', '/finance-analyst/quality/cleared-by-mute-control', 'Cleared by a Mute Control', 'domain', 'finance-analyst', 'quality', 2, 'workspace', 'How many of the blocking controls that cleared me have NEVER produced a negative outcome anywhere in this model — and were any of my steps cleared ONLY by controls of that kind?', 'Per step: clearing controls, each tagged with whether it has ever fired negative. A step cleared exclusively by never-fired controls is the headline finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

