VALUES ('hr-unapproved-claims', '/hr-policy-owner/ownership/unapproved', 'Unapproved in My Name', 'domain', 'hr-policy-owner', 'ownership', 2, 'workspace', 'Which claims am I the owner of that were never approved — and are any of them routing real cases right now?', 'List of owned fragments by status, with an ''operationally live'' flag. Reviewed-but-not-Approved AND live is the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

