VALUES ('hr-load-bearing-claim', '/hr-policy-owner/ownership/blast-radius/:fragmentId', 'Blast Radius of a Claim', 'domain', 'hr-policy-owner', 'ownership', 3, 'detail', 'How many steps, exceptions and authority boundaries currently depend on a claim I have not signed, and how long has it been sitting at Reviewed?', 'Dependency fan-out from one fragment: steps, exceptions, boundaries. Header carries the age at Reviewed. This is the screen that makes an unsigned claim feel expensive.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

