VALUES ('hr-backlog', '/hr-policy-owner/backlog', 'Waiting On Me', 'domain', 'hr-policy-owner', 'backlog', 1, 'workspace', 'What decisions are waiting on me personally, and how long have they been waiting.', 'Queue ordered by age. Each item shows what it blocks downstream, so the cost of my delay is visible from the queue itself.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

