VALUES ('hr-backlog-downstream', '/hr-policy-owner/backlog/downstream', 'What My Delay Blocks', 'domain', 'hr-policy-owner', 'backlog', 2, 'workspace', 'The full chain from my inbox outward: which knowledge gaps stay open because I have not decided, which steps sit downstream, and how many days of that delay are mine personally.', 'Chain view: my pending decision → blocked gap → downstream steps. Attribute delay days to me vs to the process explicitly; do not conflate them.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

