VALUES ('hr-my-decisions', '/hr-policy-owner/backlog/my-decisions', 'What I Have Cleared', 'domain', 'hr-policy-owner', 'backlog', 3, 'workspace', 'How many decisions have I made that the model still displays as outstanding against me? I cannot show what I have actually cleared.', 'Decision history with the terminal-state problem surfaced: Approved requests still counted open are flagged as a model defect, not hidden.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('hr-ai-boundary', '/hr-policy-owner/governance/ai-boundary', 'Is the AI Boundary Held', 'domain', 'hr-policy-owner', 'governance', 1, 'workspace', 'kf-policy-ai-boundary says AI may draft but may not create legal commitments. Is that boundary actually being held?', 'Per boundary: assigned agent, executions, and whether a violation was possible. Pair every ''no violation'' with an ''ever approached'' count — the two together are the real answer.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

