VALUES ('hr-knowledge-half-life', '/hr-policy-owner/governance/knowledge-half-life', 'Knowledge Half-Life', 'domain', 'hr-policy-owner', 'governance', 2, 'workspace', 'Is the policy I own now resting on knowledge older than the policy itself has been reviewed?', 'Timeline: elicitation dates, version issue date, review cadence, next due. The comparison between knowledge age and review interval is the headline.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

