VALUES ('hr-departed-holders', '/hr-policy-owner/governance/departed-holders', 'What Departed With Them', 'domain', 'hr-policy-owner', 'governance', 3, 'workspace', 'Somebody''s assignment ended. Did anything they owned or sourced go with them — claims, gaps, pending decisions — or did the departure genuinely leave nothing behind?', 'Per departed assignment: everything sourced or owned by that agent, with current ownership state. Orphaned items are the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

