VALUES ('hr-what-was-sent', '/hr-policy-owner/delivery/what-was-sent', 'What Was Actually Sent', 'domain', 'hr-policy-owner', 'delivery', 1, 'workspace', 'If an employee disputes what they received, can I show that what was sent matched what I approved?', 'Per delivery: approved text vs transmitted text, side by side, with the approval record and date. A mismatch is the finding; identical is stated explicitly.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

