VALUES ('counsel-home', '/employment-counsel/compliance', 'Compliance Gates', 'domain', 'employment-counsel', 'compliance', 1, 'dashboard', 'The four gates I care about — consent, quiet hours, legal review, retention — each as a pass/fail with the breaching rows named.', 'Four gate tiles across the top; a breach list beneath whichever is selected. A gate with zero breaches must distinguish ''checked and clean'' from ''never evaluated''.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

