VALUES ('counsel-consent', '/employment-counsel/compliance/consent', 'SMS Without Consent', 'domain', 'employment-counsel', 'compliance', 2, 'workspace', 'Did we send an SMS to any recipient who had not given SMS consent at the moment we sent it?', 'Per SMS delivery: recipient, consent state at send time, verdict. Bitemporal — consent today is not the question.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

