VALUES ('counsel-quiet-hours', '/employment-counsel/compliance/quiet-hours', 'Quiet Hours', 'domain', 'employment-counsel', 'compliance', 3, 'workspace', 'Did any SMS go out between 20:00 and 08:00 in the recipient''s own local time?', 'Per delivery: send instant, recipient timezone, local hour, verdict. Show the local-time conversion explicitly — the timezone is the whole difficulty.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

