VALUES ('counsel-legal-review', '/employment-counsel/compliance/legal-review', 'Sent Before My Review', 'domain', 'employment-counsel', 'compliance', 4, 'workspace', 'Did any message go out before my legal review of the underlying policy version was actually complete?', 'Timeline per campaign: review completion vs first transmission. Sends preceding review completion are the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

