VALUES ('counsel-retention', '/employment-counsel/compliance/retention', 'Retention Evidence', 'domain', 'employment-counsel', 'compliance', 5, 'workspace', 'Do we still hold the exact text of every message we sent, for the full 2555-day retention period the policy commits us to?', 'Per delivery: text retained?, retention deadline, days remaining. Missing text is a breach and must render as one.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

