VALUES ('counsel-unreachable', '/employment-counsel/compliance/unreachable', 'Unreachable, Not Acknowledged', 'domain', 'employment-counsel', 'compliance', 6, 'workspace', 'For every recipient we could not reach, did we correctly refrain from marking their acknowledgement complete?', 'Per unreachable recipient: delivery state, acknowledgement state. An acknowledgement on an unreachable recipient is the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

