VALUES ('comms-home', '/communications-manager/delivery', 'Campaign Board', 'domain', 'communications-manager', 'delivery', 1, 'dashboard', 'For this policy run: who we meant to reach, who we actually reached, and where the rest went.', 'Funnel across the top (intended → sent → delivered → acknowledged), with each drop-off clickable into the rows that fell out.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

