VALUES ('comms-yield', '/communications-manager/delivery/yield', 'Approval-to-Delivery Yield', 'domain', 'communications-manager', 'delivery', 2, 'workspace', 'Of everybody the pipeline intended to contact, what fraction actually received it — and where exactly did the rest go?', 'Sankey or stepped funnel with an explicit terminal bucket for every loss: refused, bounced, suppressed, deferred. No row may vanish without a bucket.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

