VALUES ('comms-failed-deliveries', '/communications-manager/delivery/failed', 'Bounced and Unworked', 'domain', 'communications-manager', 'delivery', 3, 'workspace', 'How many recipients are sitting in a bounced or failed state that nobody is working?', 'Worklist, not a report: each failed delivery with age and owner. Unowned failures sort first.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

