VALUES ('comms-frozen-approval', '/communications-manager/governance/frozen-approval/:deliveryId', 'Freeze What I Approved', 'domain', 'communications-manager', 'governance', 3, 'detail', 'For a message we sent last month, can I still show what I approved — the exact text, the exact approval, on the exact date — without that answer changing the next time somebody edits the template?', 'Immutable snapshot view: the text as sent, the approval as given. Must read from the frozen delivery record, never from the live template.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

