INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('comms-engagement', '/communications-manager/audience/engagement', 'Why Nobody Answered', 'domain', 'communications-manager', 'audience', 1, 'workspace', 'One acknowledgement out of six deliveries. Is that because employees ignored us, or because the messages that landed were the least likely to be answered — wrong channel, wrong template, sent into the small hours?', 'Cross-tab of acknowledgement rate by channel, template, and send hour. The point is to separate audience apathy from our own targeting.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

