VALUES ('comms-suppression', '/communications-manager/audience/suppression', 'Correctly Refused, Then Forgotten', 'domain', 'communications-manager', 'audience', 2, 'workspace', 'When we correctly refused to reach somebody, did anyone ever go back and reach them another way — or does ''correctly refused'' quietly mean ''never communicated with again''?', 'Per suppressed recipient: the refusal reason, and any subsequent successful contact on another channel. No follow-up is the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

