VALUES ('comms-authorization-override', '/communications-manager/governance/authorization-override', 'Refused, or Overridden', 'domain', 'communications-manager', 'governance', 4, 'workspace', 'When the pipeline refused to send, was it refusing on a rule I set — or overriding an authorization I had already given, for a reason nobody routed back to me?', 'Per refusal: the governing rule, its owner, and whether it contradicts a standing authorization of mine. Contradictions are the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

