VALUES ('close-auto-home', '/close-automation/readiness', 'Pre-Flight', 'domain', 'close-automation', 'readiness', 1, 'dashboard', 'Before I execute anything: am I authorized, are my inputs fresh, and did my last run leave a mess.', 'Four go/no-go tiles (authority, inputs, prior run, controls) resolving to a single may-I-run verdict. Built for a supervisor watching the agent as much as for the agent.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('close-auto-authority', '/close-automation/readiness/authority', 'Am I Authorized', 'domain', 'close-automation', 'readiness', 2, 'workspace', 'Is my own role assignment currently valid, and is the agent named in that assignment actually me?', 'Assignment card: validity window, named agent, identity match. An identity mismatch must halt, not warn.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('close-auto-inputs', '/close-automation/readiness/input-freshness', 'Are My Inputs Fresh', 'domain', 'close-automation', 'readiness', 3, 'workspace', 'Before I extract: is every operational binding this step reads inside its freshness SLA, and is it the authoritative one?', 'Per binding: age, SLA, authoritative flag. Two independent failure modes — stale, and non-authoritative — must not be collapsed into one badge.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('close-auto-controls', '/close-automation/readiness/blocking-controls', 'Controls Scored', 'domain', 'close-automation', 'readiness', 4, 'workspace', 'For each step I am about to run, has every blocking requirement actually been evaluated — or am I about to execute past a control that nobody scored?', 'Per upcoming step: blocking controls and their evaluation state. Unscored controls block the run.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('close-auto-last-run', '/close-automation/readiness/last-run', 'Last Run Clean', 'domain', 'close-automation', 'readiness', 5, 'workspace', 'Did my previous run leave anything unresolved — an open issue, a WARN, or a deviation — that I should refuse to run on top of?', 'Prior-run summary with an explicit refuse-to-proceed state. Unresolved items are listed individually, never summarised to a count alone.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('close-auto-drift', '/close-automation/self-check/override-drift', 'Am I Drifting', 'domain', 'close-automation', 'selfcheck', 1, 'workspace', 'Are humans overriding or correcting my output more often now than they used to?', 'Override rate over time with the baseline period marked. Call out sample size — a trend on three decisions is not a trend.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('variance-home', '/variance-review-agent/self-check', 'Am I Fit to Decide', 'domain', 'variance-review-agent', 'selfcheck', 1, 'dashboard', 'My authority, my boundary, and the currency of the knowledge I triage against — as one verdict.', 'Three-part readiness card: authority provenance, boundary validity, knowledge currency. Any expired component invalidates the whole.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('variance-authority', '/variance-review-agent/self-check/authority', 'By What Authority', 'domain', 'variance-review-agent', 'selfcheck', 2, 'workspace', 'By what authority am I executing close-04, when did that authority begin, who approved it, and who held this role before me?', 'Provenance chain: assignment, approver, start instant, predecessor. The handover is part of the answer, not a footnote.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('variance-handover', '/variance-review-agent/self-check/handover', 'Who Decided a Machine Should Hold This', 'domain', 'variance-review-agent', 'selfcheck', 3, 'workspace', 'Mine is the one non-human assignment with a recorded approving authority. Who decided a machine should hold this role, and on what basis?', 'The approving decision as a first-class record: who, when, rationale. If the basis is absent, say so — do not present the approval alone as sufficient.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('variance-boundary', '/variance-review-agent/governance/boundary', 'Inside My Boundary', 'domain', 'variance-review-agent', 'governance', 1, 'workspace', 'Am I operating inside my approved boundary — or have I made a decision that kf-policy-ai-boundary says only a human may make?', 'Boundary statement, decisions evaluated against it, verdict per decision. Pair with the ''ever tested'' count from the ratification route.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('variance-boundary-ratification', '/variance-review-agent/governance/boundary-ratification', 'My Boundary''s Own Validity', 'domain', 'variance-review-agent', 'governance', 2, 'workspace', 'The boundary that constrains what I am allowed to decide is ratified by a knowledge fragment that is not current. Is the rule governing me still valid?', 'Fragment validity chain behind the boundary. An expired ratifier makes the boundary itself questionable, and the page must say that plainly.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('variance-human-confirmation', '/variance-review-agent/governance/human-confirmation', 'Did a Human Confirm', 'domain', 'variance-review-agent', 'governance', 3, 'workspace', 'close-04''s instruction says ''Use AI triage, then apply human judgment.'' Did a human actually confirm my materiality calls, or did my output pass through unchallenged?', 'Per decision: human confirmation present?, who, when. Unconfirmed decisions on a human-confirmation step are the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('variance-knowledge-currency', '/variance-review-agent/knowledge/currency', 'Is My Knowledge Current', 'domain', 'variance-review-agent', 'knowledge', 1, 'workspace', 'Is the judgment knowledge I triage against still valid, still owned by someone, and has it been reviewed since it was written?', 'Per fragment: validity, owner, last review. An unowned or unreviewed fragment degrades every decision made against it.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

