VALUES ('variance-quality-baseline', '/variance-review-agent/quality/vs-human-baseline', 'Better or Worse Than the Human', 'domain', 'variance-review-agent', 'quality', 1, 'workspace', 'Since I took over, is my triage quality better or worse than maria-chen''s during the prior period?', 'Side-by-side period comparison. Sample size shown at equal prominence to the delta — this is the screen most likely to be over-read.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

