VALUES ('variance-sample-size', '/variance-review-agent/quality/sample-size', 'Is My Comparison Empty', 'domain', 'variance-review-agent', 'quality', 2, 'workspace', 'QualityRegressedVsPredecessor says I have not regressed — on the strength of three decisions. Is my comparison statistically empty?', 'Explicit power/sample-size statement. A verdict computed on too few observations must be rendered as inconclusive, not as a pass.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('variance-override-signal', '/variance-review-agent/quality/override-signal', 'Correction or Judgment', 'domain', 'variance-review-agent', 'quality', 3, 'workspace', 'One of my three decisions was overridden. Was that a correction of an error I made, or a human exercising judgment I was never authorized to exercise?', 'Per override: my decision, the human''s decision, the stated reason, and which of the two categories it falls in. Uncategorised overrides are themselves a gap.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('variance-stop-condition', '/variance-review-agent/self-check/stop-condition', 'What Would Make Me Stop', 'domain', 'variance-review-agent', 'selfcheck', 4, 'workspace', 'Every witness in this model detects something after it has happened. Is there any condition, computed and named, that would stop me before I act?', 'Inventory of stop conditions: pre-act vs post-hoc. If none are pre-act, the page must state that as the finding rather than listing post-hoc witnesses as if they qualified.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

