VALUES ('policy-agent-home', '/policy-drafting-agent/readiness', 'May I Draft', 'domain', 'policy-drafting-agent', 'readiness', 1, 'dashboard', 'Before I draft: approved sources, valid bindings, and a role assignment that actually exists.', 'Go/no-go card combining source approval, binding freshness, and assignment presence. A missing assignment is a hard stop.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

