VALUES ('policy-agent-sources', '/policy-drafting-agent/readiness/sources', 'Approved Sources', 'domain', 'policy-drafting-agent', 'readiness', 2, 'workspace', 'Is every resource I am about to read an approved source, and is its binding still inside its freshness window?', 'Per source: approval state, binding age, SLA. Unapproved or stale sources block the draft.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

