VALUES ('policy-agent-assignment', '/policy-drafting-agent/readiness/my-assignment', 'Do I Have an Assignment', 'domain', 'policy-drafting-agent', 'readiness', 3, 'workspace', 'I am named as CurrentAgent and I executed se-policy03 — but is there any RoleAssignment actually granting me that authority?', 'The absence is the finding. If no assignment exists, render that as a violation state, never as an empty list.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

