VALUES ('policy-agent-commitment-boundary', '/policy-drafting-agent/governance/commitment-boundary', 'Did I Create a Commitment', 'domain', 'policy-drafting-agent', 'governance', 1, 'workspace', 'Did I draft language that creates a new legal commitment — the one thing kf-policy-ai-boundary says I may not do?', 'Per draft: commitment-creating language detected?, the boundary text, verdict. Pair with whether the gate was ever exercised.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

