VALUES ('steward-open-gaps', '/process-steward/knowledge/open-gaps', 'Live With a Blocking Gap', 'domain', 'process-steward', 'knowledge', 1, 'workspace', 'Is any procedure version live with an Open BLOCKING knowledge gap against it?', 'Per version: open gaps by severity, blocking flag, owner. Live-and-blocking is the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

