VALUES ('steward-stalled-changes', '/process-steward/governance/stalled-changes', 'Stalled Change Requests', 'domain', 'process-steward', 'governance', 1, 'workspace', 'cr-policy-delivery was requested on 2026-07-19 with no DecidedAt. How long has it been sitting, and is that inside what we promised?', 'Queue by age with the promised decision window marked. Overdue rows are the working list.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('steward-approved-never-lands', '/process-steward/governance/approved-never-lands', 'Approved but Still Open', 'domain', 'process-steward', 'governance', 2, 'workspace', 'cr-close-timestamp is Approved, and the model still reads it as OPEN because IsOpen counts Approved as open. Every version it touches reads permanently unfit.', 'Surface this as a MODEL DEFECT panel, not a data problem: the terminal-state gap, the rows it distorts, and the downstream verdicts it poisons.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('steward-orphans', '/process-steward/ownership/orphan-versions', 'Versions With No Steward', 'domain', 'process-steward', 'ownership', 1, 'workspace', 'Which procedure versions have no steward at all? close-v1.0.0 is Archived but still referenced.', 'Per version: steward or none, status, inbound references. Unstewarded-but-referenced is the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

