VALUES ('steward-archived-still-referenced', '/process-steward/ownership/archived-referenced', 'Archived, Still Load-Bearing', 'domain', 'process-steward', 'ownership', 2, 'workspace', 'close-v1.0.0 is Archived and unstewarded — but it is still referenced. What still points at it?', 'Inbound reference list for each archived version. A referenced archive is not retired, and the page should say so.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('steward-fallbacks', '/process-steward/knowledge/untested-fallbacks', 'Untested Recovery Paths', 'domain', 'process-steward', 'knowledge', 2, 'workspace', 'close-04-fallback-close-03 and policy-07-fallback-policy-06 are the paths we take when things go wrong. Have they ever been walked?', 'Per fallback transition: times traversed, last traversal. Zero traversals is the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('steward-fallback-criticality', '/process-steward/knowledge/fallback-criticality', 'Which Untested Path Matters', 'domain', 'process-steward', 'knowledge', 3, 'workspace', 'Four recovery paths have never been walked. An untested path to a trivial step does not scare me; one guarding a blocking control does.', 'Rank untested fallbacks by what they protect — blocking controls downstream, criticality of the target step. Ranking is the contribution here.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('steward-hardcoded-predicates', '/process-steward/model/hardcoded-predicates', 'Predicates Naming Step Ids', 'domain', 'process-steward', 'model', 1, 'workspace', 'Several of my predicates name individual steps by id. Steps.IsHumanApprovalGate hardcodes policy-05 and close-06 — it should key off a control kind instead.', 'Model-quality worklist: predicates containing literal ids, with the generalisation each should use. This is technical debt in the rulebook, presented as such.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

