VALUES ('authority-home', '/knowledge-authority/knowledge', 'Knowledge Register', 'domain', 'knowledge-authority', 'knowledge', 1, 'dashboard', 'Every fragment: its status, its age, its owner, and whether anything live depends on it.', 'Table with decay signals as columns rather than separate screens, so stacked fragility is visible in one pass.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('authority-fragment-decay', '/knowledge-authority/knowledge/compound-fragility', 'Compound Fragility', 'domain', 'knowledge-authority', 'knowledge', 2, 'workspace', 'Four separate decay signals on knowledge fragments and no way to see where they stack. Show me where they compound.', 'One row per fragment, one column per decay signal, plus a stack count. Sort by stack count — a fragment failing on four axes is categorically worse than four failing on one.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO app_routes (app_route_id, route_path, route_name, surface, owning_role, nav_group, nav_order, route_kind, purpose, layout_hints, semantic_type_iri)
VALUES ('authority-unapproved-live', '/knowledge-authority/knowledge/unapproved-live', 'Unapproved but Live', 'domain', 'knowledge-authority', 'knowledge', 3, 'workspace', 'kf-policy-manager-route is Reviewed, not Approved, so IsCurrentlyValid is FALSE — and policy-08 is a live step depending on it.', 'Per unapproved fragment: dependents, and whether each is live. Live dependents on an invalid fragment are the finding.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

