VALUES ('authority-review-date-inferred', '/knowledge-authority/model/inferred-review-dates', 'Inferred, Not Recorded', 'domain', 'knowledge-authority', 'model', 1, 'workspace', 'IsOverdueForReview reads 6/7 and I do not trust it — it is computed from AgeDays rather than from a recorded review date.', 'Per fragment: inferred review state vs any recorded date. Where no date was ever recorded, say so — do not present the inference as a record.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

