VALUES ('admin-board', '/admin/conformance', 'Test Board', 'maintainer', '', 'conformance', 1, 'dashboard', 'Every check the model runs against itself, and whether the board is green.', 'Green/red banner with a blocking-failure count, then per-suite and per-kind tables, then the filterable check list. Warnings are advisory and must read that way — scoring a non-firing witness red would only pressure someone into fabricating rows until it went green.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

