VALUES ('explorer-tables', '/explorer/tables', 'All Tables', 'maintainer', '', 'inferences', 2, 'workspace', 'Every table with its raw/calculated/lookup/aggregation composition.', 'Table index with a composition bar per row. Infrastructure tables that deliberately have no view are labelled as such, not as broken.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

