VALUES ('explorer-table-detail', '/explorer/tables/:table', 'Table Detail', 'maintainer', '', 'inferences', 3, 'detail', 'One table: its full column catalog and every row, with inferred columns distinguished from stated ones.', 'Column cards above a row grid. Inferred columns are shaded and their cells are clickable for the formula-and-inputs popover.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

