VALUES ('explorer-record', '/explorer/record/:table/:id', 'Record Inspector', 'maintainer', '', 'inferences', 4, 'detail', 'One row, every field it has: stated values first, then each inference with the current value of every field its formula reads.', 'Two sections — stated and inferred. Each inference shows its formula and its inputs, local or across a foreign key, with derived inputs marked so the chain can be walked further back.', 'urn:effortless:pko-extension#AppRoute') ON CONFLICT (app_route_id) DO UPDATE SET route_path = EXCLUDED.route_path, route_name = EXCLUDED.route_name, surface = EXCLUDED.surface, owning_role = EXCLUDED.owning_role, nav_group = EXCLUDED.nav_group, nav_order = EXCLUDED.nav_order, route_kind = EXCLUDED.route_kind, purpose = EXCLUDED.purpose, layout_hints = EXCLUDED.layout_hints, semantic_type_iri = EXCLUDED.semantic_type_iri;

