-- ----------------------------------------------------------------------------
-- ConformanceSubstrates: Every tool that compiles this rulebook into something that computes. One is the answer-key author (compile-rulebook bakes derived values into the rulebook's own rows); the rest are graded substrates that re-derive those values natively and are scored cell by cell against them.
-- ----------------------------------------------------------------------------
INSERT INTO conformance_substrates (conformance_substrate_id, label, transpiler, output_folder, engine, how_it_computes, role, sort_order, semantic_type_iri)
VALUES ('compile-rulebook', 'compile-rulebook', 'compile-rulebook', '/effortless-rulebook', 'Python formula engine (shared with rulebook-to-python)', 'Runs first in the build and rewrites the rulebook in place: every calculated, lookup and aggregation value is computed across all tables to a fixed point and upserted into the rows. Those stored values become the answer keys. It is not graded against itself; when another substrate disagrees, either side can be the one that is wrong.', 'answer-key', 0, 'urn:effortless:pko-extension#ConformanceSubstrate') ON CONFLICT (conformance_substrate_id) DO UPDATE SET label = EXCLUDED.label, transpiler = EXCLUDED.transpiler, output_folder = EXCLUDED.output_folder, engine = EXCLUDED.engine, how_it_computes = EXCLUDED.how_it_computes, role = EXCLUDED.role, sort_order = EXCLUDED.sort_order, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_substrates (conformance_substrate_id, label, transpiler, output_folder, engine, how_it_computes, role, sort_order, semantic_type_iri)
VALUES ('effortless-postgres', 'PostgreSQL', 'rulebook-to-postgres', '/postgres-bootstrap', 'PostgreSQL views and calc_* SQL functions', 'rulebook-to-postgres emits a table, a set of calc_* functions and a vw_<entity> view per table. The database is reset from the rulebook, and the harness reads SELECT * from every view.', 'graded', 1, 'urn:effortless:pko-extension#ConformanceSubstrate') ON CONFLICT (conformance_substrate_id) DO UPDATE SET label = EXCLUDED.label, transpiler = EXCLUDED.transpiler, output_folder = EXCLUDED.output_folder, engine = EXCLUDED.engine, how_it_computes = EXCLUDED.how_it_computes, role = EXCLUDED.role, sort_order = EXCLUDED.sort_order, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_substrates (conformance_substrate_id, label, transpiler, output_folder, engine, how_it_computes, role, sort_order, semantic_type_iri)
VALUES ('effortless-python', 'Python', 'rulebook-to-python', '/effortless-python', 'CPython', 'rulebook-to-python emits an SDK with one computed property per derived field. The harness loads the blank test rows (raw fields only) and asks the SDK for every derived value.', 'graded', 2, 'urn:effortless:pko-extension#ConformanceSubstrate') ON CONFLICT (conformance_substrate_id) DO UPDATE SET label = EXCLUDED.label, transpiler = EXCLUDED.transpiler, output_folder = EXCLUDED.output_folder, engine = EXCLUDED.engine, how_it_computes = EXCLUDED.how_it_computes, role = EXCLUDED.role, sort_order = EXCLUDED.sort_order, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_substrates (conformance_substrate_id, label, transpiler, output_folder, engine, how_it_computes, role, sort_order, semantic_type_iri)
VALUES ('effortless-golang', 'Go', 'rulebook-to-go', '/effortless-golang', 'Go toolchain (compiled)', 'rulebook-to-go emits a Go module. The harness compiles it with go build, runs it over the blank test rows, and reads back every derived value.', 'graded', 3, 'urn:effortless:pko-extension#ConformanceSubstrate') ON CONFLICT (conformance_substrate_id) DO UPDATE SET label = EXCLUDED.label, transpiler = EXCLUDED.transpiler, output_folder = EXCLUDED.output_folder, engine = EXCLUDED.engine, how_it_computes = EXCLUDED.how_it_computes, role = EXCLUDED.role, sort_order = EXCLUDED.sort_order, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_substrates (conformance_substrate_id, label, transpiler, output_folder, engine, how_it_computes, role, sort_order, semantic_type_iri)
VALUES ('effortless-typescript', 'TypeScript', 'rulebook-to-typescript', '/effortless-typescript', 'Node.js running tsc output', 'rulebook-to-typescript emits a typed SDK. The harness compiles it with tsc and runs it on Node over the blank test rows.', 'graded', 4, 'urn:effortless:pko-extension#ConformanceSubstrate') ON CONFLICT (conformance_substrate_id) DO UPDATE SET label = EXCLUDED.label, transpiler = EXCLUDED.transpiler, output_folder = EXCLUDED.output_folder, engine = EXCLUDED.engine, how_it_computes = EXCLUDED.how_it_computes, role = EXCLUDED.role, sort_order = EXCLUDED.sort_order, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_substrates (conformance_substrate_id, label, transpiler, output_folder, engine, how_it_computes, role, sort_order, semantic_type_iri)
VALUES ('effortless-entity-framework', 'C# / Entity Framework', 'rulebook-to-entity-framework', '/effortless-entity-framework', '.NET (C# Formula* properties)', 'rulebook-to-entity-framework emits C# data classes whose Formula* properties compute derived fields. The harness compiles them with EF Core into a runner, loads the blank test rows into the generated context over a throwaway SQLite database, and reads every computed property back per row.', 'graded', 5, 'urn:effortless:pko-extension#ConformanceSubstrate') ON CONFLICT (conformance_substrate_id) DO UPDATE SET label = EXCLUDED.label, transpiler = EXCLUDED.transpiler, output_folder = EXCLUDED.output_folder, engine = EXCLUDED.engine, how_it_computes = EXCLUDED.how_it_computes, role = EXCLUDED.role, sort_order = EXCLUDED.sort_order, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_substrates (conformance_substrate_id, label, transpiler, output_folder, engine, how_it_computes, role, sort_order, semantic_type_iri)
VALUES ('effortless-xlsx', 'Excel', 'rulebook-to-xlsx', '/effortless-xlsx', 'Spreadsheet formulas (cached values read with openpyxl)', 'rulebook-to-xlsx compiles every formula into a real Excel formula over cells in the same workbook. The harness reads the workbook''s cached values, after a LibreOffice recalc when LibreOffice is installed; a value that was never calculated reads as blank.', 'graded', 6, 'urn:effortless:pko-extension#ConformanceSubstrate') ON CONFLICT (conformance_substrate_id) DO UPDATE SET label = EXCLUDED.label, transpiler = EXCLUDED.transpiler, output_folder = EXCLUDED.output_folder, engine = EXCLUDED.engine, how_it_computes = EXCLUDED.how_it_computes, role = EXCLUDED.role, sort_order = EXCLUDED.sort_order, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_substrates (conformance_substrate_id, label, transpiler, output_folder, engine, how_it_computes, role, sort_order, semantic_type_iri)
VALUES ('effortless-owl', 'OWL / SHACL', 'rulebook-to-owl', '/effortless-owl', 'SPARQL 1.1 (pyoxigraph) executing SHACL-AF rules', 'rulebook-to-owl emits an ontology, an ABox of individuals carrying raw fields only, and one SHACL-AF SPARQL rule per derived field. The harness executes the rules in dependency order and reads the inferred triples back.', 'graded', 7, 'urn:effortless:pko-extension#ConformanceSubstrate') ON CONFLICT (conformance_substrate_id) DO UPDATE SET label = EXCLUDED.label, transpiler = EXCLUDED.transpiler, output_folder = EXCLUDED.output_folder, engine = EXCLUDED.engine, how_it_computes = EXCLUDED.how_it_computes, role = EXCLUDED.role, sort_order = EXCLUDED.sort_order, semantic_type_iri = EXCLUDED.semantic_type_iri;

-- ----------------------------------------------------------------------------
-- ConformanceRuns: One execution of the conformance harness over every graded substrate. Kept as history; exactly one run is marked IsLatest, and the per-table, per-field and per-cell detail tables describe that run.
-- ----------------------------------------------------------------------------
INSERT INTO conformance_runs (conformance_run_id, ran_on, rulebook_commit, answer_key_author, is_latest, notes, semantic_type_iri)
VALUES ('run-20260913-165336', '2026-09-13T16:53:36-05:00', '4960f638', 'compile-rulebook', FALSE, 'First recorded run: all a1 tools installed; EF runner rebuilt for EF Core output; OWL rules dependency-ordered.', 'urn:effortless:pko-extension#ConformanceRun') ON CONFLICT (conformance_run_id) DO UPDATE SET ran_on = EXCLUDED.ran_on, rulebook_commit = EXCLUDED.rulebook_commit, answer_key_author = EXCLUDED.answer_key_author, is_latest = EXCLUDED.is_latest, notes = EXCLUDED.notes, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_runs (conformance_run_id, ran_on, rulebook_commit, answer_key_author, is_latest, notes, semantic_type_iri)
VALUES ('run-20260913-203118', '2026-09-13T20:31:18-05:00', '4717a575', 'compile-rulebook', FALSE, 'Loop 4: closure over StepTransitions (cyclic step graph); rulebook-to-postgres closure view now emits (x, x) for steps on a cycle; rulebook-to-owl accepts the self-reach COUNTIFS pair. Postgres/Python/Go/TypeScript/OWL agree on all new cells; EF and xlsx have no closure engine.', 'urn:effortless:pko-extension#ConformanceRun') ON CONFLICT (conformance_run_id) DO UPDATE SET ran_on = EXCLUDED.ran_on, rulebook_commit = EXCLUDED.rulebook_commit, answer_key_author = EXCLUDED.answer_key_author, is_latest = EXCLUDED.is_latest, notes = EXCLUDED.notes, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_runs (conformance_run_id, ran_on, rulebook_commit, answer_key_author, is_latest, notes, semantic_type_iri)
VALUES ('run-20260914-083430', '2026-09-14T08:34:30-05:00', '6b0287f8', 'compile-rulebook', FALSE, 'ERB build parameters: every substrate built under erbDateDiff=calendar, erbTimezone=UTC, erbDateTimeText=iso8601, erbBlankLogic=coerce, erbWholeNumber=by-field-type; Postgres/Python/Go/TypeScript at 100%, EF 99.93 (closure views), xlsx 99.82, OWL 97.15', 'urn:effortless:pko-extension#ConformanceRun') ON CONFLICT (conformance_run_id) DO UPDATE SET ran_on = EXCLUDED.ran_on, rulebook_commit = EXCLUDED.rulebook_commit, answer_key_author = EXCLUDED.answer_key_author, is_latest = EXCLUDED.is_latest, notes = EXCLUDED.notes, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_runs (conformance_run_id, ran_on, rulebook_commit, answer_key_author, is_latest, notes, semantic_type_iri)
VALUES ('run-20260914-223223', '2026-09-14T22:32:23-05:00', 'c377d831', 'compile-rulebook', FALSE, 'Plain build against the published tools (all eight at v2026.09.14.*), no local overrides; first run after the ERB build parameters and the EdgeFilterColumn closure shipped', 'urn:effortless:pko-extension#ConformanceRun') ON CONFLICT (conformance_run_id) DO UPDATE SET ran_on = EXCLUDED.ran_on, rulebook_commit = EXCLUDED.rulebook_commit, answer_key_author = EXCLUDED.answer_key_author, is_latest = EXCLUDED.is_latest, notes = EXCLUDED.notes, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO conformance_runs (conformance_run_id, ran_on, rulebook_commit, answer_key_author, is_latest, notes, semantic_type_iri)
VALUES ('run-20260914-231633', '2026-09-14T23:16:33-05:00', '37d660d4', 'compile-rulebook', TRUE, 'rulebook-to-owl v2026.09.14.2309: COUNTIFS keyed on a non-PK field of the row, verbatim __key on every individual (keys containing ''|''), blank-safe concatenation under erbBlankLogic=coerce, ''#'' inside a string literal compared whole, a scalar wrapped around an aggregation, and a refusal when two tables share a PK value (RulebookReleases key renamed pko-release-1.0.0). OWL 100%; every substrate with a closure engine agrees on all 67,616 cells; only xlsx (no closure engine) is short.', 'urn:effortless:pko-extension#ConformanceRun') ON CONFLICT (conformance_run_id) DO UPDATE SET ran_on = EXCLUDED.ran_on, rulebook_commit = EXCLUDED.rulebook_commit, answer_key_author = EXCLUDED.answer_key_author, is_latest = EXCLUDED.is_latest, notes = EXCLUDED.notes, semantic_type_iri = EXCLUDED.semantic_type_iri;

