-- ----------------------------------------------------------------------------
-- KnowledgeMethods: Named methods, techniques and methodologies for eliciting, analysing, modeling and governing process knowledge. A method is only evidence that the model uses it when a seeded row applies it.
-- ----------------------------------------------------------------------------
INSERT INTO knowledge_methods (knowledge_method_id, label, method_family, summary, origin_reference, elicitation_tradeoff, semantic_type_iri)
VALUES ('Shadowing', 'Shadowing and observation', 'Elicitation', 'A knowledge engineer observes a practitioner doing the real work and asks about choices in the moment.', 'Ethnographic observation; legitimate peripheral participation', 'Gives up reach for depth and accuracy: one practitioner per shift, seen doing the real work.', 'urn:effortless:pko-extension#KnowledgeMethod') ON CONFLICT (knowledge_method_id) DO UPDATE SET label = EXCLUDED.label, method_family = EXCLUDED.method_family, summary = EXCLUDED.summary, origin_reference = EXCLUDED.origin_reference, elicitation_tradeoff = EXCLUDED.elicitation_tradeoff, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO knowledge_methods (knowledge_method_id, label, method_family, summary, origin_reference, elicitation_tradeoff, semantic_type_iri)
VALUES ('PractitionerInterview', 'Structured practitioner interview', 'Elicitation', 'A structured interview that asks why choices are made and what happens when the procedure is not enough.', 'Knowledge elicitation practice', 'Gives up accuracy for practicality: an hour of talk, but practitioners describe what they believe they do.', 'urn:effortless:pko-extension#KnowledgeMethod') ON CONFLICT (knowledge_method_id) DO UPDATE SET label = EXCLUDED.label, method_family = EXCLUDED.method_family, summary = EXCLUDED.summary, origin_reference = EXCLUDED.origin_reference, elicitation_tradeoff = EXCLUDED.elicitation_tradeoff, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO knowledge_methods (knowledge_method_id, label, method_family, summary, origin_reference, elicitation_tradeoff, semantic_type_iri)
VALUES ('FacilitatedWorkshop', 'Facilitated workshop', 'Elicitation', 'A session bringing together people who initiate, execute and receive a process to map it together.', 'Collaborative process mapping', 'Gives up depth for reach: many roles at once, each heard briefly.', 'urn:effortless:pko-extension#KnowledgeMethod') ON CONFLICT (knowledge_method_id) DO UPDATE SET label = EXCLUDED.label, method_family = EXCLUDED.method_family, summary = EXCLUDED.summary, origin_reference = EXCLUDED.origin_reference, elicitation_tradeoff = EXCLUDED.elicitation_tradeoff, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO knowledge_methods (knowledge_method_id, label, method_family, summary, origin_reference, elicitation_tradeoff, semantic_type_iri)
VALUES ('CriticalIncidentTechnique', 'Critical incident technique', 'Elicitation', 'Collects specific occasions when a process succeeded, failed or needed improvisation to surface judgment calls.', 'Flanagan, 1954', 'Gives up accuracy for practicality: rare events are recalled and reconstructed rather than witnessed.', 'urn:effortless:pko-extension#KnowledgeMethod') ON CONFLICT (knowledge_method_id) DO UPDATE SET label = EXCLUDED.label, method_family = EXCLUDED.method_family, summary = EXCLUDED.summary, origin_reference = EXCLUDED.origin_reference, elicitation_tradeoff = EXCLUDED.elicitation_tradeoff, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO knowledge_methods (knowledge_method_id, label, method_family, summary, origin_reference, elicitation_tradeoff, semantic_type_iri)
VALUES ('ThinkAloudProtocol', 'Think-aloud protocol', 'Elicitation', 'The practitioner verbalizes reasoning while performing the task.', 'Cognitive psychology', 'Gives up practicality and some accuracy for depth: speaking while working slows and alters the work.', 'urn:effortless:pko-extension#KnowledgeMethod') ON CONFLICT (knowledge_method_id) DO UPDATE SET label = EXCLUDED.label, method_family = EXCLUDED.method_family, summary = EXCLUDED.summary, origin_reference = EXCLUDED.origin_reference, elicitation_tradeoff = EXCLUDED.elicitation_tradeoff, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO knowledge_methods (knowledge_method_id, label, method_family, summary, origin_reference, elicitation_tradeoff, semantic_type_iri)
VALUES ('RetrospectiveProtocol', 'Retrospective protocol', 'Elicitation', 'The practitioner explains reasoning after the task, avoiding interference with the work.', 'Cognitive psychology', 'Gives up some accuracy for undisturbed practice: reasons are reconstructed after the fact.', 'urn:effortless:pko-extension#KnowledgeMethod') ON CONFLICT (knowledge_method_id) DO UPDATE SET label = EXCLUDED.label, method_family = EXCLUDED.method_family, summary = EXCLUDED.summary, origin_reference = EXCLUDED.origin_reference, elicitation_tradeoff = EXCLUDED.elicitation_tradeoff, semantic_type_iri = EXCLUDED.semantic_type_iri;

