INSERT INTO source_articles (source_article_id, title, author, series, published_on, local_file_name, thesis, semantic_type_iri)
VALUES ('pkm-1', 'Process Knowledge Management, Part I: Accounting for How We Work', 'Jessica Talisman', 'Intentional Arrangement', '2025-12-03', 'Intentional Arrangement - Process Knowledge Management, Part I.pdf', 'Process knowledge, much of it tacit, is a distinct kind of organizational knowledge and now decides whether AI succeeds; representing it explicitly in ontologies with provenance makes AI more capable, interpretable and auditable.', 'urn:effortless:pko-extension#SourceArticle') ON CONFLICT (source_article_id) DO UPDATE SET title = EXCLUDED.title, author = EXCLUDED.author, series = EXCLUDED.series, published_on = EXCLUDED.published_on, local_file_name = EXCLUDED.local_file_name, thesis = EXCLUDED.thesis, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO source_articles (source_article_id, title, author, series, published_on, local_file_name, thesis, semantic_type_iri)
VALUES ('pkm-2', 'Process Knowledge Management, Part II: Collection Development and Organizing Principles', 'Jessica Talisman', 'Intentional Arrangement', '2025-12-08', 'Intentional Arrangement - Process Knowledge Management, Part II.pdf', 'Managing process knowledge is three continuous activities: collecting it from practitioners and systems, organizing it under explicit principles and vocabularies, and encoding it for people, search and AI agents, sustained by curation, governance and feedback loops until the knowledge is adequate.', 'urn:effortless:pko-extension#SourceArticle') ON CONFLICT (source_article_id) DO UPDATE SET title = EXCLUDED.title, author = EXCLUDED.author, series = EXCLUDED.series, published_on = EXCLUDED.published_on, local_file_name = EXCLUDED.local_file_name, thesis = EXCLUDED.thesis, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO source_articles (source_article_id, title, author, series, published_on, local_file_name, thesis, semantic_type_iri)
VALUES ('pkm-3', 'Process Knowledge Management, Part III: How We Lost Our Way', 'Jessica Talisman', 'Intentional Arrangement', '2025-12-13', 'Intentional Arrangement - Process Knowledge Management, Part III.pdf', 'Outsourcing shipped away the feedback loops, communities of practice and apprenticeship that generate process knowledge; organizations must audit what they hold, rebuild capture and transfer, and design new systems so knowledge capture is a primary goal.', 'urn:effortless:pko-extension#SourceArticle') ON CONFLICT (source_article_id) DO UPDATE SET title = EXCLUDED.title, author = EXCLUDED.author, series = EXCLUDED.series, published_on = EXCLUDED.published_on, local_file_name = EXCLUDED.local_file_name, thesis = EXCLUDED.thesis, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO source_articles (source_article_id, title, author, series, published_on, local_file_name, thesis, semantic_type_iri)
VALUES ('pkm-4', 'Process Knowledge Management, Part IV: From Theory to Practice, The Procedural Knowledge Ontology', 'Jessica Talisman', 'Intentional Arrangement', '2025-12-18', 'Intentional Arrangement - Process Knowledge Management, Part IV.pdf', 'The Procedural Knowledge Ontology separates procedures from their executions, reuses established vocabularies, is built by a lightweight methodology from expert workshops, and grounds elicitation tools and AI assistants in governed procedural knowledge.', 'urn:effortless:pko-extension#SourceArticle') ON CONFLICT (source_article_id) DO UPDATE SET title = EXCLUDED.title, author = EXCLUDED.author, series = EXCLUDED.series, published_on = EXCLUDED.published_on, local_file_name = EXCLUDED.local_file_name, thesis = EXCLUDED.thesis, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO source_articles (source_article_id, title, author, series, published_on, local_file_name, thesis, semantic_type_iri)
VALUES ('ont-4', 'Ontology Series, Part IV: Governance, Maintenance, and AI', 'Jessica Talisman', 'Ontology Series', '2026-03-17', 'Ontology Series, Part IV - Governance, Maintenance, and AI (mislabeled as PKM Part V).htm', 'Deployed models drift away from the organizations they describe; named stewardship and authority, semantic versioning, change requests tied to competency questions and regular review keep a model coherent, while AI proposes and people decide.', 'urn:effortless:pko-extension#SourceArticle') ON CONFLICT (source_article_id) DO UPDATE SET title = EXCLUDED.title, author = EXCLUDED.author, series = EXCLUDED.series, published_on = EXCLUDED.published_on, local_file_name = EXCLUDED.local_file_name, thesis = EXCLUDED.thesis, semantic_type_iri = EXCLUDED.semantic_type_iri;

