-- ----------------------------------------------------------------------------
-- ClaimEvidence: A proposed piece of evidence that the model covers a claim, with the justification a skeptic can audit. Whether it counts is computed in IsValid from measured facts, never asserted.
-- ----------------------------------------------------------------------------
INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c04-e1', 'pkm1-c04', 'Field', 'KnowledgeFragments.CognitiveBasis', NULL, NULL, NULL, NULL, NULL, 'Each fragment records whether it rests on intuition, pattern recognition or judgment (tacit) or was articulated outright (explicit): the bleed cue is PatternRecognition, the retrofit zero-reading distrust is Intuition, the retyped manual note is Articulated.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c05-e1', 'pkm1-c05', 'Field', 'ProcedureVersions.JudgmentHeldOutsideSopCount', NULL, NULL, NULL, NULL, NULL, 'Counts the version''s unformalized knowledge that its written SOP says nothing about; the four-step loto-v1.0.0 SOP left four pieces of expert handling outside it, and even loto-v2.0.0 still leaves one.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c06-e1', 'pkm1-c06', 'Field', 'KnowledgeHoldings.IsVeteranDiscretion', NULL, NULL, NULL, NULL, NULL, 'TRUE where a veteran resolves an exception or discretionary decision that nothing written encodes: Tomas''s bleed cue and Victor''s twin-drive isolation before v2, and Tomas''s distrust of zero readings on retrofits still today.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c15-e1', 'pkm1-c15', 'Field', 'KnowledgeConversions.ConversionMode', NULL, NULL, NULL, NULL, NULL, 'Records each shift of the lockout bleed knowledge by mode: socialization (Ken learning beside Tomas), externalization (the cue stated in an interview), combination (merged into the v2 rulebook) and internalization (Aisha rehearsing it).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c28-e1', 'pkm1-c28', 'Field', 'KnowledgeFragments.TacitnessDegree', NULL, NULL, NULL, NULL, NULL, 'Places each fragment on a 1-5 spectrum from fully articulated to not articulable instead of a binary: the manual note is 1, the shift hand-off 2, the twin-drive rule 3, the bleed cue 4, the retrofit zero-reading distrust 5.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p01-e1', 'pkm1-p01', 'Field', 'KnowledgeFragments.IsFlattenedToBrittleRule', NULL, NULL, NULL, NULL, NULL, 'Fires when tacit or situated knowledge was encoded as a hard rule with no conditions saying when it holds. It fires on ''Always isolate both drives of mixer 2'', which reduced Victor''s judgment about retrofits to one machine''s name; it does not fire on the bleed cue, encoded as guidance with its conditions, nor on the explicit manual note.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p04-e1', 'pkm1-p04', 'Field', 'ElicitationSessions.IsGenericOrUnskilledCapture', NULL, NULL, NULL, NULL, NULL, 'Fires when a session captured knowledge with a method outside the elicitation family or without the organization''s knowledge engineer running it. It fires on the three earlier sessions a finance analyst, a communications manager and a policy owner ran, and on none of the lockout sessions Sam Adeyemi ran with elicitation methods.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p05-e1', 'pkm1-p05', 'Field', 'KnowledgeFragments.RestsOnSingleDataPoint', NULL, NULL, NULL, NULL, NULL, 'Fires on approved knowledge that no second session or practitioner supports. It fires on the mixer 2 twin-drive rule, whose only other data point (Ken in think-aloud) disagrees, and on the retyped manual note; it does not fire on the bleed cue, corroborated by shadowing and by an incident, nor on the shift hand-off corroborated in the workshop.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

