VALUES ('pkm1-s08-e1', 'pkm1-s08', 'KnowledgeMethod', NULL, NULL, NULL, NULL, 'PolanyiTacitExplicitDistinction', NULL, 'Applied by method application ma7-loto-polanyi, which classified the lockout fragments and knowledge holdings as tacit or explicit before loto-v2.0.0 was encoded.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

