VALUES ('pkm2-c10-e1', 'pkm2-c10', 'Field', 'InterviewProbes.ShortfallAnswer', NULL, NULL, NULL, NULL, NULL, 'Holds what the practitioner does when the standard procedure proves insufficient: on a capacitor-bank retrofit Tomas waits five minutes and re-tests before anyone reaches in.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c11-e1', 'pkm2-c11', 'Field', 'CriticalIncidents.Outcome', NULL, NULL, NULL, NULL, NULL, 'Each collected episode is typed WentWell, WentBadly or Improvised: the mixer 2 second-drive restart went badly, the press 3 gauge episode was improvised, the conveyor 5 hand-off went well.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c12-e1', 'pkm2-c12', 'Field', 'CriticalIncidents.JudgmentFragment', NULL, NULL, NULL, NULL, NULL, 'Links each episode to the knowledge fragment recording the judgment call it brought out: the mixer 2 restart to the twin-drive isolation fragment, the press 3 gauge episode to the bleed cue.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c13-e1', 'pkm2-c13', 'Field', 'KnowledgeGaps.IsGatekeepingOrSabotage', NULL, NULL, NULL, NULL, NULL, 'TRUE for gaps caused by gatekeeping or knowledge sabotage, each recording the silo it created (SiloedWithin): the press 3 day crew withholding its bleed check, and the override card removed from the retrofit binder.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

