VALUES ('pkm2-p12-e1', 'pkm2-p12', 'Field', 'WorkflowViewDivergences.IsSurfacedButUnreconciled', NULL, NULL, NULL, NULL, NULL, 'Fires when a workshop brought two differing views of how work flows into the open but never reconciled them: when operators are notified of a shutdown. It does not fire on the last-tag disagreement, settled and recorded as a fragment.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

