INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-i01-e1', 'pkm2-i01', 'Field', 'PractitionerExpertise.KnowsMoreThanCanSay', NULL, NULL, NULL, NULL, NULL, 'The plant''s counterpart of the adjuster sensing fraud: fires when a practitioner reliably detects a condition whose basis they cannot state. It fires on Tomas, right fourteen times about a bleed that did not take; it does not fire on Aisha, who cannot say why either but has one reliable call, nor on Ken, who states his basis.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-i02-e1', 'pkm2-i02', 'Field', 'PractitionerExpertise.IsUnexplainedForesight', NULL, NULL, NULL, NULL, NULL, 'The software architect case: fires when a design judgment later proved right although its holder could not say why. It fires on Ravi''s sense that the shared build cache would be costly to maintain; it does not fire on Omar''s confirmed canary judgment, whose basis he stated, nor on detection expertise.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-i07-e1', 'pkm2-i07', 'Field', 'ProcedureVersions.TacitShareExceedsExplicit', NULL, NULL, NULL, NULL, NULL, 'Compares tacit holdings (operator memory, departing staff, crew agreements) with explicit carriers (SOP, manual notes). It fires on loto-v1.0.0, where three of five holdings were tacit; it does not fire on loto-v2.0.0 after encoding.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-i08-e1', 'pkm2-i08', 'Field', 'ProcedureVersions.IsStudiedOnlyFromTheDesk', NULL, NULL, NULL, NULL, NULL, 'The field-researcher comparison as a check: fires when the knowledge engineer elicited a version but never went where the work happens. It fires on deploy-v3.2.0, elicited by one remote interview; it does not fire on loto-v2.0.0, elicited on the plant floor.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-i09-e1', 'pkm2-i09', 'Field', 'ProcedureVersions.ExpertsEvaluateAiNotRepresentation', NULL, NULL, NULL, NULL, NULL, 'Fires when experts were recruited to evaluate AI output on a version but none to approve the representation it rests on: Ravi Menon, an affected platform engineer, rated the deployment AI''s output while no affected expert approved deploy-v3.2.0. It does not fire on loto-v2.0.0, approved by its experts.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-i12-e1', 'pkm2-i12', 'Field', 'ProcedureVersions.LivesInHandsSilenceAndNegotiation', NULL, NULL, NULL, NULL, NULL, 'Fires when a version''s knowledge lives at once in operators'' memory, in what its SOP leaves unsaid, and in unspoken crew agreements. It fires on loto-v1.0.0 (Tomas''s bleed cue, the manual margin note, the night crew''s tag habit); it does not fire on loto-v2.0.0, where the crew agreement was settled and encoded.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

