VALUES ('pkm2-i15-e1', 'pkm2-i15', 'Field', 'KnowledgeTestOutcomes.IsImproved', NULL, NULL, NULL, NULL, NULL, 'Measures each outcome the lockout knowledge tests were meant to improve, before and after: competency gaps, audit quality, minutes per lockout and consistency improved; job satisfaction did not move, and the field reads FALSE there.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

