VALUES ('pkm4-c17-e1', 'pkm4-c17', 'Table', NULL, 'KnowledgeFragments', NULL, NULL, NULL, NULL, 'Records situated, tacit and implicit knowledge -- the judgment and operating constraints practitioners bring -- as its own rows attached to steps, separate from the Steps list itself.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

