VALUES ('pkm1-p24-e1', 'pkm1-p24', 'Field', 'AssistantAnswers.IsUncheckedRegulatedRecommendation', NULL, NULL, NULL, NULL, NULL, 'Fires on a recommendation acting on a step that carries a regulatory requirement which was never checked against it: the copilot''s advice to skip the second zero-energy verification (hazardous energy standard). The two recommendations checked against the change-control requirement do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

