VALUES ('pkm1-p31-e1', 'pkm1-p31', 'Field', 'KnowledgeConsumerSystems.IsUnlinkedToolchainComponent', NULL, NULL, NULL, NULL, NULL, 'Fires on a process modeling tool, semantic repository or AI platform linked to neither the shared model nor any AI integration: the process modeling workbench. The procedure register and both AI platforms are linked and do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

