VALUES ('pkm1-p41-e1', 'pkm1-p41', 'Field', 'ProcedureVersions.ServesOnlyHumansOrOnlyMachines', NULL, NULL, NULL, NULL, NULL, 'Fires on a current version that is conveyed to people or to machines but not both: press changeover reaches only the copilot''s AI platform. Lockout 2.0.0 and deployment 3.2.0 reach technicians through published projections and AI through syncs and served assertions, and do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

