VALUES ('pkm1-i03-e1', 'pkm1-i03', 'Field', 'AssistantAnswers.DeliveredDespiteConflict', NULL, NULL, NULL, NULL, NULL, 'Witnesses the illustrated check of a proposed action against regulation doing its job: it fires when the check found the release assistant''s hotfix recommendation in conflict with the change-control requirement and it was delivered anyway. The recommendation that complied does not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

