VALUES ('pkm1-i07-e1', 'pkm1-i07', 'Field', 'KnowledgeConsumerSystems.IsImmatureGraphPlatform', NULL, NULL, NULL, NULL, NULL, 'Fires on a knowledge graph platform missing one of reasoner, semantic storage, graph algorithms or machine learning: the procedural knowledge graph has no machine learning. The defect analysis graph combines all four and does not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

