VALUES ('pkm2-p42-e1', 'pkm2-p42', 'Field', 'EmbeddingProbes.SynonymsNotSimilar', NULL, NULL, NULL, NULL, NULL, 'Fires when an embedding model scores process near-synonyms below 0.7: the general model puts ''lock out'' and ''isolate'' at 0.52. The tuned model (0.88) and approve/authorize (0.91) do not fire. The similarities are recorded probe results; the model does not compute embeddings.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

