VALUES ('pkm2-p51-e1', 'pkm2-p51', 'Field', 'KnowledgeProjections.NarrativeNotGeneratedFromModel', NULL, NULL, NULL, NULL, NULL, 'Fires on narrative documentation not generated from the model since its last change: the hand-maintained deployment runbook. The generated RuleSpeak and natural-language lockout documents do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

