VALUES ('pkm2-p58-e1', 'pkm2-p58', 'Field', 'ModelAnnotations.FlagBypassedAnnotationInterface', NULL, NULL, NULL, NULL, NULL, 'Fires when a practitioner had to flag outdated guidance outside the annotation interface: Ken emailed the steward about the retrofit bleed valve. His press-7 map flag entered through the panel does not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

