INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-i03-e1', 'pkm2-i03', 'Field', 'AiToolInvocations.ActedWithoutDeclaredContext', NULL, NULL, NULL, NULL, NULL, 'The meeting-booking point in this domain: an AI must know the context a step declares before acting. Fires when the copilot reserved padlocks for loto-05 with one of the two declared inputs (the isolation list, not the lock inventory), and the crew was two locks short. Invocations supplied with every declared input do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-i06-e1', 'pkm2-i06', 'Field', 'AssistantBenchmarks.ShowsSpatialLiftFromGraphQueries', NULL, NULL, NULL, NULL, NULL, 'Witnesses the illustrated effect on the organization''s own recorded benchmarks: TRUE for the spatial press-7 reach benchmark whose graph-querying arm gained 47 points; FALSE for the same spatial task answered over document chunks (no queries, 7 points) and for other task families. It is a recorded result, not an AI run.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

