VALUES ('pkm2-i13-e1', 'pkm2-i13', 'Field', 'Organizations.AiFailsForLackOfCapturedKnowledge', NULL, NULL, NULL, NULL, NULL, 'Fires on an organization with a failed AI initiative that has captured no procedures: ACME Logistics'' routing AI. The plant and engineering divisions also had failures but have captured procedures, and do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

