VALUES ('pkm3-p08-e1', 'pkm3-p08', 'Field', 'AiAdoptionInitiatives.AgentOnUnderSpecifiedProcedure', NULL, NULL, NULL, NULL, NULL, 'Fires when an agent is set to run a version that does not specify preconditions or exception handling: the conveyor maintenance agent, the checklist bot on the 2019 transcription, and the press-7 agent. The release and risk agents run deployment 3.2.0, which specifies both, and do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

