VALUES ('pkm3-p09-e1', 'pkm3-p09', 'Field', 'AiAdoptionInitiatives.HandsTacitProcedureToAgent', NULL, NULL, NULL, NULL, NULL, 'Fires when an agent is assigned a procedure that exists only as tacit knowledge and documents: the proposed press-7 changeover agent. Agents on procedures with specified steps do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

