VALUES ('pkm3-p10-e1', 'pkm3-p10', 'Field', 'AiAdoptionInitiatives.RedesignedBeforeDocumented', NULL, NULL, NULL, NULL, NULL, 'Fires when the workflow redesign for AI started before the workflow was documented as a version: the conveyor agent''s redesign began 10 January, conveyor maintenance 1.0.0 was issued 1 February. Redesigns that started after the target version was issued do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

