VALUES ('pkm3-p23-e1', 'pkm3-p23', 'Field', 'AiAdoptionInitiatives.AgenticWithoutKnowledgeCapture', NULL, NULL, NULL, NULL, NULL, 'Fires on an agentic system past proposal that has produced no procedural knowledge back into the model: the release assistant and the checklist bot. The risk classifier and conveyor agent each proposed insights and do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

