VALUES ('pkm3-p29-e1', 'pkm3-p29', 'Field', 'AgentIntegrations.IsShadowIntegration', NULL, NULL, NULL, NULL, NULL, 'Fires on an integration in live use with no entry in the central registry: the release assistant''s agent-to-agent connection that delivered the hotfix recommendation. Registered integrations do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

