VALUES ('pkm3-p30-e1', 'pkm3-p30', 'Field', 'AgentIntegrations.IsOneOffConnection', NULL, NULL, NULL, NULL, NULL, 'Fires on an integration whose pathway no other integration shares: the copilot''s one-off export script and the checklist bot''s pasted prompt. Integrations on the shared MCP server and agent-to-agent gateway do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

