VALUES ('pkm3-i10-e1', 'pkm3-i10', 'Field', 'AiAdoptionInitiatives.AdoptedWithoutBottomLineResult', NULL, NULL, NULL, NULL, NULL, 'Witnesses the illustrated gap between adopting AI and seeing results: fires on AI in production with no measured bottom-line result (checklist bot, routing AI). The copilot and risk classifier in production with measured results do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

