VALUES ('pkm3-i11-e1', 'pkm3-i11', 'Field', 'AiAdoptionInitiatives.FailedWithoutFormalizedKnowledge', NULL, NULL, NULL, NULL, NULL, 'Fires where prompting a model about work with no formalized steps failed: the press-7 changeover optimizer and the routing AI. The knowledge-rich lockout copilot and risk classifier, grounded in specified procedures, succeeded and do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

