VALUES ('pkm4-p06-e1', 'pkm4-p06', 'Field', 'Procedures.IsRegulatedButUnformalized', NULL, NULL, NULL, NULL, NULL, 'Makes compliance exposure visible: fires on a procedure a regulation requires that exists only as a title and documents, the press-7 accumulator bleed-down under the hazardous energy standard. Regulated procedures with specified steps do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

