INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-p34-e1', 'pkm4-p34', 'Field', 'AssistantAnswers.StayedSilentOnSafetyProblem', NULL, NULL, NULL, NULL, NULL, 'Fires when a danger cue was on record, unescalated, for the step under way and the AI answer raised no safety concern: the copilot told Ken to carry on after the hiss at loto-04b. Answers on steps with no unescalated cue, or that raised the concern, do not fire. The answer is recorded data, not a live AI.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-p35-e1', 'pkm4-p35', 'Field', 'AssistantAnswers.ArrivedAfterStepEnded', NULL, NULL, NULL, NULL, NULL, 'Fires when step guidance arrived after the step had already ended, so it could not guide the worker in real time: the copilot''s gauge guidance on 8 July. Guidance delivered while its step was under way does not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-p36-e1', 'pkm4-p36', 'Field', 'ConsumerSystemSyncs.PredatesVersionChange', NULL, NULL, NULL, NULL, NULL, 'Fires when a machine holds the current version but took it before that version last changed, so its picture predates the workflow: the copilot platform''s copy of press changeover (synced 1 June, changed 15 June). Syncs taken after the last change do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-p37-e1', 'pkm4-p37', 'Field', 'ProcedureVersions.IsNotQueryValidateReasonReady', NULL, NULL, NULL, NULL, NULL, 'The same prescription as pkm1-p11 in Part IV''s words: fires on a current version not read by any structured query, never validated against the profile, or never checked by a reasoner (conveyor maintenance, press changeover); lockout 2.0.0 and deployment 3.2.0 do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-p38-e1', 'pkm4-p38', 'Field', 'ConsumerSystemSyncs.IsAiFedFromForkedCopy', NULL, NULL, NULL, NULL, NULL, 'Fires when a system read by AI is fed from a separate document instead of the shared model people use: the release bot platform reads the runbook. The copilot and graph syncs from the model do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-p39-e1', 'pkm4-p39', 'Field', 'Agents.LacksRuntimeKnowledgeIntegration', NULL, NULL, NULL, NULL, NULL, 'Fires on an AI agent that answers people but receives no knowledge at run time through any integration: the checklist bot, whose SOP was pasted into its prompt once. The copilot and release assistant retrieve at run time and do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-p40-e1', 'pkm4-p40', 'Field', 'AiAdoptionInitiatives.BreaksElicitEncodeConnectOrder', NULL, NULL, NULL, NULL, NULL, 'Fires when knowledge was connected to AI with no elicitation behind the target version, or before the version was encoded: the release assistant and risk classifier (deployment 3.2.0 was authored without expert elicitation), the checklist bot, press optimizer and routing AI. The copilot, connected after lockout 2.0.0 was elicited from Tomas and issued, does not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

