VALUES ('pkm4-s12-e1', 'pkm4-s12', 'OntologyProfile', NULL, NULL, NULL, 'owl-2', NULL, NULL, 'The OWL 2 profile; its mappings record the procedural knowledge graph''s classes and properties as OWL declarations serialized in RDF.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

