VALUES ('pkm4-s14-e1', 'pkm4-s14', 'KnowledgeMethod', NULL, NULL, NULL, NULL, 'GraphRetrieval', NULL, 'Applied by ma-graph-retrieval-copilot: the copilot''s answers are retrieved from the knowledge graph snapshot, which AnswerGroundings ties to each answer.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-i02-e1', 'pkm4-i02', 'Field', 'KnowledgeOutcomeMeasurements.IsGainOutsideProceduralScope', NULL, NULL, NULL, NULL, NULL, 'Separates efficiency gains measured on non-procedural knowledge from procedural ones: TRUE for the defect analysis graph''s 38% gain (product quality), FALSE for the lockout crews and copilot, so the illustrated gain is not counted as evidence about procedures.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

