VALUES ('pkm4-i05-e1', 'pkm4-i05', 'Field', 'AssistantBenchmarks.ShowsGeospatialRetrievalLift', NULL, NULL, NULL, NULL, NULL, 'Witnesses the illustrated effect on the organization''s recorded benchmark: TRUE for plant-site station and muster-point retrieval, which gained 43 points once linked to the graph; FALSE for the other benchmarks. A recorded result, not an AI run.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

