VALUES ('ont4-p57-e1', 'ont4-p57', 'Field', 'AiInsightProposals.GrewModelWithoutHumanSeed', NULL, NULL, NULL, NULL, NULL, 'Fires when an AI proposed extending the model where no human-authored seed exists: the summarizer''s proposed forklift battery procedure, mined from logs with no seed version. Its proposal against the human-authored lockout 2.0.0 does not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

