VALUES ('ont4-p58-e1', 'ont4-p58', 'Field', 'AssistantAnswers.AnsweredComplianceQuestionFromDocuments', NULL, NULL, NULL, NULL, NULL, 'Fires when an authority or safety question was answered from document passages rather than a structured query over the graph: ''who approves production releases?'' from the runbook, and the checklist bot''s mixer-2 isolation answer. Structured-query answers do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

