VALUES ('ont4-p60-e1', 'ont4-p60', 'Field', 'GroundingSnapshots.ServedWithoutConsistencyCheck', NULL, NULL, NULL, NULL, NULL, 'Fires when a graph snapshot was served to AI with no reasoner run finding it consistent: the 2026-06-01 tabular export, whose only run found it inconsistent. The July snapshots were found consistent by the OWL 2 RL reasoner and do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

