VALUES ('ont4-p61-e1', 'ont4-p61', 'Field', 'GroundingSnapshots.ServedBeforeMaterialization', NULL, NULL, NULL, NULL, NULL, 'Fires when a snapshot was served before a reasoner materialized its entailments: the June export (never materialized) and the 18 July hotfix rebuild (served 08:00, materialized 09:00). The 15 July snapshot, materialized at 05:00 and served at 06:00, does not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

