VALUES ('ont4-i04-e1', 'ont4-i04', 'Field', 'ProcedureVersions.UsesAiInOneDirectionOnly', NULL, NULL, NULL, NULL, NULL, 'Fires on a version where AI only consumes the knowledge (lockout 1.0.0 served, never improved) or only contributes to it (conveyor maintenance and close receive AI insights but serve nothing to AI). Lockout 2.0.0 and deployment 3.2.0 are both served to AI and improved by AI insights, and do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

