VALUES ('ont4-i06-e1', 'ont4-i06', 'Field', 'AssistantAnswers.WrongBecauseGraphWasStale', NULL, NULL, NULL, NULL, NULL, 'Fires when a graph-grounded answer was wrong because the grounding assertion was stale or deprecated: ''classifier 2.4.0'' from a superseded assignment and ''lockout 1.0.0 is current'' from a deprecated version. Graph answers grounded on current assertions were correct and do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

