VALUES ('ont4-i07-e1', 'ont4-i07', 'Field', 'RetrievalSegments.IsMachineHeldKnowledge', NULL, NULL, NULL, NULL, NULL, 'Fires on knowledge written by software with no human role accountable for it: the summarizer''s loto-04b bleed segment. Segments with an accountable human role do not fire. Knowledge nobody is responsible for is what a machine cannot hold.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

