VALUES ('pkm1-p33-e1', 'pkm1-p33', 'Field', 'RulebookTables.LacksSemanticTypeConvention', NULL, NULL, NULL, NULL, NULL, 'The model''s stated convention is that every table carries a SemanticTypeIri column; this counts that column in the field census and fires on tables that break the convention (for example OntologyProfiles, SemanticMappings, RulebookReleases).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

