VALUES ('pkm1-p34-e1', 'pkm1-p34', 'Field', 'RulebookReleases.ReleasedDespiteFailedValidation', NULL, NULL, NULL, NULL, NULL, 'Fires on release 0.10.0, which shipped the RoleAssignments domain narrowing although its acceptance validation run failed two tests; releases whose runs passed read false.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

