VALUES ('pkm1-p35-e1', 'pkm1-p35', 'Field', 'RulebookReleases.IsUntaggedRelease', NULL, NULL, NULL, NULL, NULL, 'Fires on release 0.8.2, which has no version-control commit or tag; every other governed release records its commit, so version control of the model is checked release by release.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

