VALUES ('pkm2-p55-e1', 'pkm2-p55', 'Field', 'GovernedModels.PipelineNotContinuous', NULL, NULL, NULL, NULL, NULL, 'Counts governance controls over collection, organization and encoding that run continuously; fires on the close family (encoding is a quarterly batch) and on deployment and press changeover, not on lockout/tagout or workforce policy where all three run continuously.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

