VALUES ('ont4-i28-e1', 'ont4-i28', 'Field', 'ModelCharters.StewardIsOutsideTooling', NULL, NULL, NULL, NULL, NULL, 'Fires on the first PKO rulebook charter, stewarded by People Operations; the model moved to the knowledge engineer, who owns the build and publication tooling.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

