VALUES ('ont4-i29-e1', 'ont4-i29', 'Field', 'CompetencyQuestionSetEntries.ServesEveryGovernanceUse', NULL, NULL, NULL, NULL, NULL, 'Fires on questions that served as scoping tool, acceptance criterion, test driver and governance instrument in turn (the multi-step question, the CFO sign-off question).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-i30-e1', 'ont4-i30', 'Field', 'DriftObservations.DriftFollowsCleanRelease', NULL, NULL, NULL, NULL, NULL, 'Fires on drift observed after releases that passed every acceptance validation (0.9.0, 0.10.1); drift after the failed 0.10.0 release and drift with no release reference read false.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c07-e1', 'pkm1-c07', 'Field', 'Steps.StatesOperationalKnowledge', NULL, NULL, NULL, NULL, NULL, 'TRUE for a step that states the three operational-level facts together: it is reached through the transition order (what comes before), it names the step it depends on, and it has a precondition that must hold before work continues. loto-03, loto-07 and deploy-04 carry all three; steps missing any of them read FALSE.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c08-e1', 'pkm1-c08', 'Table', NULL, 'TacticalResourceAllocations', NULL, NULL, NULL, NULL, 'Each row is tactical knowledge: the capacity allocated to a step''s resource, the demand on it, whether that makes a bottleneck, and the adjustment decided (order padlocks, fill the night deputy role).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c09-e1', 'pkm1-c09', 'Table', NULL, 'ProcessStrategicAlignments', NULL, NULL, NULL, NULL, 'Each row ties a procedure to the mission of the organization it serves and records its rationale, the value it creates and the trade-offs it makes, e.g. lockout''s extra hour of downtime per job.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c10-e1', 'pkm1-c10', 'Table', NULL, 'ProcessStages', NULL, NULL, NULL, NULL, 'Stages group a version''s steps (Steps.Stage), in sequence, as a product manager runs the release process: build and classify, approve, roll out and verify.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c11-e1', 'pkm1-c11', 'Field', 'ProcessStages.OwnerRole', NULL, NULL, NULL, NULL, NULL, 'The stakeholder role that owns each stage (release manager owns Approve, site reliability engineer owns Roll out and verify); Steps.AssignedRole already names the owner of each step.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c12-e1', 'pkm1-c12', 'Field', 'ProcessOutcomeMeasures.ObservedValue', NULL, NULL, NULL, NULL, NULL, 'The measured value of each outcome of a procedure over a period against its target, e.g. change failure rate 33% against 5%, zero-energy first-pass rate 60% against 95%.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c13-e1', 'pkm1-c13', 'Table', NULL, 'ProcessInterdependencies', NULL, NULL, NULL, NULL, 'Rows record how one operation requires, helps or hinders another and the mechanism, e.g. deployments during the close window restarting the ledger integration: the cross-process dependencies an infrastructure engineer needs.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c14-e1', 'pkm1-c14', 'Field', 'ProcessOutcomeMeasures.BusinessOutcome', NULL, NULL, NULL, NULL, NULL, 'Links each process measure to the business outcome it drives (change failure rate to platform availability, owned by the VP of engineering), with LinkRationale saying how.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c34-e1', 'pkm1-c34', 'Table', NULL, 'StepContextSensitivities', NULL, NULL, NULL, NULL, 'One row per way a step''s significance changes with context, typed by ContextFactor Performer, Resource or Circumstance: a deputy verifying on nights, padlocks running short, a press carrying an accumulator retrofit.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p02-e1', 'pkm1-p02', 'Field', 'ProcessKnowledgeLevels.LacksCaptureStrategyForEitherForm', NULL, NULL, NULL, NULL, NULL, 'Fires on a level that has no capture strategy for its tacit knowledge or none for its explicit knowledge. The strategic level has only strategy memos (explicit) and nothing for the executives'' tacit judgment, so it fires; operational and tactical have both and do not. That is the prescription that each level needs its own strategy for both forms broken.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p03-e1', 'pkm1-p03', 'Field', 'Procedures.PrivilegesSingleStakeholderView', NULL, NULL, NULL, NULL, NULL, 'Fires when a procedure is organized for exactly one stakeholder lens. The press-7 die changeover is organized only as the trainer''s view, so every other stakeholder (auditor, manager, executive) is unserved; lockout and deployment serve several lenses and do not fire. That is one stakeholder view privileged over the rest.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p14-e1', 'pkm1-p14', 'Field', 'TermRelations.AssertsIndirectLinkAsDirect', NULL, NULL, NULL, NULL, NULL, 'Fires when a skos:broader link, which must be direct, is asserted from a concept to its grandparent. The SOP index linked accumulator bleed-down straight to lockout/tagout although it sits under energy isolation, so it fires; the associative relations do not. The rule that a direct relation cannot stand in for an indirect one is enforced.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p15-e1', 'pkm1-p15', 'Field', 'ExecutionEntities.ViolatesDeclaredDatatypeOrFormat', NULL, NULL, NULL, NULL, NULL, 'Fires when a recorded value''s datatype or media type differs from what its step variable declares. The 2026-07-14 hotfix recorded its risk report as a text/plain chat message where deploy-02 declares a RiskReport in application/json, so it fires; the conforming PDF verification record and JSON risk report do not. Expected datatype and format are enforced.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p28-e1', 'pkm1-p28', 'Field', 'Steps.IsContextSensitiveButUnscoped', NULL, NULL, NULL, NULL, NULL, 'Fires when a step''s significance depends on context and a recorded dependency names no applicability scope. loto-03''s dependence on the press-7 retrofit has no scope, so it fires; the night-shift and EU-freeze dependencies point at one compact ApplicabilityScopes row and do not. Context is captured by explicit scoping rather than by forking the procedure.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-q05-e1', 'pkm1-q05', 'RoleQuestion', NULL, NULL, 'aq-pkm1-q05', NULL, NULL, NULL, 'The operations manager''s bottleneck question, answered by TacticalResourceAllocations.IsBottleneck and Steps.IsBottleneckStep: north-station padlocks and night verifier hours are demanded beyond capacity.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-q06-e1', 'pkm1-q06', 'RoleQuestion', NULL, NULL, 'aq-pkm1-q06', NULL, NULL, NULL, 'The VP''s question on why each procedure exists and what it trades off, answered by ProcessStrategicAlignments and Procedures.HasNoStatedReasonForExisting / ProcessStrategicAlignments.StatesNoTradeOff.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-q07-e1', 'pkm1-q07', 'RoleQuestion', NULL, NULL, 'aq-pkm1-q07', NULL, NULL, NULL, 'The VP''s question on how performance connects to business outcomes, answered by ProcessOutcomeMeasures.BusinessOutcome and Procedures.MeasuresPerformanceWithoutBusinessLink (conveyor maintenance is measured but tied to nothing).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-s06-e1', 'pkm1-s06', 'OntologyProfile', NULL, NULL, NULL, 'sparql-11-sd', NULL, NULL, 'SPARQL 1.1 Service Description''s named graphs: ApplicabilityScopes maps to sd:NamedGraph and NamedGraphIri to sd:name, so knowledge scoped to a context is kept in the named graph where it holds.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-i04-e1', 'pkm1-i04', 'Field', 'LevelCaptureStrategies.ContradictsKnowledgeForm', NULL, NULL, NULL, NULL, NULL, 'Fires when tacit knowledge is to be passed on only as a stored document, or explicit knowledge only in person. The shift planners'' tacit staffing heuristics were written up once as a wiki page, so it fires; shadowing veterans (tacit, in person) and encoding the SOP (explicit, codified) do not. It witnesses the chart''s contrast: explicit knowledge is codified and stored, tacit knowledge is passed on in person.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-i05-e1', 'pkm1-i05', 'Field', 'ProcessLevelStatements.IsFiledAtWrongLevel', NULL, NULL, NULL, NULL, NULL, 'Fires when a statement answers a question its level does not answer in the planning pyramid (LevelPyramidQuestions: strategic who and why, tactical what, operational how and where). The deployment''s reason for gating releases (a why) was filed among operational statements, so it fires; the lockout statements filed by the pyramid do not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p06-e1', 'pkm1-p06', 'Field', 'Resources.IsContentWithoutOrganization', NULL, NULL, NULL, NULL, NULL, 'Fires when a resource has content (a description) but lacks structure (no type from the artifact-type scheme), findability (no keywords) or linkage (no procedure or step references it). The press-7 changeover PDF has content but no keywords, so it fires; the typed, keyworded, referenced 2019 lockout SOP does not. Content alone does not pass.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p40-e1', 'pkm1-p40', 'Field', 'Procedures.LacksManagedControlledVocabulary', NULL, NULL, NULL, NULL, NULL, 'Fires when a procedure with specified steps has no controlled vocabulary whose metadata (governing role, establishment date) is managed. Conveyor maintenance has only an ungoverned PDF glossary, so it fires; lockout, deployment, close and policy each have a governed scheme and do not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

