VALUES ('pkm2-q28-e1', 'pkm2-q28', 'RoleQuestion', NULL, NULL, 'aq-pkm2-q28', NULL, NULL, NULL, 'The steward''s question, answered by Roles.Organization and OrganizationType, with IsNotHousedInDepartment for roles outside any department.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

