VALUES ('ont4-c10-e1', 'ont4-c10', 'Field', 'OntologyProfiles.Version', NULL, NULL, NULL, NULL, NULL, 'One record per reused external standard (SKOS, FOAF, schema.org, DCAT, PKO, ...) holding the version the model depends on, with its version IRI and namespace.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

