VALUES ('ont4-c11-e1', 'ont4-c11', 'Field', 'ExternalStandardTerms.DeprecatedBySource', NULL, NULL, NULL, NULL, NULL, 'TRUE for an adopted external term its source standard marks deprecated (foaf:givenname, schema:serviceAudience, schema:vendor), with DeprecatedAt and StillResolves.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

