VALUES ('ont4-c34-e1', 'ont4-c34', 'Field', 'Vocabularies.GovernedDimension', NULL, NULL, NULL, NULL, NULL, 'Names what each scheme controls; voc-agent-capabilities is the AgentCapability scheme (compliance review, validation, risk scoring, automated deployment).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

