VALUES ('ont4-s12-e1', 'ont4-s12', 'OntologyProfile', NULL, NULL, NULL, 'owl-2', NULL, NULL, 'OWL 2 mapping of VocabularyTerms.SameAsIri to owl:sameAs, the identity assertion between a re-homed local term and the deprecated original.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-s14-e1', 'ont4-s14', 'OntologyProfile', NULL, NULL, NULL, 'rdf-1-1', NULL, NULL, 'RDF 1.1 Concepts mapping of VocabularyTerms.ConceptIri: every concept is identified by a globally unique IRI.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-i09-e1', 'ont4-i09', 'Field', 'ExternalStandardTerms.RehomingKeptExternalNamespace', NULL, NULL, NULL, NULL, NULL, 'Fires when a deprecated FOAF personal-name term said to be re-homed still sits in FOAF''s namespace. The local copy of foaf:family_name kept http://xmlns.com/foaf/0.1/ as its namespace, so it fires; ''given name'' was moved into urn:effortless:pko-extension# and linked to foaf:givenname, the illustration done correctly, and does not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-i12-e1', 'ont4-i12', 'Field', 'VocabularyTerms.HasStructuralSenseShiftAcrossYears', NULL, NULL, NULL, NULL, NULL, 'Fires when what a term refers to changed shape after holding for about two years or more. ''release'' meant an engineer copying a tagged build from January 2024 and, since January 2026, a risk-classified change through a human gate and a pipeline, so it fires; ''rollback'', reworded within a year without structural change, does not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-i13-e1', 'ont4-i13', 'Field', 'OntologyProfiles.IsReviewOverdueForChangeRate', NULL, NULL, NULL, NULL, NULL, 'Reads each standard''s change rate (ChangeRateProfile: FOAF Dormant since 2014, schema.org FrequentDeprecation with two deprecations in two years, DCAT RecentMajorRevision in 2024) and fires when a fast-changing one has not had our dependency reviewed in 180 days. schema.org, last reviewed September 2025, fires; DCAT, reviewed June 2026, and dormant FOAF do not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-i16-e1', 'ont4-i16', 'Field', 'AiLabelingRuns.IsUngroundedSynonymSprawl', NULL, NULL, NULL, NULL, NULL, 'Fires when an ungrounded run produced values outside the canonical scheme. The ungrounded status run returned ''live'', ''shipped'', ''work in progress'' and ''retired'', so it fires; the same notes grounded in the workflow status scheme returned only active, draft and deprecated, and do not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-i17-e1', 'ont4-i17', 'Field', 'AiLabelingRuns.GroundedInNonMachineReadableScheme', NULL, NULL, NULL, NULL, NULL, 'Fires when a model was grounded in a vocabulary that is not formal and machine-accessible. The support run was grounded in a PDF glossary and still produced ''looking into it'', so it fires; the run grounded in the SKOS workflow status scheme does not. Grounding helps at scale only when the vocabulary is formal.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c30-e1', 'pkm1-c30', 'Field', 'KnowledgeTraces.ProvenanceStatement', NULL, NULL, NULL, NULL, NULL, 'Every trace states in one line the material the item came from (origin), the derivation route and deriving agent (route), and the agent who confirmed it (confirmation), e.g. loto-04b from the press-7 drawing excerpt, paraphrased by the knowledge engineer, confirmed by the plant safety officer.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c32-e1', 'pkm1-c32', 'Field', 'CollectedSourceMaterials.ExpertEffortHours', NULL, NULL, NULL, NULL, NULL, 'Each capture records the hours of domain-expert time it consumed and whose (ContributingExpert): technicians and the release manager, not knowledge modelers, spent 0.5 to 3 hours per capture; Procedures.ExpertAcquisitionHours totals the cost per procedure.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p25-e1', 'pkm1-p25', 'Field', 'ProcessMiningRuns.IsDeviationUnexplainedByPeople', NULL, NULL, NULL, NULL, NULL, 'TRUE when a mining run found non-conforming variants and no capture from people that holds the reasoning behind them complements the run. It fires on the close cutoff-bypass run (3 of 8 variants conform, nobody asked why) and not on the deployment run, whose hotfix bypass Grace Holloway explained in an interview; a mining finding left uncomplemented is exactly the breach.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p26-e1', 'pkm1-p26', 'Field', 'MinedFlowEdges.IsMinedPathRecordedAsIntentWithoutDecision', NULL, NULL, NULL, NULL, NULL, 'TRUE when a hand-off reconstructed from the event log is recorded as intended process logic with nobody having decided it should be. It fires on the deploy-05 -> deploy-04 retry loop, silently promoted from the log, and not on deploy-04 -> deploy-05 (decided by an engineer) or edges kept as Observed; the breach is mined behavior becoming indistinguishable from intent.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p29-e1', 'pkm1-p29', 'Field', 'StakeholderPerspectives.IsDissentingViewNotKeptWithSource', NULL, NULL, NULL, NULL, NULL, 'TRUE when a perspective that conflicts with another was overridden into one agreed version or is kept without the material it comes from. It fires on the release manager''s hotfix view, overridden by the auditor''s, and not on the technician and safety officer views of zero-energy verification, both retained with their sources.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-q08-e1', 'pkm1-q08', 'RoleQuestion', NULL, NULL, 'aq-pkm1-q08', NULL, NULL, NULL, 'The auditor''s question is answered per knowledge item by ProvenanceStatement (origin, route, confirmation), and HasIncompleteProvenance flags the item missing one of the three: the deploy-02 definition the wiki extractor produced, which nobody confirmed.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-q09-e1', 'pkm1-q09', 'RoleQuestion', NULL, NULL, 'aq-pkm1-q09', NULL, NULL, NULL, 'The steward''s question is answered by StakeholderPerspectives: IsInConflict marks the four views that conflict (zero-energy verification, hotfix approval), and SourceMaterial / SourceMaterialKind say which transcript, excerpt or interview each comes from.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-q13-e1', 'pkm1-q13', 'RoleQuestion', NULL, NULL, 'aq-pkm1-q13', NULL, NULL, NULL, 'IsUndocumentedPath on each mined hand-off answers where log behavior departs from intended logic: the hotfix path deploy-02 -> deploy-04 (no approval) and the deploy-05 -> deploy-04 retry, neither in StepTransitions.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-s05-e1', 'pkm1-s05', 'KnowledgeMethod', NULL, NULL, NULL, NULL, 'ProcessMining', NULL, 'Applied by MethodApplications ma13-process-mining-deploy to the CI/CD event log; its output is the mined event trace material and the MinedFlowEdges, and IsDeviationUnexplainedByPeople records that it is a partial aid that needs capture from people.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c19-e1', 'pkm2-c19', 'Table', NULL, 'MinedFlowEdges', NULL, NULL, NULL, NULL, 'One row per step-to-step hand-off rebuilt from the CI/CD event log by a mining run, with the cases that took it and their wait times: the actual flow of the deployment process.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c20-e1', 'pkm2-c20', 'Field', 'MinedFlowEdges.IsUndocumentedPath', NULL, NULL, NULL, NULL, NULL, 'TRUE for a reconstructed hand-off that no documented transition matches: the deviation between the documented deployment procedure and the flow rebuilt from its event log.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c21-e1', 'pkm2-c21', 'Field', 'MinedFlowEdges.IsBottleneck', NULL, NULL, NULL, NULL, NULL, 'TRUE where mined cases wait more than four times the entered step''s documented duration: cases sit a day (1440 minutes) before the fifteen-minute release approval gate.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c22-e1', 'pkm2-c22', 'Field', 'CollectedSourceMaterials.HoldsReasoningOrTacitKnowledge', NULL, NULL, NULL, NULL, NULL, 'Each collected material records whether it holds the reasoning or tacit knowledge behind the actions. The mined deployment event trace reads FALSE (it holds only system events) while the interview and field-note captures read TRUE; the mining-complement witness counts only the latter.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c24-e1', 'pkm2-c24', 'Field', 'CollectedSourceMaterials.SourceDocument', NULL, NULL, NULL, NULL, NULL, 'Collected excerpts name the existing document they were taken from: the deployment runbook, the 2019 lockout SOP and the press-7 retrofit drawing notes.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

