VALUES ('pkm2-c25-e1', 'pkm2-c25', 'Field', 'KnowledgeTraces.PrescribedVersusEnacted', NULL, NULL, NULL, NULL, NULL, 'For a trace where practice evidence contradicts a document, states what the document prescribes against what was enacted: the runbook requires recorded approval, the event log shows three hotfixes rolled out with no approval event.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

