VALUES ('pkm2-p32-e1', 'pkm2-p32', 'Field', 'CollectedSourceMaterials.IsDependencyInvisibleToChange', NULL, NULL, NULL, NULL, NULL, 'TRUE when a material was encoded into a model but no trace records which knowledge rests on it, so a change to it reveals nothing. It fires on the conveyor manual roller excerpt encoded into convmaint-v1.0.0 and not on the lockout and deployment materials, whose dependents HasKnowledgeAffectedBySourceChange reveals when their document is revised.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

