VALUES ('pkm3-q11-e1', 'pkm3-q11', 'RoleQuestion', NULL, NULL, 'aq-pkm3-q11', NULL, NULL, NULL, 'IssueOccurrences answer how the procedure failed and how it was recorded (Error, IssueCause, encountering agent); RedesignChangeRequest and ImprovementCyclePath give the redesign; IsFailureWithoutLandedRedesign marks the three failures with no landed redesign.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-q13-e1', 'pkm4-q13', 'RoleQuestion', NULL, NULL, 'aq-pkm4-q13', NULL, NULL, NULL, 'IsDocumentedBehindPractice marks deploy-v3.2.0, whose runbook is contradicted by practice evidence collected after its last revision; PrescribedVersusEnacted says how.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c16-e1', 'pkm1-c16', 'Field', 'KnowledgeTransfers.IsTraditionalChannel', NULL, NULL, NULL, NULL, NULL, 'TRUE for a recorded transfer that went through a document, a training program or mentoring: the release notes Grace documented for Leo, the lockout training Lin gave Aisha, and Walter''s and Tomas''s mentoring.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c35-e1', 'pkm1-c35', 'Table', NULL, 'KnowledgeWorkforcePositions', NULL, NULL, NULL, NULL, 'Each row is a position an organization budgets specifically for knowledge engineering, information architecture or ontology work: roles devoted to managing process knowledge.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-c36-e1', 'pkm1-c36', 'Table', NULL, 'SharingRecognitions', NULL, NULL, NULL, NULL, 'Each row is an incentive given for sharing knowledge: the plant''s teaching award to Tomas for training apprentices and a cluster peer award to Joao for spreading servo timing practice.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p08-e1', 'pkm1-p08', 'Field', 'Procedures.HasDecayedTransferChannel', NULL, NULL, NULL, NULL, NULL, 'Detects both kinds of decay the claim names: TRUE when a procedure''s repository entry is past its review interval or some of its know-how is held only by someone who left with nothing transferred or captured. It fires on production deployment (stale go/no-go notes and a departed SRE''s health-check judgment) and customer incident response (a departed incident lead''s triage heuristics), and is FALSE on the other eight procedures.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p36-e1', 'pkm1-p36', 'Field', 'Procedures.HasUnengagedStakeholder', NULL, NULL, NULL, NULL, NULL, 'TRUE when a stakeholder department of a procedure was never engaged in shaping its knowledge. It fires on production deployment, whose compliance stakeholder was never engaged, and is FALSE on lockout/tagout, where maintenance and production were both engaged; an unengaged stakeholder is exactly the breach the prescription forbids.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p37-e1', 'pkm1-p37', 'Field', 'KnowledgeRepositoryEntries.IsUncreditedExpertKnowHow', NULL, NULL, NULL, NULL, NULL, 'TRUE when an entry records another person''s expertise without crediting them. It fires on the lockout quick reference card Lin wrote from Ken''s know-how without naming him, and is FALSE on entries that credit their source or record the author''s own expertise.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p38-e1', 'pkm1-p38', 'Field', 'DepartmentProcessAccounts.IsUnresolvedDisagreement', NULL, NULL, NULL, NULL, NULL, 'TRUE when two departments give contradicting accounts of the same process and no resolution practice was used. Engineering''s and customer support''s accounts of deployment rollback fire; the maintenance/production conflict over bleed time, settled by a timed joint walk-down, does not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm1-p39-e1', 'pkm1-p39', 'Field', 'Organizations.MemoryLeavesWithStaff', NULL, NULL, NULL, NULL, NULL, 'TRUE when some know-how of people who left was neither transferred nor captured, so the organization''s memory did not stay intact through turnover. acme-engineering fires (two of three departed carriers'' know-how lost); acme-plant does not, because Walter''s die-shim know-how passed to Ken before he retired.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c32-e1', 'pkm2-c32', 'Field', 'Agents.IsBoundarySpanner', NULL, NULL, NULL, NULL, NULL, 'TRUE for a person who belongs to two or more communities of practice: Lin (maintenance guild and portal community), Ken (maintenance guild and Riverbend cluster) and Joao (Riverbend and Eastvale clusters).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c33-e1', 'pkm2-c33', 'Field', 'Agents.LocatedKnowHowCount', NULL, NULL, NULL, NULL, NULL, 'Counts know-how held by someone else that a broker can point seekers to. Lin knows that the Press 7 bleed-down know-how lives with Tomas without holding it herself: meta-knowledge of where process knowledge sits.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c34-e1', 'pkm2-c34', 'Field', 'CommunitiesOfPractice.HasOwnVocabularyAndNorms', NULL, NULL, NULL, NULL, NULL, 'TRUE for a community that speaks its own vocabulary and states its own norms: the maintenance guild (lockout vocabulary; deviations talked through at the Friday huddle) and the release guild (release vocabulary; a written note for every rollback).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c35-e1', 'pkm2-c35', 'Field', 'KnowledgeBrokerLinks.TranslationBetweenVocabularies', NULL, NULL, NULL, NULL, NULL, 'The broker''s translation between the words of the two communities a link connects, e.g. production''s ''line stop'' (plant quality vocabulary) = maintenance''s ''energy isolation'' (lockout vocabulary), and support''s ''outage'' = release engineering''s ''rollback''.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c36-e1', 'pkm2-c36', 'Field', 'SourceRelationships.WithholdingMotive', NULL, NULL, NULL, NULL, NULL, 'Records why a source holds information back: Ken fears documenting his die-shim tricks makes him replaceable (job security); Grace guards the go/no-go judgment that gives her release authority (status).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c37-e1', 'pkm2-c37', 'Field', 'DepartmentProcessAccounts.ShapingInterest', NULL, NULL, NULL, NULL, NULL, 'Each department''s account of a process carries the interest that shapes it: maintenance''s twenty-minute bleed is shaped by technician safety, production''s five minutes by uptime targets; engineering''s ten-minute rollback by release velocity, support''s hour of errors by incident load.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c38-e1', 'pkm2-c38', 'Field', 'SourceRelationships.TrustLevel', NULL, NULL, NULL, NULL, NULL, 'The state of trust between the knowledge engineer and each source: Established with Tomas and Lin, Building with Grace, Low with Ken.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-c39-e1', 'pkm2-c39', 'Field', 'SourceRelationships.PowerDynamic', NULL, NULL, NULL, NULL, NULL, 'The power dynamic shaping what each source shares: Tomas outranks the engineer, Grace''s sessions had a supervisor present, Ken''s knowledge is threatened by automation, Lin''s relationship is balanced.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-p15-e1', 'pkm2-p15', 'Field', 'KnowHowCarriers.IsOverlookedLivingHolder', NULL, NULL, NULL, NULL, NULL, 'TRUE when uncaptured know-how is carried by someone still in a role whom no collection relationship has approached on that procedure. It fires on Tomas''s improvised press setup, Ken''s belt-drift diagnosis and Lin''s forklift checks, and is FALSE on Tomas''s bleed-down know-how, which a knowledge engineer is collecting from him: collection that follows documents rather than the social holder breaks the claim.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-p16-e1', 'pkm2-p16', 'Field', 'Agents.IsUnidentifiedBoundarySpanner', NULL, NULL, NULL, NULL, NULL, 'TRUE when a person who connects two communities was never identified by a social network analysis. The plant analysis found Lin, so she reads FALSE; Ken (maintenance guild and Riverbend cluster) and Joao (two clusters) connect groups and no analysis found them.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-p17-e1', 'pkm2-p17', 'Field', 'SourceRelationships.IsUnnegotiatedPowerGap', NULL, NULL, NULL, NULL, NULL, 'TRUE when a power imbalance shapes a source relationship and nothing was negotiated about how the knowledge is collected and used. It fires on Ken, whose job is threatened by automation, and is FALSE on Tomas and Grace, where review rights and supervisor-free sessions were negotiated, and on Lin''s balanced relationship.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-p18-e1', 'pkm2-p18', 'Field', 'SourceRelationships.IsExtractiveRelationship', NULL, NULL, NULL, NULL, NULL, 'TRUE when trust with a source is not established and the engineer records no trust-building practice. It fires on Grace (trust still building, nothing done to build it) and is FALSE on Ken, whose low trust is being addressed by returning transcripts, and on the established relationships.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm2-p78-e1', 'pkm2-p78', 'Field', 'Procedures.IsCapturedByAutomationAlone', NULL, NULL, NULL, NULL, NULL, 'TRUE when a procedure''s knowledge was captured by machine-authored entries and no practitioner relationship exists. Conveyor maintenance fires (only a copilot summary of vendor manuals); lockout/tagout, captured through relationships with Tomas and Lin, does not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

