VALUES ('pkm2-q06-e1', 'pkm2-q06', 'RoleQuestion', NULL, NULL, 'aq-pkm2-q06', NULL, NULL, NULL, 'A knowledge engineer asks who holds each piece of know-how; KnowHowCarriers.IsHeldByCurrentPractitioner answers it per carrier, TRUE for know-how carried by a person still in a role and FALSE for plants, systems and people who left.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

