VALUES ('pkm2-q07-e1', 'pkm2-q07', 'RoleQuestion', NULL, NULL, 'aq-pkm2-q07', NULL, NULL, NULL, 'A knowledge engineer asks who knows where know-how is held; KnowledgeBrokerLinks.LocatesOtherHolder is TRUE when a broker points a seeker to know-how someone else carries (Lin pointing Aisha to Tomas).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

