VALUES ('pkm3-q10-e1', 'pkm3-q10', 'RoleQuestion', NULL, NULL, 'aq-pkm3-q10', NULL, NULL, NULL, 'The VP asks what would be relearned if the current team left; KnowHowCarriers.MustBeRelearnedIfHolderLeaves is TRUE for know-how carried by a serving person with nothing captured for a successor.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

