VALUES ('pkm3-i04-e1', 'pkm3-i04', 'Field', 'Organizations.ErodedInStages', NULL, NULL, NULL, NULL, NULL, 'TRUE when facility investment declined, then engineer training after it, then upkeep of how-to-make knowledge after that. acme-plant fires (tooling budget frozen 2011, engineer rotation cut 2015, how-to-make binders abandoned 2020); acme-engineering''s isolated training pause does not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm3-i05-e1', 'pkm3-i05', 'Field', 'CommunitiesOfPractice.IsCrossFirmPracticeCluster', NULL, NULL, NULL, NULL, NULL, 'TRUE when members from several firms share practice, know-how moves with people changing employers, and specialists are at hand. The Riverbend press cluster fires (members from two supplier firms, Joao''s move, Petra as specialist); single-firm guilds do not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm3-i06-e1', 'pkm3-i06', 'Field', 'ProblemOccurrences.IsTurnoverRegression', NULL, NULL, NULL, NULL, NULL, 'TRUE when a fix that was never recorded comes back after the person who made it left. The contractor who fixed stale CDN assets in 2025 left without a note, and the bug returned in May 2026; the Press 7 bleed stall, whose fix was recorded, does not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm3-i07-e1', 'pkm3-i07', 'Field', 'CommunitiesOfPractice.IsCirculationEndingForLackOfApprentices', NULL, NULL, NULL, NULL, NULL, 'TRUE when know-how circulates through people moving between firms but offered apprenticeship places have gone unfilled for three years. The Eastvale packaging cluster fires (Petra''s move, four open places, last apprentice in 2014); Riverbend, with no unfilled places, does not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm3-i08-e1', 'pkm3-i08', 'Field', 'CommunitiesOfPractice.HasAmbientTradeKnowHow', NULL, NULL, NULL, NULL, NULL, 'TRUE when a trade concentrated in one place passes its know-how even to people who do not practise it. Riverbend fires: Nina, a school leaver with no role, absorbed servo timing by growing up among the works; no other community records such absorption.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm3-i09-e1', 'pkm3-i09', 'Field', 'Organizations.HoldsKnowHowInPeoplePlantsAndSystems', NULL, NULL, NULL, NULL, NULL, 'TRUE when an organization''s how-to-build knowledge is carried at once by people, plants and systems. acme-plant fires (technicians, the Plant North isolation layout, the PLC interlock logic); acme-engineering, whose know-how is carried only by people, does not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-p04-e1', 'pkm4-p04', 'Field', 'Procedures.HasTransferShortfallExposure', NULL, NULL, NULL, NULL, NULL, 'TRUE when a wave of three or more new starters meets untransferred veteran know-how, or a veteran about to leave carries untransferred know-how. Lockout/tagout fires on both counts: Aisha, Bea and Carlos started within 180 days and Tomas retires on 2026-09-30 with his bleed-down know-how untransferred. No other procedure is exposed.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-p05-e1', 'pkm4-p05', 'Field', 'KnowHowCarriers.TransferStopsWithoutVeteran', NULL, NULL, NULL, NULL, NULL, 'TRUE when a serving veteran''s know-how has only been passed person to person and nothing is captured, so the next newcomer still needs that veteran. Tomas''s improvised press setup, taught only to Aisha, fires; Grace''s go/no-go judgment, also written into the repository, does not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-p08-e1', 'pkm4-p08', 'Field', 'Procedures.FormalizationDoesNotEaseOnboarding', NULL, NULL, NULL, NULL, NULL, 'TRUE when starters who learned from captured knowledge took at least as long to reach proficiency as those who did not. Production deployment fires (55 days with the stale go/no-go notes against 40 without); lockout/tagout, where captured knowledge cut onboarding from 70 to 21 days, does not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm4-q14-e1', 'pkm4-q14', 'RoleQuestion', NULL, NULL, 'aq-pkm4-q14', NULL, NULL, NULL, 'The plant operations manager asks which know-how only veterans hold unpassed, and whether they are leaving; KnowHowCarriers.IsUntransferredVeteranKnowHow and IsAtRiskOfImminentLoss answer it, TRUE for Tomas''s bleed-down know-how (retiring in 73 days) and, without the departure, Lin''s checks.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm3-c06-e1', 'pkm3-c06', 'Field', 'SourcingFunctions.IsBusinessProcessOutsourcing', NULL, NULL, NULL, NULL, NULL, 'TRUE for a function a provider performs whose work is routine and transactional; it fires on accounts payable invoice processing sent to Harborline and on nothing expertise-heavy.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

