VALUES ('pkm3-c07-e1', 'pkm3-c07', 'Field', 'SourcingFunctions.IsKnowledgeProcessOutsourcing', NULL, NULL, NULL, NULL, NULL, 'TRUE for a function a provider performs whose work is expertise-heavy: appliance process engineering, safety regulatory research, acquisition due-diligence analysis, press overhaul and classifier training.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

