VALUES ('pkm3-c09-e1', 'pkm3-c09', 'Field', 'SourcingFunctions.ClaimsHowWithoutDoing', NULL, NULL, NULL, NULL, NULL, 'The model records who holds the how of a function separately from who executes it, and flags a declaration that the client holds the method while a provider does the work: acme-engineering says it holds classifier training know-how while Northstar trains the model, and its own audit rates the in-house level 1 of the 3 needed.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

