VALUES ('pkm3-p03-e1', 'pkm3-p03', 'Field', 'ProviderEngagements.IsUnplannedKnowledgeReturn', NULL, NULL, NULL, NULL, NULL, 'Fires when an audit shows the client relies on a provider''s knowledge, the provider keeps the documentation as its own property, and the engagement records no plan for how the knowledge comes back: Meridian, Quillstone and Northstar; it does not fire on Baxter, whose documentation is joint and whose return plan is recorded.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('pkm3-p11-e1', 'pkm3-p11', 'Field', 'KnowledgeAudits.TreatsDeficitAsCostProblem', NULL, NULL, NULL, NULL, NULL, 'Fires when an audit finds knowledge shortfalls but frames them as a cost and efficiency problem rather than a knowledge deficit: the 2025 Home Brands supplier review found two dependencies and filed them as cost; the plant and engineering audits acknowledge a deficit, and the 2024 corporate cost review found no shortfall.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

