VALUES ('pkm3-p12-e1', 'pkm3-p12', 'Field', 'SourcingFunctions.IsUnauditedFunction', NULL, NULL, NULL, NULL, NULL, 'Fires for an outsourced or strategically vital function that no audit has compared held against needed knowledge for: invoice processing at Harborline and the heating element R&D; audited functions do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

