VALUES ('pkm3-p13-e1', 'pkm3-p13', 'Field', 'KnowledgeAuditItems.IsUnnamedFinding', NULL, NULL, NULL, NULL, NULL, 'Fires for an audit finding (gap or dependency) that no knowledge gap row names: the two Home Brands dependencies; the plant and engineering findings are each named as a knowledge gap.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

