VALUES ('pkm3-p14-e1', 'pkm3-p14', 'Field', 'Organizations.HasKnowledgeFindingsWithoutKnowledgeStaff', NULL, NULL, NULL, NULL, NULL, 'Fires for an organization whose audits found shortfalls while it has no filled knowledge engineer, information architect or ontologist position: ACME Home Brands, whose knowledge engineer position was never budgeted; the plant and engineering have filled positions.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

