VALUES ('pkm3-p21-e1', 'pkm3-p21', 'Field', 'ProviderEngagements.IsOneWayLearning', NULL, NULL, NULL, NULL, NULL, 'Fires for a running engagement with knowledge deliverables where knowledge has actually been delivered in only one direction: Quillstone (digests to the client only) and Northstar (change history to the provider only); Harborline, Baxter and Lattice deliver both ways.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

