VALUES ('pkm3-p22-e1', 'pkm3-p22', 'Field', 'ProviderEngagements.IsShortTermWithoutJointKnowledge', NULL, NULL, NULL, NULL, NULL, 'Fires for a running engagement contracted for under three years that builds no knowledge asset jointly, i.e. a provider treated transactionally rather than as a long-term partner: Meridian, Quillstone and Northstar; Baxter (60 months, shared failure-mode catalog) and Lattice (48 months, joint playbook) do not.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

