VALUES ('ont4-c50-e1', 'ont4-c50', 'Field', 'AssignmentUpdatePolicies.UpdateSlaHours', NULL, NULL, NULL, NULL, NULL, 'Each assignment-update policy for roles operational systems route from states the hours within which an update must be completed (24 for release approvers, 72 for AI agent fills, 0 where none is defined).', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-p70-e1', 'ont4-p70', 'Field', 'AiRegistryModelVersions.IsLiveButUnregisteredInGraph', NULL, NULL, NULL, NULL, NULL, 'Fires for a model version running in production that no agent individual in the graph represents: release-notes-writer 1.1.0; the risk classifier versions and health checker are individuals, and the retired 2.3.0 is not live.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-p71-e1', 'ont4-p71', 'Field', 'AgentUpgradeAssessments.MissedTraversedImpact', NULL, NULL, NULL, NULL, NULL, 'Fires when an upgrade assessment lists fewer affected steps than the traversal of the artifact-flow closure finds: the hand-written change ticket for 2.4.1 -> 2.5.0 listed only the release gate while traversal reaches deploy-03, deploy-04 and deploy-05; the traversal-based assessment does not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-p72-e1', 'ont4-p72', 'Field', 'Agents.IsAiAgentNotFilledFromRegistry', NULL, NULL, NULL, NULL, NULL, 'Fires for an AI agent individual whose identifier and version are not supplied by a registry record through dct:identifier and dct:hasVersion: the 2.5.0 candidate typed in as 2.5.0 while the registry says 2.5.0-rc3, and two AI agents entered by hand; the 2.4.0, 2.4.1 and health-check individuals match the feed.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-p73-e1', 'ont4-p73', 'Field', 'RoleAssignmentUpdateTasks.LacksNamedTriggerOwner', NULL, NULL, NULL, NULL, NULL, 'Fires when the governing policy names no role responsible for triggering an assignment update, or names one nobody holds: every update under the engineering operations policy, including the SRE departure nobody triggered; updates under the release approver and AI agent policies (owner: VP of engineering) do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-p74-e1', 'ont4-p74', 'Field', 'RoleAssignmentUpdateTasks.ExceededUpdateSla', NULL, NULL, NULL, NULL, NULL, 'Fires when no service level is defined or the update took longer than it allows: the hotfix release manager''s departure was recorded 307 hours after he left against a 24-hour service level; the 2.4.1 classifier swap finished in 39 of 72 hours and does not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-p75-e1', 'ont4-p75', 'Field', 'RoleAssignmentUpdateTasks.ChangedRoleInsteadOfAssignment', NULL, NULL, NULL, NULL, NULL, 'Fires when a change of who does the work replaced an assignment of one role with an assignment of a different role, so the steps had to be re-pointed: build and rollout moved from Hector Ruiz''s Build and Release Engineer role to a new Deployment Automation role; the classifier swap and the AI-to-human SRE handover changed only the assignment.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

