VALUES ('ont4-p76-e1', 'ont4-p76', 'Field', 'AssignmentRoutedNotices.RoutedAroundModel', NULL, NULL, NULL, NULL, NULL, 'Fires for a notice routed from a separately maintained list that reached someone the model''s assignments did not name for the step''s role when it was sent: the ops spreadsheet sent the 2026-03-01 health verification notice to the VP while Leo Marchetti held the SRE role; notices read from assignments do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

