VALUES ('ont4-p77-e1', 'ont4-p77', 'Field', 'RoleAssignmentUpdateTasks.MissedNextDependentRun', NULL, NULL, NULL, NULL, NULL, 'Fires when a run needing the role started after the person left and before the assignment change was recorded: the 2026-07-14 hotfix ran after Dmitri Volkov (release manager), Leo Marchetti (SRE) and Kwame Asante (rollout) left and before any of those updates; the classifier swap and the SRE handover were recorded before their next runs.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

