INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-i05-e1', 'ont4-i05', 'Field', 'RoleAssignmentUpdateTasks.StaleAssignmentBrokeRouting', NULL, NULL, NULL, NULL, NULL, 'Separates a stale assignment that only made the model inaccurate from one that broke operations: it fires when the assignment was still stale at a run that needed it and that run''s notice for the role reached the wrong person or nobody (the release manager and SRE departures before the 2026-07-14 hotfix), and not for the rollout operator''s departure, equally stale at that run but routed nothing.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

