VALUES ('ont4-i23-e1', 'ont4-i23', 'Field', 'AiModelDeployments.IsIsolatedRegistryFact', NULL, NULL, NULL, NULL, NULL, 'Fires for a live production deployment whose agent fills no role and has no attributed artifact in the graph: the release-notes writer is a registry row and nothing more, while the live 2.4.1 classifier deployment is connected to its role assignment and risk reports.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

INSERT INTO claim_evidence (claim_evidence_id, article_claim, evidence_kind, rulebook_field, rulebook_table, role_question, ontology_profile, knowledge_method, procedure, justification, semantic_type_iri)
VALUES ('ont4-i24-e1', 'ont4-i24', 'Field', 'AssignmentRoutedNotices.ReachedWrongPersonOrNobody', NULL, NULL, NULL, NULL, NULL, 'Fires when a notice went to someone who did not hold the step''s role when it was sent, or to nobody: the hotfix approval notice went to Dmitri Volkov eleven days after he left, the hotfix health verification notice went to nobody, and the spreadsheet sent one to the VP; notices to Grace Holloway and to Leo Marchetti while he held the role do not fire.', 'urn:effortless:pko-extension#ClaimEvidence') ON CONFLICT (claim_evidence_id) DO UPDATE SET article_claim = EXCLUDED.article_claim, evidence_kind = EXCLUDED.evidence_kind, rulebook_field = EXCLUDED.rulebook_field, rulebook_table = EXCLUDED.rulebook_table, role_question = EXCLUDED.role_question, ontology_profile = EXCLUDED.ontology_profile, knowledge_method = EXCLUDED.knowledge_method, procedure = EXCLUDED.procedure, justification = EXCLUDED.justification, semantic_type_iri = EXCLUDED.semantic_type_iri;

